local config = {
  ui_story_5053_50530001_1_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5053_50530001_2_dialog_content = "...",
  ui_story_5053_50530001_3_dialog_content = "Come quickly, PlayerName.",
  ui_story_5053_50530001_4_dialog_content = "And you are?",
  ui_story_5053_50530001_5_dialog_content = "You... forgot my name?",
  ui_story_5053_50530001_6_dialog_content = "I don't blame you. I've been told my name is a bit of a mouthful.",
  ui_story_5053_50530001_7_dialog_content = "Veronica, my name is Veronica. You can also call me Vonnie.",
  ui_story_5053_50530001_8_dialog_content = "My sister and mother are waiting in the garden. We should go.",
  ui_story_5053_50530001_9_option_content = "Okay.",
  ui_story_5053_50530001_10_dialog_content = "See, I knew Carleen would be here.",
  ui_story_5053_50530001_11_dialog_content = "Can I ask you a favor, PlayerName? I'll cover Carleen's eyes, and you'll...",
  ui_story_5053_50530001_12_dialog_content = "Huh?!",
  ui_story_5053_50530001_13_dialog_content = "Guess who?",
  ui_story_5053_50530001_14_dialog_content = "I've never heard your voice before!",
  ui_story_5053_50530001_15_dialog_content = "D-Despicable! Who speaks? And how dare you prank me like this?",
  ui_story_5053_50530001_16_dialog_content = "Where's my lance? Hey, let go, I can't find my lance!",
  ui_story_5053_50530001_17_dialog_content = "*Giggles*",
  ui_story_5053_50530001_18_dialog_content = "Wait, your hands feel so familiar...",
  ui_story_5053_50530001_19_dialog_content = "Sister? Is that Veronica?",
  ui_story_5053_50530001_20_dialog_content = "Do I sound like your sister?",
  ui_story_5053_50530001_21_dialog_content = "I don't know who you are, but I know the person behind me is my sister!",
  ui_story_5053_50530001_22_dialog_content = "I see I can't fool you with this.",
  ui_story_5053_50530001_23_dialog_content = "It's really you! You're back!",
  ui_story_5053_50530001_24_dialog_content = "But who's the suspicious person next to you?",
  ui_story_5053_50530001_25_dialog_content = "This is PlayerName. We'll both hang out with you from now on, is that alright?",
  ui_story_5053_50530001_26_dialog_content = "...",
  ui_story_5053_50530001_27_dialog_content = "How about saying hello to PlayerName, Carleen?",
  ui_story_5053_50530001_28_dialog_content = "How do you do... big brother.",
  ui_story_5053_50530001_29_dialog_content = "Don't read too much into it, PlayerName. Carleen might act like a grownup...",
  ui_story_5053_50530001_30_dialog_content = "... but once you spend some time with her, you'll find she's actually quite a shy kid.",
  ui_story_5053_50530001_31_dialog_content = "Mother!",
  ui_story_5053_50530001_32_dialog_content = "All right, it's getting late. Time for us to set off.",
  ui_story_5053_50530001_33_dialog_content = "Are you ready, PlayerName?",
  ui_story_5053_50530001_34_option_content = "What, me?",
  ui_story_5053_50530001_35_dialog_content = "Look, the parade is coming this way!",
  ui_story_5053_50530001_36_dialog_content = "Watch your posture, smile, look forward... Yes, good job.",
  ui_story_5053_50530001_37_dialog_content = "I-I'm still somewhat nervous.",
  ui_story_5053_50530001_38_dialog_content = "Relax! Everyone just wants to greet us, that's all.",
  ui_story_5053_50530001_39_dialog_content = "Still doing fine, Veronica?",
  ui_story_5053_50530001_40_dialog_content = "I'm fine, Father... I'll show Lumopolis my best self!",
  ui_story_5053_50530001_41_dialog_content = "I believe you, but tell me if you aren't feeling well.",
  ui_story_5053_50530001_42_dialog_content = "... Yes!",
  ui_story_5053_50530001_43_dialog_content = "See how great and valiant the City Lord is!",
  ui_story_5053_50530001_44_dialog_content = "See how gentle and compassionate the Chatelaine is!",
  ui_story_5053_50530001_45_dialog_content = "See how graceful the princesses are!",
  ui_story_5053_50530001_46_dialog_content = "But who's the stranger behind them?",
  ui_story_5053_50530001_47_dialog_content = "Is there such a person in the Schwartz family?",
  ui_story_5053_50530001_48_dialog_content = "\"Is there such a person\"... ?",
  ui_story_5053_50530001_49_dialog_content = "Uh, no, it's not like that.",
  ui_story_5053_50530001_50_dialog_content = "This way, please, PlayerName!",
  ui_story_5053_50530001_51_dialog_content = "What's going on?",
  ui_story_5053_50530001_52_dialog_content = "Father is off to pacify the insurgents and I'm worried...",
  ui_story_5053_50530001_53_dialog_content = "Can you come with me to help him?",
  ui_story_5053_50530001_54_option_content = "Sure, let's go!",
  ui_story_5053_50530001_55_dialog_content = "Father...",
  ui_story_5053_50530001_56_dialog_content = "Over there!",
  ui_story_5053_50530001_57_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5053_50530001_58_dialog_content = "The wind's kicking up? This feels familiar...",
  ui_story_5053_50530001_59_dialog_content = "What do we do now, PlayerName?",
  ui_story_5053_50530001_60_dialog_content = "Don't worry, if the City Lord can take advantage of the wind, the battle will be over soon.",
  ui_story_5053_50530001_61_dialog_content = "I-I must tell Father about that!",
  ui_story_5053_50530001_62_dialog_content = "Don't rush, I'll show you the way!",
  ui_story_5053_50530001_63_dialog_content = "Veronica never mentioned to me that you have command skills.",
  ui_story_5053_50530001_64_dialog_content = "You must be a Caelestite, right?",
  ui_story_5053_50530001_65_dialog_content = "Y-Yes. I didn't mean to hide that from you.",
  ui_story_5053_50530001_66_dialog_content = "Worry not, youngster, I am not berating you. In fact, thanks to you, this battle ended quickly.",
  ui_story_5053_50530001_67_dialog_content = "Come join us for a feast back home.",
  ui_story_5053_50530001_68_option_content = "Okay!",
  ui_story_5053_50530001_69_dialog_content = "Where did Carleen go...",
  ui_story_5053_50530001_70_dialog_content = "Could she still be in her room?",
  ui_story_5053_50530001_71_dialog_content = "You think so? Then I should go check on her.",
  ui_story_5053_50530001_72_dialog_content = "Why don't you chat with my parents in the meantime, PlayerName.",
  ui_story_5053_50530001_73_dialog_content = "Hahahahaha, you're the great City Lord. Why do you still love telling bad jokes so much?",
  ui_story_5053_50530001_74_dialog_content = "See, you've stunned even PlayerName into silence.",
  ui_story_5053_50530001_75_dialog_content = "How long have you been sitting here, PlayerName?",
  ui_story_5053_50530001_76_dialog_content = "Children should not eavesdrop on adult conversations.",
  ui_story_5053_50530001_77_dialog_content = "I-I heard nothing!",
  ui_story_5053_50530001_78_dialog_content = "Haha, are you sure?",
  ui_story_5053_50530001_79_dialog_content = "Stop teasing, his face is turning red.",
  ui_story_5053_50530001_80_dialog_content = "Don't you have important news, Daniel?",
  ui_story_5053_50530001_81_dialog_content = "Right, speaking of that...",
  ui_story_5053_50530001_82_dialog_content = "I need you to be prepared for what I am about to tell you, PlayerName.",
  ui_story_5053_50530001_83_dialog_content = "Okay...",
  ui_story_5053_50530001_84_dialog_content = "Your parents and people did not perish.",
  ui_story_5053_50530001_85_dialog_content = "They survived just barely all those years ago, and settled in secret on a secluded piece of land belonging to the Schwartz family.",
  ui_story_5053_50530001_86_dialog_content = "I notified them to come to see you. They should be here anytime now.",
  ui_story_5053_50530001_87_dialog_content = "...",
  ui_story_5053_50530001_88_dialog_content = "Do you understand what I'm saying, PlayerName?",
  ui_story_5053_50530001_89_dialog_content = "What's the matter? Why are your eyes glazing over?",
  ui_story_5053_50530001_90_dialog_content = "PlayerName? PlayerName!",
  ui_story_5053_50530001_91_dialog_content = "<color=#e8d9bb>Slap!</color>",
  ui_story_5053_50530001_92_dialog_content = "PlayerName!!!",
  ui_story_5053_50530001_93_dialog_content = "My face... That hurts...",
  ui_story_5053_50530001_94_dialog_content = "Finally, a response.",
  ui_story_5053_50530001_95_dialog_content = "My parents and kin! Where are they?!",
  ui_story_5053_50530001_96_dialog_content = "Was all of that not real...?",
  ui_story_5053_50530001_97_dialog_content = "You seem rather dejected, young one.",
  ui_story_5053_50530001_98_dialog_content = "Even though I know it wasn't real, I still would like to see my family...",
  ui_story_5053_50530001_99_dialog_content = "Miring in a bogus past is never a good thing. Focus on the present, PlayerName!",
  ui_story_5053_50530001_100_dialog_content = "The present? Where am I...?",
  ui_story_5053_50530001_101_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5053_50530001_102_dialog_content = "Are those clock bells...? I remember now!",
  ui_story_5053_50530001_103_dialog_content = "We just fought a monster that came out of nowhere until the day was almost over...",
  ui_story_5053_50530001_104_dialog_content = "The clock is about to strike twelve!",
  ui_story_5053_50530001_105_dialog_content = "I already said, it's futile.",
  ui_story_5053_50530001_106_dialog_content = "Wait, maybe we can still make it!",
  ui_story_5053_50530001_107_dialog_content = "Give me the Crystal, Caleb!",
  ui_story_5053_50530001_108_dialog_content = "Reditus, reditus, reditus!",
  ui_story_5053_50530001_109_dialog_content = "Ad praessence!",
  ui_story_5053_50530001_110_dialog_content = "Rewind to the beginning, let us return to reality!",
  ui_story_5053_50530001_111_dialog_content = "Abracadabra!",
  ui_story_5053_50530001_112_dialog_content = "Ugh!",
  ui_story_5053_50530001_113_dialog_content = "Here it comes again... The topsy-turvy feeling...",
  ui_story_5053_50530001_114_dialog_content = "Everybody hold on tight and don't let go!",
  ui_story_5053_50530001_115_dialog_content = "Come to me, Mia, PlayerName!",
  ui_story_5053_50530001_116_dialog_content = "Oh, no, I can't hold on to Caleb!",
  ui_story_5053_50530001_117_dialog_content = "Sorry, my sister, I can't be with you anymore...",
  ui_story_5053_50530001_118_dialog_content = "We can't... leave anyone behind!",
  ui_story_5053_50530001_119_dialog_content = "PlayerName?!",
  ui_story_5053_50530001_120_dialog_content = "Caleb!",
  ui_story_5053_50530001_121_option_content = "Grab my hand!",
  ui_story_5053_50530001_122_dialog_content = "Agh!",
  ui_story_5053_50530001_123_dialog_content = "Stop stretching, PlayerName. My father's losing his grip on you!",
  ui_story_5053_50530001_124_option_content = "I can't give up!",
  ui_story_5053_50530001_125_dialog_content = "PlayerName!!!",
  ui_story_5053_50530001_126_dialog_content = "Gotcha! I got Caleb!",
  ui_story_5053_50530001_127_dialog_content = "PlayerName...?",
  ui_story_5053_50530101_1_dialog_content = "<color=#e8d9bb>Chirp, chirp!</color>",
  ui_story_5053_50530101_2_dialog_content = "(Is that birds I hear?)",
  ui_story_5053_50530101_3_dialog_content = "(The birds in Eraveil always woke me up early. I couldn't even sleep in.)",
  ui_story_5053_50530101_4_dialog_content = "(But...)",
  ui_story_5053_50530101_5_dialog_content = "(Why am I lying on grass?!)",
  ui_story_5053_50530101_6_dialog_content = "(No, this is not Eraveil... This is Lumopolis?!)",
  ui_story_5053_50530101_7_dialog_content = "(That's right, I'm in Lumopolis! Mia and I went into the Crystal of Eternal Memory, and then...)",
  ui_story_5053_50530101_8_dialog_content = "(We made it out at the last second!)",
  ui_story_5053_50530101_9_dialog_content = "...",
  ui_story_5053_50530101_10_dialog_content = "Mia?",
  ui_story_5053_50530101_11_dialog_content = "...",
  ui_story_5053_50530101_12_dialog_content = "...",
  ui_story_5053_50530101_13_dialog_content = "Jakine! Caleb! Everybody...",
  ui_story_5053_50530101_14_dialog_content = "<size=30>Keep your voice down.</size>",
  ui_story_5053_50530101_15_dialog_content = "<size=30>City Lord?!</size>",
  ui_story_5053_50530101_16_dialog_content = "<size=30>Why are you whispering?</size>",
  ui_story_5053_50530101_17_dialog_content = "<size=30>Look over there.</size>",
  ui_story_5053_50530101_18_dialog_content = "Everything is set, my lord. The carriage awaits outside and is ready to depart anytime.",
  ui_story_5053_50530101_19_dialog_content = "Understood. Get on the carriage, Carleen.",
  ui_story_5053_50530101_20_dialog_content = "I... I want to stay behind with Mother!",
  ui_story_5053_50530101_21_dialog_content = "Everyone in Lumopolis is waiting for us, Carleen. You should know your purpose and obligations.",
  ui_story_5053_50530101_22_dialog_content = "... Yes, I do.",
  ui_story_5053_50530101_23_dialog_content = "I'll wait for you in the carriage, Father.",
  ui_story_5053_50530101_24_dialog_content = "Princess Carleen may be young, but she has great foresight and understanding. It's a blessing to the people of Lumopolis.",
  ui_story_5053_50530101_25_dialog_content = "...",
  ui_story_5053_50530101_26_dialog_content = "Are you worried about Lady Joshua, my lord?",
  ui_story_5053_50530101_27_dialog_content = "Joshua has always been in good health and she wouldn't usually complain about feeling under the weather. Especially not on a day like this.",
  ui_story_5053_50530101_28_dialog_content = "She has been quite busy lately, advocating the new policies to the nobles' wives. I imagine it's taken a toll on her.",
  ui_story_5053_50530101_29_dialog_content = "Never mind.",
  ui_story_5053_50530101_30_dialog_content = "You'll stay behind and look after her, Ms. Rot. Update me should anything happen.",
  ui_story_5053_50530101_31_dialog_content = "Yes, my lord.",
  ui_story_5053_50530101_32_dialog_content = "Is that the young City Lord? How can this be? Does that mean...",
  ui_story_5053_50530101_33_dialog_content = "We did not make it.",
  ui_story_5053_50530101_34_dialog_content = "Father...",
  ui_story_5053_50530101_35_dialog_content = "Father? And PlayerName...",
  ui_story_5053_50530101_36_dialog_content = "Are we back to reality now?",
  ui_story_5053_50530101_37_dialog_content = "This is not the real world.",
  ui_story_5053_50530101_38_dialog_content = "What? It's not reality? But if we didn't get out before the day ended...",
  ui_story_5053_50530101_39_dialog_content = "Aren't we now trapped inside the Crystal of Eternal Memory forever?",
  ui_story_5053_50530101_40_dialog_content = "I'm not sure. We have to ask Jakine.",
  ui_story_5053_50530101_41_dialog_content = "Zzz...",
  ui_story_5053_50530101_42_dialog_content = "Jakine!",
  ui_story_5053_50530101_43_dialog_content = "Stop nudging me, Whisper. Let me sleep some more...",
  ui_story_5053_50530101_44_dialog_content = "Jakine, it's me, PlayerName! It's an emergency, so wake up!",
  ui_story_5053_50530101_45_dialog_content = "Huh, what? Oh, it's you, PlayerName. Yawn...",
  ui_story_5053_50530101_46_dialog_content = "Hey, where am I—",
  ui_story_5053_50530101_47_dialog_content = "Shhh!",
  ui_story_5053_50530101_48_dialog_content = "Did you hear that?",
  ui_story_5053_50530101_49_dialog_content = "Yeah, it's probably coming from the bushes over there.",
  ui_story_5053_50530101_50_dialog_content = "Let's go take a look.",
  ui_story_5053_50530101_51_dialog_content = "Squeak...",
  ui_story_5053_50530101_52_dialog_content = "Oh, it's just a rabbit!",
  ui_story_5053_50530101_53_dialog_content = "<size=50>Squeak... Squeak!</size>",
  ui_story_5053_50530101_54_dialog_content = "That freaked me out. I didn't know rabbits made noises!",
  ui_story_5053_50530101_55_dialog_content = "Never mind, just a rabbit. No threat at all. Let's make our round over there.",
  ui_story_5053_50530101_56_dialog_content = "That was close...",
  ui_story_5053_50530101_57_dialog_content = "Luckily, I was witty enough to morph Caleb into a rabbit and distract them!",
  ui_story_5053_50530101_58_dialog_content = "Squeak!",
  ui_story_5053_50530101_59_dialog_content = "But hold on, why are we hiding?",
  ui_story_5053_50530101_60_dialog_content = "We're still in the Crystal of Eternal Memory, Jakine.",
  ui_story_5053_50530101_61_dialog_content = "What? No way! The spell couldn't have been wrong, and I'm sure I cast it correctly!",
  ui_story_5053_50530101_62_dialog_content = "Let me backtrack here...",
  ui_story_5053_50530101_63_dialog_content = "We were there when the day ended and the clock struck twelve.",
  ui_story_5053_50530101_64_dialog_content = "To get out, the spells to <color=#FFB400>rewind time</color> and <color=#FFB400>exit the Crystal of Eternal Memory</color> must be cast simultaneously.",
  ui_story_5053_50530101_65_dialog_content = "We just saw Ms. Rot sending Young Schwartz and Carleen away, so that means...",
  ui_story_5053_50530101_66_dialog_content = "The spell to exit the Crystal of Eternal Memory <color=#FFB400>failed</color>, but the one to rewind time <color=#FFB400>succeeded</color>?",
  ui_story_5053_50530101_67_dialog_content = "Maybe the monster had something to do with it?",
  ui_story_5053_50530101_68_dialog_content = "Oh right, I remember that thing! What a creepy pain in the ass!",
  ui_story_5053_50530101_69_dialog_content = "It looks terrifying with many densely packed wings on its head.",
  ui_story_5053_50530101_70_dialog_content = "It was like...",
  ui_story_5053_50530101_71_dialog_content = "It was like a dark angel of despair.",
  ui_story_5053_50530101_72_dialog_content = "That's what it was, a <color=#FFB400>dark angel</color>!",
  ui_story_5053_50530101_73_dialog_content = "Sigh, never mind, I'll cast the exit spell now and get everyone out of here!",
  ui_story_5053_50530101_74_dialog_content = "Uh...",
  ui_story_5053_50530101_75_dialog_content = "Squeak!",
  ui_story_5053_50530101_76_dialog_content = "How about changing Uncle Caleb back first?",
  ui_story_5053_50530101_77_dialog_content = "Oops, almost forgot all about that!",
  ui_story_5053_50530101_78_dialog_content = "Mutatio! Mutatio! Mutatio!",
  ui_story_5053_50530101_79_dialog_content = "Restore Caleb back to normal!",
  ui_story_5053_50530101_80_dialog_content = "Abracadabra!",
  ui_story_5053_50530101_81_dialog_content = "<color=#e8d9bb>Poof!</color>",
  ui_story_5053_50530101_82_dialog_content = "...",
  ui_story_5053_50530101_83_dialog_content = "Within the rift of the Crystal is a land of giants...",
  ui_story_5053_50530101_84_dialog_content = "The land of giants... where did it go?",
  ui_story_5053_50530101_85_dialog_content = "Welcome back, Caleb!",
  ui_story_5053_50530101_86_dialog_content = "Back...?",
  ui_story_5053_50530101_87_dialog_content = "I'm back! But I still don't have my sister's... Rats!",
  ui_story_5053_50530101_88_dialog_content = "Uh, what are you saying?",
  ui_story_5053_50530101_89_dialog_content = "You've been very weird from the start, Caleb.",
  ui_story_5053_50530101_90_dialog_content = "One minute you go off on your own, the next you try to steal the Crystal... What are you really up to?",
  ui_story_5053_50530101_91_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5053_50530101_92_dialog_content = "Who's that? Did the guards spot us after all?",
  ui_story_5053_50530101_93_dialog_content = "Grab your weapon, Jakine...",
  ui_story_5053_50530101_94_dialog_content = "The Dark Angel is here again!",
  ui_story_5053_50530101_95_dialog_content = "Over... here?",
  ui_story_5053_50530102_1_dialog_content = "Over... here?",
  ui_story_5053_50530102_2_dialog_content = "Activate, crystal ball!",
  ui_story_5053_50530102_3_dialog_content = "How did the Dark Angel find us here? I thought we reset everything!",
  ui_story_5053_50530102_4_dialog_content = "T-That's my sister's voice...",
  ui_story_5053_50530102_5_dialog_content = "Over... here!",
  ui_story_5053_50530102_6_dialog_content = "White Night! Protect us!",
  ui_story_5053_50530102_7_dialog_content = "Do not lose your focus in battle, Caleb!",
  ui_story_5053_50530102_8_dialog_content = "I don't take orders from you! What's going on here...",
  ui_story_5053_50530102_9_dialog_content = "Lay your weapons down, intruders!",
  ui_story_5053_50530102_10_dialog_content = "How dare you start a fight in the City Lord's residence?!",
  ui_story_5053_50530102_11_dialog_content = "Hi-yah!",
  ui_story_5053_50530102_12_dialog_content = "A-A monster? What in the world is that?!",
  ui_story_5053_50530102_13_dialog_content = "Go get back up!",
  ui_story_5053_50530102_14_dialog_content = "Okay, okay...",
  ui_story_5053_50530102_15_dialog_content = "Sch... wartz...!",
  ui_story_5053_50530102_16_dialog_content = "...",
  ui_story_5053_50530102_17_dialog_content = "Why does the Dark Angel go after my father all the time?",
  ui_story_5053_50530102_18_dialog_content = "And it keeps calling your family name. Does it know you guys?",
  ui_story_5053_50530102_19_dialog_content = "But I don't recognize it at all...",
  ui_story_5053_50530102_20_dialog_content = "Aaaah—!",
  ui_story_5053_50530102_21_dialog_content = "The Sovereign's Blade!",
  ui_story_5053_50530102_22_dialog_content = "Ugh...",
  ui_story_5053_50530102_23_dialog_content = "Your power has diminished much since our first battle.",
  ui_story_5053_50530102_24_dialog_content = "Hi-yah!",
  ui_story_5053_50530102_25_dialog_content = "Yet, still very much a nuisance.",
  ui_story_5053_50530102_26_dialog_content = "Please let me take command! Even though my psychic ability is much weaker now, I can still coordinate!",
  ui_story_5053_50530102_27_dialog_content = "Thank you, but I have another prospect in mind.",
  ui_story_5053_50530102_28_dialog_content = "You should know how to handle this, right, Mia?",
  ui_story_5053_50530102_29_dialog_content = "Me? You're giving me the command...?",
  ui_story_5053_50530102_30_dialog_content = "Take it easy. Think of me as a chess piece in your hand.",
  ui_story_5053_50530102_31_dialog_content = "Tell me, where should I go?",
  ui_story_5053_50530102_32_dialog_content = "Maybe... you can keep luring the angel forward, and then I can attack it from behind?",
  ui_story_5053_50530102_33_dialog_content = "Insufficient!",
  ui_story_5053_50530102_34_dialog_content = "Well, uh...",
  ui_story_5053_50530102_35_dialog_content = "You have more than one chess piece in your hands!",
  ui_story_5053_50530102_36_dialog_content = "I'm sorry, I can't...",
  ui_story_5053_50530102_37_dialog_content = "Relax, Mia, you can do it!",
  ui_story_5053_50530102_38_dialog_content = "PlayerName...",
  ui_story_5053_50530102_39_dialog_content = "(This is practically knight's training. Are you trying to mentor me, Father?)",
  ui_story_5053_50530102_40_dialog_content = "(I can't let him down... And I can't bring dishonor to the knights!)",
  ui_story_5053_50530102_41_dialog_content = "Yes, I think I got this...",
  ui_story_5053_50530102_42_dialog_content = "While my father distracts the Dark Angel... Jakine will attack from one side and, Uncle, you attack from the other.",
  ui_story_5053_50530102_43_dialog_content = "Let's launch a triangular offense to surround the angel... That should work, right?",
  ui_story_5053_50530102_44_dialog_content = "Sounds good! Very professional, I like.",
  ui_story_5053_50530102_45_dialog_content = "Not a bad plan. Let's do it.",
  ui_story_5053_50530102_46_dialog_content = "Over... here...",
  ui_story_5053_50530102_47_dialog_content = "What are you? Why do you pursue us?",
  ui_story_5053_50530102_48_dialog_content = "Sch... wartz...!!!",
  ui_story_5053_50530102_49_dialog_content = "(It's holding back? This is the best window to strike!)",
  ui_story_5053_50530102_50_dialog_content = "Now, everybody!",
  ui_story_5053_50530102_51_dialog_content = "Sorry...!",
  ui_story_5053_50530102_52_dialog_content = "Activate, Crystal Ball!",
  ui_story_5053_50530102_53_dialog_content = "Meet my power!",
  ui_story_5053_50530102_54_dialog_content = "Argh—!",
  ui_story_5053_50530102_55_dialog_content = "Everything hit. We're simply amazing!",
  ui_story_5053_50530102_56_dialog_content = "Hurts... it hurts...!",
  ui_story_5053_50530102_57_dialog_content = "She seems to be in agony...",
  ui_story_5053_50530102_58_dialog_content = "Don't get all soft on me now. The Dark Angel has been attacking us for no reason!",
  ui_story_5053_50530102_59_dialog_content = "You're right, no mercy in battle.",
  ui_story_5053_50530102_60_dialog_content = "Did our attack work?",
  ui_story_5053_50530102_61_dialog_content = "Agh... Aaaaaaaagh!",
  ui_story_5053_50530102_62_dialog_content = "Whoa, what a creepy shriek.",
  ui_story_5053_50530102_63_dialog_content = "Oh no, it's powering up and about to go off!",
  ui_story_5053_50530102_64_dialog_content = "W-What now...?!",
  ui_story_5053_50530102_65_dialog_content = "You did well, Mia. I will take over now.",
  ui_story_5053_50530102_66_dialog_content = "Father...?",
  ui_story_5053_50530102_67_dialog_content = "All of you, stand down!",
  ui_story_5053_50530102_68_dialog_content = "Sch...",
  ui_story_5053_50530102_69_dialog_content = "Sch... wartz...!!!",
  ui_story_5053_50530102_70_dialog_content = "Are you so desperate to fight me one-on-one?",
  ui_story_5053_50530102_71_dialog_content = "I shall grant your wish, then.",
  ui_story_5053_50530102_72_dialog_content = "Now, take your epitaph—!",
  ui_story_5053_50530102_73_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5053_50530102_74_dialog_content = "Ugh... Ugh...",
  ui_story_5053_50530102_75_dialog_content = "Where did it go?",
  ui_story_5053_50530102_76_dialog_content = "Probably fled down a path outside.",
  ui_story_5053_50530102_77_dialog_content = "That was awesome, Lord Schwartz!",
  ui_story_5053_50530102_78_dialog_content = "No matter how powerful it is, the angel must be injured badly. I doubt it can get very far.",
  ui_story_5053_50530102_79_dialog_content = "...",
  ui_story_5053_50530102_80_dialog_content = "Are you still bothered about the Dark Angel, Uncle?",
  ui_story_5053_50530102_81_dialog_content = "Its voice... Never mind, my sister could never be a monster.",
  ui_story_5053_50530102_82_dialog_content = "Take the time now to cast your spell, Jakine.",
  ui_story_5053_50530102_83_dialog_content = "Huh... Oh yeah! Now that the meddling angel is finally gone, I can get everybody out!",
  ui_story_5053_50530102_84_dialog_content = "Ad praesens! Ad praesens! Ad praesens!",
  ui_story_5053_50530102_85_dialog_content = "Let us return to reality!",
  ui_story_5053_50530102_86_dialog_content = "Abracadabra!",
  ui_story_5053_50530102_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530102_88_dialog_content = "I don't think that worked...",
  ui_story_5053_50530102_89_dialog_content = "Let me try again!",
  ui_story_5053_50530102_90_dialog_content = "Ad praesens! Ad praesens! Ad praesens!",
  ui_story_5053_50530102_91_dialog_content = "Let us return to reality! Abracadabra!",
  ui_story_5053_50530102_92_dialog_content = "You sure you got the words right, Jakine?",
  ui_story_5053_50530102_93_dialog_content = "Of course! Is everyone holding hands? Let me check... Yeah!",
  ui_story_5053_50530102_94_dialog_content = "I thought it failed last time because it was so chaotic that our hands couldn't all be linked.",
  ui_story_5053_50530102_95_dialog_content = "But how come it still didn't work this time?",
  ui_story_5053_50530102_96_dialog_content = "You were holding the Crystal for this realm when you cast the spell last time. Did you forget this time?",
  ui_story_5053_50530102_97_dialog_content = "No, <color=#FFB400>you only need it when rewinding time</color>... That's the emergency fail safe my mom set up.",
  ui_story_5053_50530102_98_dialog_content = "It's not necessary for a standard departure like this!",
  ui_story_5053_50530102_99_dialog_content = "Are there other possibilities?",
  ui_story_5053_50530102_100_dialog_content = "Unless... <color=#FFB400>Not all of us are here</color>.",
  ui_story_5053_50530102_101_dialog_content = "What do you mean by that?",
  ui_story_5053_50530102_102_dialog_content = "Out of safety concerns, a person has to activate the Crystal to enter it, and everyone has to be present for the whole party to leave.",
  ui_story_5053_50530102_103_dialog_content = "Even though I accidentally broke that rule with my spell when we came in, I can't be doing that on our way out!",
  ui_story_5053_50530102_104_dialog_content = "All of us are here, right? I didn't miss anyone...",
  ui_story_5053_50530102_105_dialog_content = "Could someone else have gotten pulled in along with us?",
  ui_story_5053_50530102_106_dialog_content = "Or maybe, before we entered, someone came in through other means.",
  ui_story_5053_50530102_107_dialog_content = "But the activator passed away long ago, so that's impossible, right?",
  ui_story_5053_50530102_108_dialog_content = "...",
  ui_story_5053_50530102_109_dialog_content = "My lord, y-you've come in person?!",
  ui_story_5053_50530102_110_dialog_content = "My apologies that our incompetence has disturbed your peace.",
  ui_story_5053_50530102_111_dialog_content = "It's all right. Can you tell me what happened?",
  ui_story_5053_50530102_112_dialog_content = "Of course. Several unknown individuals trespassed into the garden and fought off a monster.",
  ui_story_5053_50530102_113_dialog_content = "One of the intruders looked and dressed very much like Princess Veronica, but I'm not sure...",
  ui_story_5053_50530102_114_dialog_content = "Veronica? I see. You're doing a good job.",
  ui_story_5053_50530201_1_dialog_content = "So, you guys don't want to try these snacks? I'll finish them if you don't.",
  ui_story_5053_50530201_2_dialog_content = "Can't believe you're still in the mood for that.",
  ui_story_5053_50530201_3_dialog_content = "We just fought in Lady Joshua's garden. I have no idea how to break it to her.",
  ui_story_5053_50530201_4_dialog_content = "Relax, relax! Stressing out won't get us anywhere!",
  ui_story_5053_50530201_5_dialog_content = "I do envy you for your optimism.",
  ui_story_5053_50530201_6_dialog_content = "Joshua is not someone who would mete harsh punishments.",
  ui_story_5053_50530201_7_dialog_content = "Since she ordered us to be brought here and even offered dessert, it clearly shows she's treating us with respect, not hostility.",
  ui_story_5053_50530201_8_dialog_content = "We really should rejoice.",
  ui_story_5053_50530201_9_dialog_content = "If <color=#FFB400>someone else</color> had also been present, we'd probably be incarcerated by now.",
  ui_story_5053_50530201_10_dialog_content = "Someone else? Who are you talking about?",
  ui_story_5053_50530201_11_dialog_content = "...",
  ui_story_5053_50530201_12_dialog_content = "He means me, the younger me.",
  ui_story_5053_50530201_13_dialog_content = "You're not so full of yourself after all, Lord Schwartz.",
  ui_story_5053_50530201_14_dialog_content = "A-Anyway, here comes the Lady Joshua of this world.",
  ui_story_5053_50530201_15_dialog_content = "That at least proves the Dark Angel isn't this world's Lady Joshua.",
  ui_story_5053_50530201_16_dialog_content = "We should not be worried about that right now. Jakine, do you know how to find out who else has entered the Crystal?",
  ui_story_5053_50530201_17_dialog_content = "There's always a way, of course.",
  ui_story_5053_50530201_18_dialog_content = "We just need the Crystal of Eternal Memory for this world.",
  ui_story_5053_50530201_19_dialog_content = "Other than using it to rewind time, we can <color=#FFB400>see who's an illusion and who's real with the Crystal</color>.",
  ui_story_5053_50530201_20_dialog_content = "Even though it still can't pinpoint exact locations...",
  ui_story_5053_50530201_21_dialog_content = "But the problem with that is it's time-consuming. You can only verify one person at a time.",
  ui_story_5053_50530201_22_dialog_content = "There's a lotta people in Lumopolis...",
  ui_story_5053_50530201_23_dialog_content = "It's okay! As long as we have the fail-safe in hand, we can keep rewinding to buy ourselves time!",
  ui_story_5053_50530201_24_dialog_content = "Though that will use up the Lumina maintaining the world, so we can't do it indiscriminately.",
  ui_story_5053_50530201_25_dialog_content = "Then our top priority is to find the Crystal of Eternal Memory. We should put the Dark Angel matter on hold for now.",
  ui_story_5053_50530201_26_dialog_content = "Is this what you're looking for?",
  ui_story_5053_50530201_27_dialog_content = "Is that the Crystal of Eternal Memory in your hand, Lady Joshua?",
  ui_story_5053_50530201_28_dialog_content = "Did you overhear our conversation, Lady Joshua? How did you know we were looking for the Crystal?",
  ui_story_5053_50530201_29_dialog_content = "Heheh, don't worry about that, my dear child, and check out the Crystal.",
  ui_story_5053_50530201_30_dialog_content = "Wait... How is this possible?!",
  ui_story_5053_50530201_31_dialog_content = "Lady Joshua... You're a <color=#FFB400>real Aurorian</color>!",
  ui_story_5053_50530201_32_dialog_content = "!!!",
  ui_story_5053_50530201_33_dialog_content = "Sister... But... Is it really you?",
  ui_story_5053_50530201_34_dialog_content = "Who else would I be, my dear little genius?",
  ui_story_5053_50530201_35_dialog_content = "...",
  ui_story_5053_50530201_36_dialog_content = "Are you sure, Jakine?",
  ui_story_5053_50530201_37_dialog_content = "Sure as I'll ever be! Unless there's a problem with my eyes!",
  ui_story_5053_50530201_38_dialog_content = "Mother... is this real?",
  ui_story_5053_50530201_39_dialog_content = "Of course it is.",
  ui_story_5053_50530201_40_dialog_content = "You still look very much the same as when you joined the knights, just like I remembered.",
  ui_story_5053_50530201_41_dialog_content = "*Sniff* That's... That's because...",
  ui_story_5053_50530201_42_dialog_content = "It's because Forsakin modified Veronica... Mia's body and made her forever 13 physically.",
  ui_story_5053_50530201_43_dialog_content = "But wait, I saw with my own eyes that you...",
  ui_story_5053_50530201_44_dialog_content = "What do you mean?",
  ui_story_5053_50530201_45_dialog_content = "On Schwartz Family Day twelve years ago, the Eclipsites planted a Seed in Mia... in Veronica, during a mission for the knights.",
  ui_story_5053_50530201_46_dialog_content = "Then she was sent to an Illumina lab for the so-called \"treatment,\" which was actually a trap set up by Eclipsites and traitors.",
  ui_story_5053_50530201_47_dialog_content = "To save Veronica, Joshua went to fight them on her own.",
  ui_story_5053_50530201_48_dialog_content = "The rescue was a success, but somehow they planted a Seed in Joshua as well...",
  ui_story_5053_50530201_49_dialog_content = "Later, after much suffering...",
  ui_story_5053_50530201_50_dialog_content = "She <color=#FFB400>chose to end her own life</color>.",
  ui_story_5053_50530201_51_dialog_content = "Yet, here you are in the Crystal. Maybe you could explain that.",
  ui_story_5053_50530201_52_dialog_content = "Schwartz, is this how you talk to the wife you haven't seen in twelve years?!",
  ui_story_5053_50530201_53_dialog_content = "It's all right, Caleb. Daniel is doing the right thing to protect everyone.",
  ui_story_5053_50530201_54_dialog_content = "Fine, if you say so.",
  ui_story_5053_50530201_55_dialog_content = "Then I should pick up where Daniel left off.",
  ui_story_5053_50530201_56_dialog_content = "It was true that I was tormented by agony...",
  ui_story_5053_50530201_57_dialog_content = "<color=#e8d9bb>Schwartz Manor, A Number of Years Ago</color>",
  ui_story_5053_50530201_58_dialog_content = "*Coughs* Just kill me, Daniel.",
  ui_story_5053_50530201_59_dialog_content = "I will not hear such a request from you, Joshua...",
  ui_story_5053_50530201_60_dialog_content = "The more I resist the Seed, the harder it tortures me.",
  ui_story_5053_50530201_61_dialog_content = "I can feel it is fighting me for control of my body.",
  ui_story_5053_50530201_62_dialog_content = "There's a way to free you, trust me!",
  ui_story_5053_50530201_63_dialog_content = "Do you remember John the physician? Yes, we can ask him for help.",
  ui_story_5053_50530201_64_dialog_content = "I will send people to track him down immediately!",
  ui_story_5053_50530201_65_dialog_content = "Take it easy and wait for me.",
  ui_story_5053_50530201_66_dialog_content = "It's pointless, Daniel, pointless...",
  ui_story_5053_50530201_67_dialog_content = "Urgh—",
  ui_story_5053_50530201_68_dialog_content = "Stop struggling and give in to me.",
  ui_story_5053_50530201_69_dialog_content = "Never!",
  ui_story_5053_50530201_70_dialog_content = "I'll never surrender my body, even if I have to stab myself in the heart!",
  ui_story_5053_50530201_71_dialog_content = "No, drop that dagger!",
  ui_story_5053_50530201_72_dialog_content = "Never!",
  ui_story_5053_50530201_73_dialog_content = "Drop it!!!",
  ui_story_5053_50530201_74_dialog_content = "Urgh...",
  ui_story_5053_50530201_75_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5053_50530201_76_dialog_content = "The Crystal of Eternal Memory...?",
  ui_story_5053_50530201_77_dialog_content = "What are you doing? No!!!",
  ui_story_5053_50530201_78_dialog_content = "Let us relive the golden days of the past...",
  ui_story_5053_50530201_79_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5053_50530201_80_dialog_content = "Are you all right, Joshua? What was that loud noise?",
  ui_story_5053_50530201_81_dialog_content = "How come you're not answering? Stop freaking me out. I'm coming in.",
  ui_story_5053_50530201_82_dialog_content = "J-Joshua...?",
  ui_story_5053_50530201_83_dialog_content = "<size=50>Sister!!!</size>",
  ui_story_5053_50530201_84_dialog_content = "The Seed split me into <color=#FFB400>two different personalities</color>.",
  ui_story_5053_50530201_85_dialog_content = "One is the normal me, but the other is an irrational, deranged monster.",
  ui_story_5053_50530201_86_dialog_content = "As it grew, it began to try to take over me and hurt those around me.",
  ui_story_5053_50530201_87_dialog_content = "I couldn't allow that, so I started fighting it.",
  ui_story_5053_50530201_88_dialog_content = "The constant clash between the personalities was ripping my mind apart every day.",
  ui_story_5053_50530201_89_dialog_content = "It didn't affect the monster at all, so it slowly gained the upper hand...",
  ui_story_5053_50530201_90_dialog_content = "I was on the verge of collapsing and knew I was about to lose.",
  ui_story_5053_50530201_91_dialog_content = "So I thought of a solution that would not let me win, but would thoroughly defeat the monster—",
  ui_story_5053_50530201_92_dialog_content = "<color=#FFB400>And that was to trap us both in the Crystal of Eternal Memory</color>.",
  ui_story_5053_50530201_93_dialog_content = "With a death wish, I sent myself and the monster into this world.",
  ui_story_5053_50530201_94_dialog_content = "We're one, so as long as I don't leave, it has to stay here with me.",
  ui_story_5053_50530201_95_dialog_content = "We fought each other for a long, long time.",
  ui_story_5053_50530201_96_dialog_content = "After the clock struck midnight, we became part of this world since we broke the rule.",
  ui_story_5053_50530201_97_dialog_content = "We lost our memory and recombined to become this world's Joshua, and we've been reliving this same day over and over all this time.",
  ui_story_5053_50530201_98_dialog_content = "Until you arrived.",
  ui_story_5053_50530201_99_dialog_content = "Your arrival awakened our memories.",
  ui_story_5053_50530201_100_dialog_content = "The awakened monster struggled and separated from me.",
  ui_story_5053_50530201_101_dialog_content = "<color=#FFB400>She robbed me of all my power</color> and fled, trying to exit the Crystal.",
  ui_story_5053_50530201_102_dialog_content = "The situation is dire, but this time...",
  ui_story_5053_50530201_103_dialog_content = "I'm not alone anymore.",
  ui_story_5053_50530201_104_dialog_content = "...",
  ui_story_5053_50530201_105_dialog_content = "W-What a marvelous story... So the <color=#FFB400>Dark Angel that attacked us was another Lady Joshua</color>?",
  ui_story_5053_50530201_106_dialog_content = "Dark Angel? You named it...? Anyway, yes, you could say that.",
  ui_story_5053_50530201_107_dialog_content = "Only Joshua and I were privy to that conversation, and the details matched exactly.",
  ui_story_5053_50530201_108_dialog_content = "It really is you, Joshua...",
  ui_story_5053_50530201_109_dialog_content = "It's great that you finally believe me.",
  ui_story_5053_50530201_110_dialog_content = "Oh, Mother... You're real...",
  ui_story_5053_50530201_111_dialog_content = "You're crying again, little one.",
  ui_story_5053_50530201_112_dialog_content = "I can't believe you're here, Joshua. I've been looking... and never found you...",
  ui_story_5053_50530201_113_dialog_content = "How wonderful it is to talk to you again after twelve years...",
  ui_story_5053_50530201_114_dialog_content = "(The Seed, two personalities... That sounds very similar to what happened to Mia.)",
  ui_story_5053_50530201_115_dialog_content = "(Mia's personalities are friends and depend on each other, but it's the polar opposite for Lady Joshua.)",
  ui_story_5053_50530201_116_dialog_content = "(Seeds have such different effects on different people.)",
  ui_story_5053_50530201_117_dialog_content = "Speaking of which, you mentioned something about twelve years ago.",
  ui_story_5053_50530201_118_dialog_content = "Have I been here for twelve years?",
  ui_story_5053_50530201_119_dialog_content = "Correct.",
  ui_story_5053_50530201_120_dialog_content = "No wonder you look totally different, Daniel.",
  ui_story_5053_50530201_121_dialog_content = "I probably wouldn't recognize you if it wasn't for others calling your name.",
  ui_story_5053_50530201_122_dialog_content = "But what happened to your eyes and face?",
  ui_story_5053_50530201_123_dialog_content = "I have been through too many wars and turmoil to recall the origins of my scars.",
  ui_story_5053_50530201_124_dialog_content = "But I still remember the day you left me, and how cold the dagger on your chest was to the touch...",
  ui_story_5053_50530201_125_dialog_content = "Daniel...",
  ui_story_5053_50530201_126_dialog_content = "Speaking of, Lady Joshua's body was buried, right?",
  ui_story_5053_50530201_127_dialog_content = "Can she or the Dark Angel leave the Crystal then?",
  ui_story_5053_50530201_128_dialog_content = "Yes.",
  ui_story_5053_50530201_129_dialog_content = "Because her body <color=#FFB400>was never buried</color>.",
  ui_story_5053_50530201_130_dialog_content = "What do you mean?",
  ui_story_5053_50530201_131_dialog_content = "Hmph, when I found her, she wasn't dead yet.",
  ui_story_5053_50530201_132_dialog_content = "I pulled off a few things and brought her home for treatment.",
  ui_story_5053_50530201_133_dialog_content = "What? But I heard the whole city witnessed the funeral, so what did you do...",
  ui_story_5053_50530201_134_dialog_content = "I handled Joshua's funeral personally, so there could not have been any missteps.",
  ui_story_5053_50530201_135_dialog_content = "Unless, you exhumed her.",
  ui_story_5053_50530201_136_dialog_content = "Heavens... Tell me what you did, little brother!",
  ui_story_5053_50530201_137_dialog_content = "Since you ask... Yes, I did exhume you.",
  ui_story_5053_50530201_138_dialog_content = "To avoid detection, I dug a tunnel to the crypt from a distance, so no one would be the wiser.",
  ui_story_5053_50530201_139_dialog_content = "You dug it yourself? Gonna be honest, I didn't expect you to be capable of labor like that.",
  ui_story_5053_50530201_140_dialog_content = "I'm willing to do anything for my sister.",
  ui_story_5053_50530201_141_dialog_content = "But how did you fool the physician and coroner? Did you bribe them...?",
  ui_story_5053_50530201_142_dialog_content = "No, I just used some potion.",
  ui_story_5053_50530201_143_dialog_content = "I was surprised too, that the great doctors in Lumopolis Gardens were deceived by my little tricks.",
  ui_story_5053_50530201_144_dialog_content = "No wonder they couldn't cure my sister.",
  ui_story_5053_50530201_145_dialog_content = "You were never this humble when you were arguing with the instructors in Dawn Academy, Caleb.",
  ui_story_5053_50530201_146_dialog_content = "You're the type of genius the Academy comes across maybe once a century. I hope you apply your intelligence to the right things.",
  ui_story_5053_50530201_147_dialog_content = "Why did you have to act on your own volition, Caleb...",
  ui_story_5053_50530201_148_dialog_content = "Because you never wanted to leave Schwartz and the children, while he was making life harder and harder for you.",
  ui_story_5053_50530201_149_dialog_content = "I just wanted to protect you.",
  ui_story_5053_50530201_150_dialog_content = "I'm so sorry to have made you feel so burdened.",
  ui_story_5053_50530201_151_dialog_content = "He is this way because you have always spoiled him.",
  ui_story_5053_50530201_152_dialog_content = "We will revisit this after we exit here, Caleb.",
  ui_story_5053_50530201_153_dialog_content = "So, we can leave here and revive Mother if we defeat the Dark Angel?",
  ui_story_5053_50530201_154_dialog_content = "From what we've gathered so far, that's the case.",
  ui_story_5053_50530201_155_dialog_content = "So, how is Joshua's body now? Can it endure the shock of an abrupt revival?",
  ui_story_5053_50530201_156_dialog_content = "It's perfectly preserved, of course. Since she fell into a coma, I've spent all my time and effort on her.",
  ui_story_5053_50530201_157_dialog_content = "As for the result, <color=#FFB400>just look at me</color>.",
  ui_story_5053_50530201_158_dialog_content = "Look at you? What for?",
  ui_story_5053_50530201_159_dialog_content = "Caleb, even if it's for Joshua, I forbid you from unethical experiments.",
  ui_story_5053_50530201_160_dialog_content = "What's it to you?",
  ui_story_5053_50530201_161_dialog_content = "Wait, I'm lost. What's going on here?",
  ui_story_5053_50530201_162_dialog_content = "How old do you think I am, Jakine?",
  ui_story_5053_50530201_163_dialog_content = "Twenty-something?",
  ui_story_5053_50530201_164_dialog_content = "See what I mean?",
  ui_story_5053_50530201_165_dialog_content = "Uh, if I remember correctly, Uncle should be approaching 40...",
  ui_story_5053_50530201_166_dialog_content = "Huh—?!",
  ui_story_5053_50530201_167_dialog_content = "What—?!",
  ui_story_5053_50530201_168_dialog_content = "Here I thought Uncle was born that way or just good with makeup... I didn't expect it to be the result of experiments...",
  ui_story_5053_50530201_169_dialog_content = "I'd never use an untested potion on my sister.",
  ui_story_5053_50530201_170_dialog_content = "Nor would I hurt innocent people like those nobles, so the only choice was to test it on myself.",
  ui_story_5053_50530201_171_dialog_content = "Oh my, Caleb...",
  ui_story_5053_50530201_172_dialog_content = "Are you okay, Mother? You don't look well...",
  ui_story_5053_50530201_173_dialog_content = "I'm fine... I'm used to it, probably...",
  ui_story_5053_50530201_174_dialog_content = "<size=30>But PlayerName, Caleb acts very immature too, so does that mean his research could keep people forever young, like, mentally?</size>",
  ui_story_5053_50530201_175_dialog_content = "I heard that, Jakine!",
  ui_story_5053_50530201_176_dialog_content = "While her body is fine, the Lumina in her tends to go out of control.",
  ui_story_5053_50530201_177_dialog_content = "I still need to do more research into it since I haven't found a solution yet.",
  ui_story_5053_50530201_178_dialog_content = "Lumina? So that's why you asked me where Lady Joshua's Lumina was!",
  ui_story_5053_50530201_179_dialog_content = "Obviously. My intent was to find her residual Lumina for experimental treatment.",
  ui_story_5053_50530201_180_dialog_content = "But who could've guessed she was in the Crystal all along? And that's why the Lumina in her body kept losing control.",
  ui_story_5053_50530201_181_dialog_content = "My theory was completely wrong...",
  ui_story_5053_50530201_182_dialog_content = "You should have told me about it sooner, Caleb.",
  ui_story_5053_50530201_183_dialog_content = "Told you? So you could keep torturing her?",
  ui_story_5053_50530201_184_dialog_content = "Why are you arguing again? Let's not do this in front of others.",
  ui_story_5053_50530201_185_dialog_content = "Sorry, Sister.",
  ui_story_5053_50530201_186_dialog_content = "Given her body is still in good condition, we should bring her out as soon as possible.",
  ui_story_5053_50530201_187_dialog_content = "Let's get back on topic and figure out what to do about the Dark Angel.",
  ui_story_5053_50530201_188_dialog_content = "Yes, let's do that.",
  ui_story_5053_50530201_189_dialog_content = "I cannot defeat it on my own.",
  ui_story_5053_50530201_190_dialog_content = "Because we share <color=#FFB400>the same body and have lived one life</color>, only a third party could destroy it.",
  ui_story_5053_50530201_191_dialog_content = "But you must be cautious since it's hunting you as well.",
  ui_story_5053_50530201_192_dialog_content = "Hunting us?",
  ui_story_5053_50530201_193_dialog_content = "Yes. It's grown tired of our conflicts and wants to be independent, taking my body for itself.",
  ui_story_5053_50530201_194_dialog_content = "It would be very difficult in the real world.",
  ui_story_5053_50530201_195_dialog_content = "But as a part of me who activated the Crystal of Eternal Memory, it can <color=#FFB400>kill all other living persons for the Lumina to become whole</color> here.",
  ui_story_5053_50530201_196_dialog_content = "Is that true, Jakine?",
  ui_story_5053_50530201_197_dialog_content = "Yeah. It might sound like nonsense, but it's possible inside the Crystal.",
  ui_story_5053_50530201_198_dialog_content = "The Crystal might seem like a memory playback device, but the principle behind it goes way deeper than that.",
  ui_story_5053_50530201_199_dialog_content = "That's why Mom only made one under the Queen's order, then hid all everything about it after...",
  ui_story_5053_50530201_200_dialog_content = "So, basically, there are two possible outcomes.",
  ui_story_5053_50530201_201_dialog_content = "One is we destroy the Dark Angel and bring Lady Joshua with us out of here.",
  ui_story_5053_50530201_202_dialog_content = "The other is the Dark Angel kills us and gets let loose into the real world?",
  ui_story_5053_50530201_203_dialog_content = "That's correct. What a brilliant child. You're PlayerName, right?",
  ui_story_5053_50530201_204_dialog_content = "Yes. By the way, you know my name and Jakine's, and the name Mia doesn't seem to surprise you.",
  ui_story_5053_50530201_205_dialog_content = "Do you have memories from prior to the reset too?",
  ui_story_5053_50530201_206_dialog_content = "Yes, since <color=#FFB400>I was with you</color> when it happened.",
  ui_story_5053_50530201_207_dialog_content = "And I don't want to be away from my family again...",
  ui_story_5053_50530201_208_dialog_content = "I swear I'll destroy the Dark Angel and get you out of here, so don't you worry.",
  ui_story_5053_50530201_209_dialog_content = "Me too...! I'll free you from this place!",
  ui_story_5053_50530201_210_dialog_content = "Indeed, I have faith in all of you.",
  ui_story_5053_50530201_211_dialog_content = "The Dark Angel lacks reasoning skills, yet it's devious.",
  ui_story_5053_50530201_212_dialog_content = "We need bait to draw it out.",
  ui_story_5053_50530201_213_dialog_content = "Do you mind, Daniel?",
  ui_story_5053_50530201_214_dialog_content = "No problem. It is best that I assume such a vital and dangerous role anyway.",
  ui_story_5053_50530201_215_dialog_content = "But how do I lure it to me?",
  ui_story_5053_50530201_216_dialog_content = "You don't have to do anything, since that monster... <color=#FFB400>rather hates you</color>.",
  ui_story_5053_50530201_217_dialog_content = "If you weren't strong enough to drive it away, it would have torn you apart.",
  ui_story_5053_50530201_218_dialog_content = "That also applies to the young you in this world. It's likely to attack him at the celebration.",
  ui_story_5053_50530201_219_dialog_content = "Even though killing an illusion won't do anything for it, it still can't resist.",
  ui_story_5053_50530201_220_dialog_content = "I see. In that case, I just have to find the young me and wait around for it to show up.",
  ui_story_5053_50530201_221_dialog_content = "Wait, won't that be dangerous, Father? What if you get hurt?",
  ui_story_5053_50530201_222_dialog_content = "You're always so concerned about our family, Vonnie.",
  ui_story_5053_50530201_223_dialog_content = "But, our current situation is urgent and we must focus our priorities.",
  ui_story_5053_50530201_224_dialog_content = "Trust your father, will you?",
  ui_story_5053_50530201_225_dialog_content = "All right...",
  ui_story_5053_50530201_226_dialog_content = "After the parade should be the opening ceremony at the square.",
  ui_story_5053_50530201_227_dialog_content = "Should we stake out there?",
  ui_story_5053_50530201_228_dialog_content = "Good idea, but you must stay with me, Jakine.",
  ui_story_5053_50530201_229_dialog_content = "Why? Don't snub me, I'm a much better fighter than PlayerName!",
  ui_story_5053_50530201_230_dialog_content = "Ahem...",
  ui_story_5053_50530201_231_dialog_content = "Yes, I know, but you operate the Crystal.",
  ui_story_5053_50530201_232_dialog_content = "If the others get hurt, we can always turn back time to restore everything.",
  ui_story_5053_50530201_233_dialog_content = "But if anything were to happen to you, it would be irreversible.",
  ui_story_5053_50530201_234_dialog_content = "Y-You're right...",
  ui_story_5053_50530201_235_dialog_content = "So we have the City Lord as the bait. Mia, PlayerName and I will head for the square together to stop the Dark Angel.",
  ui_story_5053_50530201_236_dialog_content = "Jakine and my sister shall stay here and wait for the good news.",
  ui_story_5053_50530201_237_dialog_content = "Make sure you take good care of her, Jakine.",
  ui_story_5053_50530201_238_dialog_content = "I got it! Why does everyone doubt me...",
  ui_story_5053_50530201_239_dialog_content = "I'm surprised, Caleb. I thought you would insist on staying with your sister.",
  ui_story_5053_50530201_240_dialog_content = "Killing the Dark Angel and taking my sister out of here is the most important thing right now. Do you think I don't get that?",
  ui_story_5053_50530201_241_dialog_content = "U-Um, we should get going.",
  ui_story_5053_50530201_242_dialog_content = "Yeah, let's go!",
  ui_story_5053_50530201_243_dialog_content = "Stop pushing me, you two.",
  ui_story_5053_50530201_244_dialog_content = "Have a safe trip!",
  ui_story_5053_50530201_245_dialog_content = "I will not lose you again, Joshua, I promise.",
  ui_story_5053_50530201_246_dialog_content = "Yes, I believe you.",
  ui_story_5053_50530201_247_dialog_content = "You won't.",
  ui_story_5053_50530301_1_dialog_content = "The parade is over and the celebration will start soon.",
  ui_story_5053_50530301_2_dialog_content = "Are there still good spots available to watch it?",
  ui_story_5053_50530301_3_dialog_content = "Hurry, let's go check it out!",
  ui_story_5053_50530301_4_dialog_content = "What's there to see? It's all just a farce.",
  ui_story_5053_50530301_5_dialog_content = "It's crowded everywhere. How are we going to spot the Dark Angel when we can barely see?",
  ui_story_5053_50530301_6_dialog_content = "Get close to the stand and just wait.",
  ui_story_5053_50530301_7_dialog_content = "Since both of you can lure the Dark Angel to us, wouldn't we have a better chance if both of you go up there?",
  ui_story_5053_50530301_8_dialog_content = "Well, I think it's better for me to go, since the people here still recognize me.",
  ui_story_5053_50530301_9_dialog_content = "If Father goes, it might stir up too much chaos...",
  ui_story_5053_50530301_10_dialog_content = "True. But if the Angel attacks the stand, can you fight it off alone, Mia?",
  ui_story_5053_50530301_11_dialog_content = "I... I'm not alone.",
  ui_story_5053_50530301_12_dialog_content = "Father in this world will help me too.",
  ui_story_5053_50530301_13_dialog_content = "Not to mention, I'll have a better view up there. I can relay the Angel's position to you when I see it...",
  ui_story_5053_50530301_14_dialog_content = "Hmm... I'll move to a spot where everyone can see me and send a signal!",
  ui_story_5053_50530301_15_dialog_content = "Oh, sorry, Father... Maybe my idea is too naive?",
  ui_story_5053_50530301_16_dialog_content = "You covered everything. We will proceed as you suggested.",
  ui_story_5053_50530301_17_dialog_content = "What? Really?",
  ui_story_5053_50530301_18_dialog_content = "Thank you, Father. I'll be off now, just wait for my signal!",
  ui_story_5053_50530301_19_dialog_content = "It's only been a day and Mia is so brave and independent already. It's good to see that.",
  ui_story_5053_50530301_20_dialog_content = "Now is not the time for praises, PlayerName. Keep your eyes open for the demon that ruined my sister!",
  ui_story_5053_50530301_21_dialog_content = "Yes, I'll be right over!",
  ui_story_5053_50530301_22_dialog_content = "The celebration will begin soon, Carleen. Return to your seat.",
  ui_story_5053_50530301_23_dialog_content = "Yes, Father.",
  ui_story_5053_50530301_24_dialog_content = "Father, Carleen.",
  ui_story_5053_50530301_25_dialog_content = "Veronica?! Father, Veronica's here!",
  ui_story_5053_50530301_26_dialog_content = "Veronica? What are you doing here?",
  ui_story_5053_50530301_27_dialog_content = "M-Mother told me to come home for the Family Day celebration.",
  ui_story_5053_50530301_28_dialog_content = "You saw your mother?",
  ui_story_5053_50530301_29_dialog_content = "Yes... She wasn't feeling well but said we shouldn't worry.",
  ui_story_5053_50530301_30_dialog_content = "Isn't this Princess Veronica? It's been a long time. How are you doing?",
  ui_story_5053_50530301_31_dialog_content = "Didn't Princess Veronica join the knights and follow them to Umbraton?",
  ui_story_5053_50530301_32_dialog_content = "I wanted to come back for the celebration so I requested time off.",
  ui_story_5053_50530301_33_dialog_content = "I see. And you should, since it's Schwartz Family Day, after all.",
  ui_story_5053_50530301_34_dialog_content = "Too bad my family is still stationed in Umbraton and doesn't have the privilege.",
  ui_story_5053_50530301_35_dialog_content = "Veronica is a member of House Schwartz so it's her right to come back for our Family Day!",
  ui_story_5053_50530301_36_dialog_content = "Be quiet, Carleen, and be respectful to Duke Hermes.",
  ui_story_5053_50530301_37_dialog_content = "Don't blame Carleen, Father. I came back unannounced.",
  ui_story_5053_50530301_38_dialog_content = "And since Duke Hermes is here, how is Mrs. Hermes doing lately?",
  ui_story_5053_50530301_39_dialog_content = "She's doing just fine, as always.",
  ui_story_5053_50530301_40_dialog_content = "I've been very concerned since your grandson always took leave and said Mrs. Hermes was in bad shape.",
  ui_story_5053_50530301_41_dialog_content = "It is good to know she is fine.",
  ui_story_5053_50530301_42_dialog_content = "... Yes, thank you for the regard, your highness.",
  ui_story_5053_50530301_43_dialog_content = "You should take the time to spend with your family once in a while, Duke Hermes.",
  ui_story_5053_50530301_44_dialog_content = "Princess Veronica has matured. The Knights must have trained her well.",
  ui_story_5053_50530301_45_dialog_content = "Perhaps, but I hope it does not go to her head.",
  ui_story_5053_50530301_46_dialog_content = "Oh, Lord Schwartz, you don't have to be so tough only to Princess Veronica.",
  ui_story_5053_50530301_47_dialog_content = "Thank you, Duke Troy. Father is right, I must remain humble and keep learning.",
  ui_story_5053_50530301_48_dialog_content = "I see, Princess Veronica... You indeed have grown up working with the knights.",
  ui_story_5053_50530301_49_dialog_content = "The celebration is starting. Please take your seat, everyone.",
  ui_story_5053_50530301_50_dialog_content = "You were so cool, Veronica! Those nobles from the Elder Council didn't scare you at all!",
  ui_story_5053_50530301_51_dialog_content = "You think so? I was nervous, to be honest...",
  ui_story_5053_50530301_52_dialog_content = "You were brave too, Carleen, joining the parade with Father by yourself.",
  ui_story_5053_50530301_53_dialog_content = "No, I didn't want to be apart from Mother either...",
  ui_story_5053_50530301_54_dialog_content = "When I got on the carriage, Father said Mother wasn't feeling well and wanted me to go to the celebration alone...",
  ui_story_5053_50530301_55_dialog_content = "(I see, Mother used illness as an excuse to get Carleen and Father away so she could see us.)",
  ui_story_5053_50530301_56_dialog_content = "(That must've hurt little Carleen's feelings, but at least none of this is real.)",
  ui_story_5053_50530301_57_dialog_content = "(Priorities, priorities... No, I just can't do it.)",
  ui_story_5053_50530301_58_dialog_content = "How about we go back to Mother, Carleen?",
  ui_story_5053_50530301_59_dialog_content = "Can we? Won't it disturb her?",
  ui_story_5053_50530301_60_dialog_content = "Of course it won't. Mother loves you and will get better with you around.",
  ui_story_5053_50530301_61_dialog_content = "I love Mother and you too! And Father!",
  ui_story_5053_50530301_62_dialog_content = "I'll bring her fruit and tell her about the parade when we get back!",
  ui_story_5053_50530301_63_dialog_content = "Hehe, good girl.",
  ui_story_5053_50530301_64_dialog_content = "(It's so wonderful to see Carleen cheerful again.)",
  ui_story_5053_50530301_65_dialog_content = "What do you see?",
  ui_story_5053_50530301_66_dialog_content = "Mia's up there, but I can't see her now... Though Young Schwartz is ready to speak.",
  ui_story_5053_50530301_67_dialog_content = "No sight of the Dark Angel yet.",
  ui_story_5053_50530301_68_dialog_content = "We can hardly see from here. We ought to try another spot.",
  ui_story_5053_50530301_69_dialog_content = "<color=#e8d9bb>Crack! Crack!</color>",
  ui_story_5053_50530301_70_dialog_content = "That sounds like...",
  ui_story_5053_50530301_71_dialog_content = "I don't think we need to try another spot, Caleb.",
  ui_story_5053_50530301_72_dialog_content = "Duck, you two!",
  ui_story_5053_50530301_73_dialog_content = "Over... here!",
  ui_story_5053_50530302_1_dialog_content = "I hereby declare the commencement of the Schwartz Family Day Celebration!",
  ui_story_5053_50530302_2_dialog_content = "Now, let the Showdown Ceremony begin!",
  ui_story_5053_50530302_3_dialog_content = "(How come they haven't shown yet...)",
  ui_story_5053_50530302_4_dialog_content = "(They should be over there, but I can't see them at all...)",
  ui_story_5053_50530302_5_dialog_content = "(Don't tell me the Dark Angel already tracked PlayerName and the others down?)",
  ui_story_5053_50530302_6_dialog_content = "(Should I find an excuse and leave?)",
  ui_story_5053_50530302_7_dialog_content = "Are you looking for something, Vonnie?",
  ui_story_5053_50530302_8_dialog_content = "N-No, Carleen... Look, the showdown has started over there. It sounds like it's going to be exciting.",
  ui_story_5053_50530302_9_dialog_content = "When will they let me participate... I'm every bit as good as them.",
  ui_story_5053_50530302_10_dialog_content = "That's weird, the two duelists just stopped...",
  ui_story_5053_50530302_11_dialog_content = "And they're walking in our direction...",
  ui_story_5053_50530302_12_dialog_content = "Are we getting a bonus show or something?",
  ui_story_5053_50530302_13_dialog_content = "What?",
  ui_story_5053_50530302_14_dialog_content = "(Father is confused, like he doesn't know what's going on.)",
  ui_story_5053_50530302_15_dialog_content = "(I wasn't here back then, so I have no idea what's going to happen now, but this doesn't feel right.)",
  ui_story_5053_50530302_16_dialog_content = "...",
  ui_story_5053_50530302_17_dialog_content = "(Could this be...?!)",
  ui_story_5053_50530302_18_dialog_content = "Father, the assassination was moved forward!",
  ui_story_5053_50530302_19_dialog_content = "How do you know about that? And that it's... moved?",
  ui_story_5053_50530302_20_dialog_content = "It's a long story...",
  ui_story_5053_50530302_21_dialog_content = "What are you doing here? This is not the place for you!",
  ui_story_5053_50530302_22_dialog_content = "...",
  ui_story_5053_50530302_23_dialog_content = "How insolent of you not to respond to me!",
  ui_story_5053_50530302_24_dialog_content = "They do not come in peace... Get back, Duke Hermes!",
  ui_story_5053_50530302_25_dialog_content = "Keep Carleen safe, Veronica!",
  ui_story_5053_50530302_26_dialog_content = "Be careful, Father!",
  ui_story_5053_50530302_27_dialog_content = "Hah!",
  ui_story_5053_50530302_28_dialog_content = "Is this all you got?",
  ui_story_5053_50530302_29_dialog_content = "A sovereign's slash!",
  ui_story_5053_50530302_30_dialog_content = "Ugh...",
  ui_story_5053_50530302_31_dialog_content = "Would you like to try your luck as well?",
  ui_story_5053_50530302_32_dialog_content = "Hah!",
  ui_story_5053_50530302_33_dialog_content = "Take this!",
  ui_story_5053_50530302_34_dialog_content = "Ugh...",
  ui_story_5053_50530302_35_dialog_content = "You survived my blade? Tell me, who sent you?",
  ui_story_5053_50530302_36_dialog_content = "Wait—",
  ui_story_5053_50530302_37_dialog_content = "It is too late to beg for mercy now!",
  ui_story_5053_50530302_38_dialog_content = "Veronica, why is Father whispering to the bad guy?",
  ui_story_5053_50530302_39_dialog_content = "No, I don't think Father's the one threatening him... he has Father by his weapon.",
  ui_story_5053_50530302_40_dialog_content = "<color=#e8d9bb>Crack!</color>",
  ui_story_5053_50530302_41_dialog_content = "Huh?",
  ui_story_5053_50530302_42_dialog_content = "Ha... haha! Soon...",
  ui_story_5053_50530302_43_dialog_content = "Why has his face become so contorted?",
  ui_story_5053_50530302_44_dialog_content = "And why is he laughing when he's injured? What's going on...",
  ui_story_5053_50530302_45_dialog_content = "How is this... What kind of power is this? <color=#FFB400>I can't free my weapon</color>!",
  ui_story_5053_50530302_46_dialog_content = "In this case, Sovereign's...",
  ui_story_5053_50530302_47_dialog_content = "Here it comes...",
  ui_story_5053_50530302_48_dialog_content = "Look up, Father! The sky!",
  ui_story_5053_50530302_49_dialog_content = "<size=45><color=#e8d9bb>Roar—!</color></size>",
  ui_story_5053_50530302_50_dialog_content = "What?",
  ui_story_5053_50530302_51_dialog_content = "T-The wind is too strong! It's going to blow me away!",
  ui_story_5053_50530302_52_dialog_content = "I'm right here, Carleen!",
  ui_story_5053_50530302_53_dialog_content = "Dragon... A <color=#FFB400>dragon</color>? The Kartimas... Are they going to destroy the stand too?!",
  ui_story_5053_50530302_54_dialog_content = "<size=45><color=#e8d9bb>Roar—!</color></size>",
  ui_story_5053_50530302_55_dialog_content = "Carleen, Veronica!",
  ui_story_5053_50530302_56_dialog_content = "Run, quickly!",
  ui_story_5053_50530302_57_dialog_content = "<size=45><color=#e8d9bb>Boom—!!!</color></size>",
  ui_story_5053_50530401_1_dialog_content = "Agh!",
  ui_story_5053_50530401_2_dialog_content = "You're worse than you look!",
  ui_story_5053_50530401_3_dialog_content = "How dare a mere Seed trick me by imitating my sister's voice...",
  ui_story_5053_50530401_4_dialog_content = "I'll have you pay for her sufferings in blood!",
  ui_story_5053_50530401_5_dialog_content = "Hah!",
  ui_story_5053_50530401_6_dialog_content = "...",
  ui_story_5053_50530401_7_dialog_content = "Don't be rash, Caleb!",
  ui_story_5053_50530401_8_dialog_content = "Time to die!",
  ui_story_5053_50530401_9_dialog_content = "Agh!",
  ui_story_5053_50530401_10_dialog_content = "What?!",
  ui_story_5053_50530401_11_dialog_content = "Caleb!!!",
  ui_story_5053_50530401_12_dialog_content = "Ca...leb...?",
  ui_story_5053_50530401_13_dialog_content = "Keep my name off your lips...",
  ui_story_5053_50530401_14_dialog_content = "Now!",
  ui_story_5053_50530401_15_dialog_content = "I will shake every star—!!!",
  ui_story_5053_50530401_16_dialog_content = "Ugh!!!",
  ui_story_5053_50530401_17_dialog_content = "Sch... wartz...",
  ui_story_5053_50530401_18_dialog_content = "Sch...",
  ui_story_5053_50530401_19_dialog_content = "Everything seems back to normal?",
  ui_story_5053_50530401_20_dialog_content = "It's gone... Does it mean it's dead?",
  ui_story_5053_50530401_21_dialog_content = "No, something is wrong. Look over there.",
  ui_story_5053_50530401_22_dialog_content = "Argh—!",
  ui_story_5053_50530401_23_dialog_content = "Run!!!",
  ui_story_5053_50530401_24_dialog_content = "The crowd is fleeing the square... Has the rebellion started?",
  ui_story_5053_50530401_25_dialog_content = "It can't be. Without our interference, it would've started after the assassination...",
  ui_story_5053_50530401_26_dialog_content = "No...",
  ui_story_5053_50530401_27_dialog_content = "Look up in the sky!",
  ui_story_5053_50530401_28_dialog_content = "Roar—!",
  ui_story_5053_50530401_29_dialog_content = "The Kartima dragon?!",
  ui_story_5053_50530401_30_dialog_content = "What's it doing in the city?",
  ui_story_5053_50530401_31_dialog_content = "Oh heavens, what is such a thing doing in Lumopolis...?",
  ui_story_5053_50530401_32_dialog_content = "Shouldn't you guards protect us in times like this? What are you waiting for?",
  ui_story_5053_50530401_33_dialog_content = "...",
  ui_story_5053_50530401_34_dialog_content = "H-Hey, what are you doing?",
  ui_story_5053_50530401_35_dialog_content = "Kill... Kill... Kill...",
  ui_story_5053_50530401_36_dialog_content = "Aaah—!",
  ui_story_5053_50530401_37_dialog_content = "The Sovereign's Blade!",
  ui_story_5053_50530401_38_dialog_content = "What kind of knights are you to harm helpless people? Is this the level Kartimas have stooped to?",
  ui_story_5053_50530401_39_dialog_content = "Oh...",
  ui_story_5053_50530401_40_dialog_content = "T-This one is still alive!",
  ui_story_5053_50530401_41_dialog_content = "Kill...",
  ui_story_5053_50530401_42_dialog_content = "Kill? What are you saying?",
  ui_story_5053_50530401_43_dialog_content = "Sch... wartz...",
  ui_story_5053_50530401_44_dialog_content = "Kill... Kill... Kill the intruders!",
  ui_story_5053_50530401_45_dialog_content = "Out of the way, PlayerName!",
  ui_story_5053_50530401_46_dialog_content = "Why, what's wrong with her...?",
  ui_story_5053_50530401_47_dialog_content = "<color=#e8d9bb><size=45>Boom!</size></color>",
  ui_story_5053_50530401_48_dialog_content = "Such a powerful shockwave. What now?",
  ui_story_5053_50530401_49_dialog_content = "The explosion is coming from the stand!",
  ui_story_5053_50530401_50_dialog_content = "The City Lord has been attacked!",
  ui_story_5053_50530401_51_dialog_content = "Run for your lives!",
  ui_story_5053_50530401_52_dialog_content = "Attacked? Mia...!",
  ui_story_5053_50530401_53_dialog_content = "If Mia was still on the stand... No, it can't be...",
  ui_story_5053_50530401_54_dialog_content = "My sister is still at the Schwartz mansion. If the rebels find her...",
  ui_story_5053_50530401_55_dialog_content = "PlayerName, leave with Caleb!",
  ui_story_5053_50530401_56_dialog_content = "If I don't come back with Mia, tell Jakine to rewind immediately!",
  ui_story_5053_50530401_57_dialog_content = "Lord Schwartz!!!",
  ui_story_5053_50530401_58_dialog_content = "(What's going on? Is the Crystal of Eternal Memory broken?)",
  ui_story_5053_50530401_59_dialog_content = "(Or maybe the Dark Angel is still alive and this is all her doing...?)",
  ui_story_5053_50530401_60_dialog_content = "Don't just stand there! We need to get out of here!",
  ui_story_5053_50530401_61_dialog_content = "Kill... Kill... Kill...",
  ui_story_5053_50530402_1_dialog_content = "Hah!",
  ui_story_5053_50530402_2_dialog_content = "Ugh...",
  ui_story_5053_50530402_3_dialog_content = "Damn the rebels... Thank you for the help, old man.",
  ui_story_5053_50530402_4_dialog_content = "Where are the highnesses?",
  ui_story_5053_50530402_5_dialog_content = "The highnesses? You ought to be thinking about keeping yourself alive.",
  ui_story_5053_50530402_6_dialog_content = "What do you mean by that?",
  ui_story_5053_50530402_7_dialog_content = "Princess Carleen, Princess Veronica and the City Lord were attacked by the dragon... <color=#FFB400>They're dead</color>!",
  ui_story_5053_50530402_8_dialog_content = "Where? Where is Princess Veronica?!",
  ui_story_5053_50530402_9_dialog_content = "Still on the stand. Don't tell me you want to go collect their remains at a time like this?",
  ui_story_5053_50530402_10_dialog_content = "Thanks.",
  ui_story_5053_50530402_11_dialog_content = "Fool... Clinging to what you've already lost will only cost you your life.",
  ui_story_5053_50530402_12_dialog_content = "Joshua!",
  ui_story_5053_50530402_13_dialog_content = "Lady Joshua! Jakine! Where are you?",
  ui_story_5053_50530402_14_dialog_content = "Why aren't they responding... Joshua!",
  ui_story_5053_50530402_15_dialog_content = "I'm here, Caleb.",
  ui_story_5053_50530402_16_dialog_content = "Thank goodness you're all right! I thought I'd lost you again...",
  ui_story_5053_50530402_17_dialog_content = "The insurgence was moved up. We have to get you to somewhere safe.",
  ui_story_5053_50530402_18_dialog_content = "Where's Jakine? Where in the world has she gone at a time like this?",
  ui_story_5053_50530402_19_dialog_content = "Stay calm, Caleb, one thing at a time.",
  ui_story_5053_50530402_20_dialog_content = "You're sweating everywhere, even your collar's wrinkled. Here, let me fix it for you.",
  ui_story_5053_50530402_21_dialog_content = "Huh? Uh, I can handle that myself...",
  ui_story_5053_50530402_22_dialog_content = "T-Thanks, sis.",
  ui_story_5053_50530402_23_dialog_content = "Lady Joshua is all right, but where did Jakine run off to?",
  ui_story_5053_50530402_24_dialog_content = "Where are you, Jakine?!!",
  ui_story_5053_50530402_25_dialog_content = "Ugh...",
  ui_story_5053_50530402_26_dialog_content = "Si... s...?",
  ui_story_5053_50530402_27_dialog_content = "What's wrong, Caleb?",
  ui_story_5053_50530402_28_dialog_content = "T-This...",
  ui_story_5053_50530402_29_dialog_content = "But... why?",
  ui_story_5053_50530402_30_dialog_content = "Your chest, Caleb?!",
  ui_story_5053_50530402_31_dialog_content = "Did you get hurt on the way? N-No, can't be...",
  ui_story_5053_50530402_32_dialog_content = "Why do you still like sitting on the ground at your age?",
  ui_story_5053_50530402_33_dialog_content = "Still immature as ever, Caleb.",
  ui_story_5053_50530402_34_dialog_content = "How disappointing.",
  ui_story_5053_50530402_35_dialog_content = "Why...",
  ui_story_5053_50530402_36_dialog_content = "Sis...",
  ui_story_5053_50530402_37_dialog_content = "Mia...",
  ui_story_5053_50530402_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_39_dialog_content = "I know we can rewind time...",
  ui_story_5053_50530402_40_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_41_dialog_content = "But I do not want you to go through this...",
  ui_story_5053_50530402_42_dialog_content = "Even if you hate me for sending you away from me, I will be at peace knowing you are safe and sound...",
  ui_story_5053_50530402_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_44_dialog_content = "<size=45>Roar—!</size>",
  ui_story_5053_50530402_45_dialog_content = "Do you want to kill me still, after killing my family?",
  ui_story_5053_50530402_46_dialog_content = "I will repay you twofold the pain you have dealt to them...",
  ui_story_5053_50530402_47_dialog_content = "<size=45>Roar—!</size>",
  ui_story_5053_50530402_48_dialog_content = "<size=45>Now die!!!</size>",
  ui_story_5053_50530402_49_dialog_content = "<color=#e8d9bb>Thud, thud...</color>",
  ui_story_5053_50530402_50_dialog_content = "(Why, why, why?!)",
  ui_story_5053_50530402_51_dialog_content = "(Why did Lady Joshua kill Caleb, her own brother?!)",
  ui_story_5053_50530402_52_dialog_content = "<color=#e8d9bb>Thud, thud, thud...</color>",
  ui_story_5053_50530402_53_dialog_content = "(Has everyone in this world gone mad?)",
  ui_story_5053_50530402_54_dialog_content = "(Or am I trapped in a never-ending nightmare?)",
  ui_story_5053_50530402_55_dialog_content = "<color=#e8d9bb>Thud, thud, thud...</color>",
  ui_story_5053_50530402_56_dialog_content = "(Is she gone?)",
  ui_story_5053_50530402_57_dialog_content = "(But I can't hide under the table forever... What am I gonna do?)",
  ui_story_5053_50530402_58_dialog_content = "<color=#e8d9bb>Thud, thud.</color>",
  ui_story_5053_50530402_59_dialog_content = "(The footsteps stopped...)",
  ui_story_5053_50530402_60_dialog_content = "I FOUND YOU!",
  ui_story_5053_50530402_61_dialog_content = "What?!",
  ui_story_5053_50530402_62_dialog_content = "Oh, dear, not even Carleen still plays hide-and-seek.",
  ui_story_5053_50530402_63_dialog_content = "You're not a kid anymore, PlayerName. How long do you want me to keep playing games with you?",
  ui_story_5053_50530402_64_dialog_content = "Huff... puff...",
  ui_story_5053_50530402_65_dialog_content = "Stop running. That'll only make your death more agonizing.",
  ui_story_5053_50530402_66_dialog_content = "Mia, Caleb... Their Lumina is nice. I've never felt so invigorated.",
  ui_story_5053_50530402_67_dialog_content = "I wonder what happens if I take a Caelestite's Lumina? Maybe I can read others' minds too?",
  ui_story_5053_50530402_68_dialog_content = "I won't let you get away with this!",
  ui_story_5053_50530402_69_dialog_content = "Well, I can control people in this world already.",
  ui_story_5053_50530402_70_dialog_content = "That sure makes things simple and easy, doesn't it?",
  ui_story_5053_50530402_71_dialog_content = "Huff... puff...",
  ui_story_5053_50530402_72_dialog_content = "(Only one door ahead of me... Please don't let it be a dead end!)",
  ui_story_5053_50530402_73_dialog_content = "That's... Well, I guess that's The Last Caelestite's instinct.",
  ui_story_5053_50530402_74_dialog_content = "Nice pick.",
  ui_story_5053_50530402_75_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5053_50530402_76_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_77_dialog_content = "Jakine?!",
  ui_story_5053_50530402_78_dialog_content = "Jakine! Her body's cold and she's not breathing...",
  ui_story_5053_50530402_79_dialog_content = "You sure know how to pick a spot, PlayerName.",
  ui_story_5053_50530402_80_dialog_content = "The Northland seer could control the Crystal, so naturally, she was the first one I killed.",
  ui_story_5053_50530402_81_dialog_content = "Why else would I have asked her to stay with me?",
  ui_story_5053_50530402_82_dialog_content = "I don't get it, Lady Joshua, why are you doing this?",
  ui_story_5053_50530402_83_dialog_content = "Why would you kill Jakine and your brother... And me too?",
  ui_story_5053_50530402_84_dialog_content = "Is it so hard to understand? I need your powers.",
  ui_story_5053_50530402_85_dialog_content = "I bear you no ill will, but your sacrifices are necessary.",
  ui_story_5053_50530402_86_dialog_content = "I don't understand, are you the real Joshua?",
  ui_story_5053_50530402_87_dialog_content = "What are you, really?",
  ui_story_5053_50530402_88_dialog_content = "I am Joshua, the real Joshua!",
  ui_story_5053_50530402_89_dialog_content = "Open your eyes wide and take a good look. Remember this before you die.",
  ui_story_5053_50530402_90_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5053_50530402_91_dialog_content = "What?",
  ui_story_5053_50530402_92_dialog_content = "Come over to me, PlayerName...",
  ui_story_5053_50530402_93_dialog_content = "Jakine?!",
  ui_story_5053_50530402_94_dialog_content = "You're alive? I thought you were...",
  ui_story_5053_50530402_95_dialog_content = "Did you forget? I've been a wandering fortune-teller since I was little...",
  ui_story_5053_50530402_96_dialog_content = "What's a little trick? ... (Starts coughing)",
  ui_story_5053_50530402_97_dialog_content = "Jakine!",
  ui_story_5053_50530402_98_dialog_content = "Where are the others?",
  ui_story_5053_50530402_99_dialog_content = "...",
  ui_story_5053_50530402_100_dialog_content = "Curses...!",
  ui_story_5053_50530402_101_dialog_content = "Casting illusions with Northland magic... No wonder you people could create something like the Crystal of Eternal Memory.",
  ui_story_5053_50530402_102_dialog_content = "What revolting intelligence.",
  ui_story_5053_50530402_103_dialog_content = "Sorry, I've always been a naughty kid.",
  ui_story_5053_50530402_104_dialog_content = "Then allow me to show you some discipline!",
  ui_story_5053_50530402_105_dialog_content = "On guard, crystal ball!",
  ui_story_5053_50530402_106_dialog_content = "Get that Crystal of Eternal Memory over here, PlayerName.",
  ui_story_5053_50530402_107_dialog_content = "Put your hand on it. Even if I can't make it...",
  ui_story_5053_50530402_108_dialog_content = "You mustn't let go.",
  ui_story_5053_50530402_109_dialog_content = "Got it!",
  ui_story_5053_50530402_110_dialog_content = "Reditus, reditus, reditus!",
  ui_story_5053_50530402_111_dialog_content = "Rewind to the beginning...",
  ui_story_5053_50530402_112_dialog_content = "Abracadabra—Urgh!",
  ui_story_5053_50530402_113_dialog_content = "Oh no...",
  ui_story_5053_50530402_114_dialog_content = "Jakine... Jakine—!",
  ui_story_5053_50530501_0X_dialog_content = "<color=#e8d9bb>After the second reset—</color>",
  ui_story_5053_50530501_1_dialog_content = "Everything is set, my lord.",
  ui_story_5053_50530501_2_dialog_content = "The carriage awaits outside and is ready to depart anytime.",
  ui_story_5053_50530501_3_dialog_content = "...",
  ui_story_5053_50530501_4_dialog_content = "My lord, are you still concerned about your wife?",
  ui_story_5053_50530501_5_dialog_content = "Joshua has always been in good health and she wouldn't usually complain about feeling under the weather. Especially not on a day like this.",
  ui_story_5053_50530501_6_dialog_content = "She has been quite busy lately, advocating the new policies to the nobles' wives. I imagine it's taken a toll on her.",
  ui_story_5053_50530501_7_dialog_content = "Rest assured, my lord. I will take good care of her.",
  ui_story_5053_50530501_8_dialog_content = "Urgh...",
  ui_story_5053_50530501_9_dialog_content = "Where am I...?",
  ui_story_5053_50530501_10_dialog_content = "Wait, this place... Is it still daytime outside?",
  ui_story_5053_50530501_11_dialog_content = "I was being chased, and I ran into Jakine, then...",
  ui_story_5053_50530501_12_dialog_content = "(Thanks for saving me, Jakine...)",
  ui_story_5053_50530501_13_dialog_content = "(But I don't see her anywhere around here... Could it be that we got separated, just like when we first arrived inside the Crystal?)",
  ui_story_5053_50530501_14_dialog_content = "(And why did Lady Joshua attack us like that? Is it possible that she wasn't the real Joshua?)",
  ui_story_5053_50530501_15_dialog_content = "(No, she was <color=#FFB400>a real person</color>, just like the rest of us. Jakine proved it using the Crystal of Eternal Memory.)",
  ui_story_5053_50530501_16_dialog_content = "I am Joshua, the real Joshua.",
  ui_story_5053_50530501_17_dialog_content = "(The way she emphasized her identity... what was that supposed to mean?)",
  ui_story_5053_50530501_18_dialog_content = "(I'm so confused, but that's not important right now. If something really is wrong with Joshua, how are we supposed to get back?)",
  ui_story_5053_50530501_19_dialog_content = "(Aaah... There's so much going on that I don't understand, and why am I the only one here?!)",
  ui_story_5053_50530501_20_dialog_content = "<color=#e8d9bb>Pit, pat, pit, pat—</color>",
  ui_story_5053_50530501_21_dialog_content = "That sound! Is that...?",
  ui_story_5053_50530501_22_dialog_content = "Here...?",
  ui_story_5053_50530501_23_dialog_content = "How did the Dark Angel find us here? I thought we reset everything!",
  ui_story_5053_50530501_24_dialog_content = "Th-That's my sister's voice...",
  ui_story_5053_50530501_25_dialog_content = "... Here!",
  ui_story_5053_50530501_26_dialog_content = "White Night, protect us!",
  ui_story_5053_50530501_27_dialog_content = "Do not lose your focus in battle, Caleb!",
  ui_story_5053_50530501_28_dialog_content = "Aaaah—!",
  ui_story_5053_50530501_29_dialog_content = "The Sovereign's Blade!",
  ui_story_5053_50530501_30_dialog_content = "I... Hate...",
  ui_story_5053_50530501_31_dialog_content = "Urgh!",
  ui_story_5053_50530501_32_dialog_content = "That's fast! Be careful, Lord Schwartz!",
  ui_story_5053_50530501_33_dialog_content = "Are you so desperate to fight me one-on-one?",
  ui_story_5053_50530501_34_dialog_content = "I shall grant your wish, then.",
  ui_story_5053_50530501_35_dialog_content = "Sch... Schwartz...!",
  ui_story_5053_50530501_36_dialog_content = "Mia and the others are fighting that Dark Angel again... So we did manage to start the memory over!",
  ui_story_5053_50530501_37_dialog_content = "I need to get over there and help them!",
  ui_story_5053_50530501_38_dialog_content = "You, there... Halt.",
  ui_story_5053_50530501_39_dialog_content = "A guard? Perfect timing! Look, I—",
  ui_story_5053_50530501_40_dialog_content = "Suspect... Exterminate...",
  ui_story_5053_50530501_41_dialog_content = "(Huh? Something seems off about these people?)",
  ui_story_5053_50530501_42_dialog_content = "What are you guys talking about?",
  ui_story_5053_50530501_43_dialog_content = "Lady Joshua... someone... intruders?",
  ui_story_5053_50530501_44_dialog_content = "Intruders... Must capture... and kill!",
  ui_story_5053_50530501_45_dialog_content = "(Something's definitely wrong with their minds! They're just like the people from the central square!)",
  ui_story_5053_50530501_46_dialog_content = "Aaaah!!!",
  ui_story_5053_50530502_1_dialog_content = "<color=#e8d9bb>Boom—!!</color>",
  ui_story_5053_50530502_2_dialog_content = "Urgh... Cough, cough...",
  ui_story_5053_50530502_3_dialog_content = "Where did it go?",
  ui_story_5053_50530502_4_dialog_content = "Probably fled on a trail to the outside...",
  ui_story_5053_50530502_5_dialog_content = "That was awesome, Lord Schwartz!",
  ui_story_5053_50530502_6_dialog_content = "The angel gotta be hurt, as powerful as it is, and probably can't go too far.",
  ui_story_5053_50530502_7_dialog_content = "...",
  ui_story_5053_50530502_8_dialog_content = "Are you still bothered about the Dark Angel, Uncle?",
  ui_story_5053_50530502_9_dialog_content = "Its voice... Never mind, my sister could never be a monster.",
  ui_story_5053_50530502_10_dialog_content = "Wait, aren't we forgetting something? Oh no, where's PlayerName?!",
  ui_story_5053_50530502_11_dialog_content = "Hey, you're right! Where did PlayerName run off to?!",
  ui_story_5053_50530502_12_dialog_content = "Oh, there you all are!",
  ui_story_5053_50530502_13_dialog_content = "Phew... Did I lose them?",
  ui_story_5053_50530502_14_dialog_content = "Over there... Over there!",
  ui_story_5053_50530502_15_dialog_content = "Kill the intruder!",
  ui_story_5053_50530502_16_dialog_content = "(Crap! Even though they're mindless now, these guards are still impossible to shake!)",
  ui_story_5053_50530502_17_dialog_content = "No... Right there!",
  ui_story_5053_50530502_18_dialog_content = "(... Wait, I've got it!)",
  ui_story_5053_50530502_19_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5053_50530502_20_dialog_content = "(What's this cart, anyway? It must be for the holiday... Either way, I think they won't see me here.)",
  ui_story_5053_50530502_21_dialog_content = "Not there... Where?",
  ui_story_5053_50530502_22_dialog_content = "That street... Go...",
  ui_story_5053_50530502_23_dialog_content = "Those guards are acting so strangely. Are they after somebody?",
  ui_story_5053_50530502_24_dialog_content = "I'm not sure, but who would want to start trouble on a day like this? The parade is about to begin too!",
  ui_story_5053_50530502_25_dialog_content = "I can't wait to see it!",
  ui_story_5053_50530502_26_dialog_content = "(Phew! I finally managed to lose them...)",
  ui_story_5053_50530502_27_dialog_content = "(According to that girl, it looks like the parade hasn't started yet.)",
  ui_story_5053_50530502_28_dialog_content = "(Good. That gives me some time to gather my thoughts and figure out my next move.)",
  ui_story_5053_50530502_29_dialog_content = "(I've got some serious questions to consider right now...)",
  ui_story_5053_50530502_30_option_content = "The current situation",
  ui_story_5053_50530502_31_dialog_content = "(The parade still hasn't started, and everyone should have seen Lady Joshua by now.)",
  ui_story_5053_50530502_32_dialog_content = "(That means there are two possible scenarios right now, both of which depend on <color=#FFB400>whether or not everyone remembers the time reset</color>.)",
  ui_story_5053_50530502_33_dialog_content = "(If everyone still remembers, then they must have already fought Lady Joshua and escaped.)",
  ui_story_5053_50530502_34_dialog_content = "(If that's the case, the others should be out looking for me right now. I'm still not too familiar with Lumopolis, so I should just keep my head down and wait for them to find me.)",
  ui_story_5053_50530502_35_dialog_content = "(But if no one remembers the time reset, then they probably fell for Joshua's trap...)",
  ui_story_5053_50530502_36_dialog_content = "(If so, then everything should happen exactly as it did before the reset. Jakine will get left behind, and the others will make their way to the central square.)",
  ui_story_5053_50530502_37_dialog_content = "(I happen to be pretty close to the square too. Looks like my best bet is to sit here and wait for everyone to arrive.)",
  ui_story_5053_50530502_38_dialog_content = "(But then there's Jakine... Drat! We won't be able to rescue her until the others get here!)",
  ui_story_5053_50530502_39_option_content = "The \"memory\"",
  ui_story_5053_50530502_40_dialog_content = "(According to Jakine, using divination for any reason requires a <color=#FFB400>strict adherence to its rules</color>.)",
  ui_story_5053_50530502_41_dialog_content = "(During the first reset, Jakine kept telling us to <color=#FFB400>hold on tightly to each other's hands</color>.)",
  ui_story_5053_50530502_42_dialog_content = "(Joshua also said that this was the reason she could remember the events of the first reset. It was because she was with us when it happened.)",
  ui_story_5053_50530502_43_dialog_content = "(Does that mean she managed to hold onto our hands without us noticing?)",
  ui_story_5053_50530502_44_dialog_content = "(During the second reset, the only ones holding onto the Crystal of Eternal Memory were Jakine and me.)",
  ui_story_5053_50530502_45_dialog_content = "(That would mean Joshua and the others don't remember the second reset, right?)",
  ui_story_5053_50530502_46_dialog_content = "(Jakine and I should be the only ones who remember everything that's happened since we got here...)",
  ui_story_5053_50530502_47_dialog_content = "(Or at least I hope so.)",
  ui_story_5053_50530502_48_option_content = "The dragon, the soldiers, and the Dark Angel",
  ui_story_5053_50530502_49_dialog_content = "(What was the deal with those guards just now? Why were they trying to capture me?)",
  ui_story_5053_50530502_50_dialog_content = "(They were just as crazy as the people from the central square. It's like they came down with some mysterious illness... Or they were being mind-controlled.)",
  ui_story_5053_50530502_51_dialog_content = "(Given how determined they were to hunt me down, I'd say they were trying to keep me apart from the others. They kept chasing me, forcing me to leave the mansion.)",
  ui_story_5053_50530502_52_dialog_content = "(I can't use my psychic powers inside the Crystal of Eternal Memory, so I had no way of knowing what was going on upstairs while everyone was fighting.)",
  ui_story_5053_50530502_53_dialog_content = "(And I ended up missing my chance to meet back up with them...)",
  ui_story_5053_50530502_54_dialog_content = "(If Joshua still has her memories, then she must have sent those soldiers to silence me.)",
  ui_story_5053_50530502_55_dialog_content = "(But if she doesn't, then she must have ordered them to simply kill off any stragglers.)",
  ui_story_5053_50530502_56_dialog_content = "(Just like the first time we got separated from Jakine.)",
  ui_story_5053_50530502_57_dialog_content = "(Fighting against the Dark Angel must be part of her plan too. That way, she can split us up and finish off Jakine!)",
  ui_story_5053_50530502_58_dialog_content = "(At this point, it's clear that the guards who chased me are working for her...)",
  ui_story_5053_50530502_59_dialog_content = "(It's probably safe to assume the crazy people from the square and that black dragon are also under her control.)",
  ui_story_5053_50530502_60_dialog_content = "(Which means that everything we went through since the first reset was all part of her plan... How terrifying.)",
  ui_story_5053_50530502_61_dialog_content = "(But what about the Dark Angel? What's her connection to Joshua?)",
  ui_story_5053_50530502_62_dialog_content = "(Are the two of them working together? Or is there more to the story than that...?)",
  ui_story_5053_50530502_63_dialog_content = "(I just don't have enough information to work with right now.)",
  ui_story_5053_50530502_64_dialog_content = "(Sigh... all that being said, sitting here and waiting for the others is still my best course of action.)",
  ui_story_5053_50530502_65_dialog_content = "(I'll tell everyone the truth once they find me, so we can go save Jakine...)",
  ui_story_5053_50530502_66_dialog_content = "(I just hope they're all okay!)",
  ui_story_5053_50530601_1_dialog_content = "So you're saying...",
  ui_story_5053_50530601_2_dialog_content = "We can either destroy the Dark Angel and bring Lady Joshua with us out of here....",
  ui_story_5053_50530601_3_dialog_content = "... or the Dark Angel kills us and gets loose in the real world?",
  ui_story_5053_50530601_4_dialog_content = "That is correct, yes.",
  ui_story_5053_50530601_5_dialog_content = "...",
  ui_story_5053_50530601_6_dialog_content = "I understand our escape plan perfectly fine, but...",
  ui_story_5053_50530601_7_dialog_content = "Where is PlayerName? I'm really starting to worry about him.",
  ui_story_5053_50530601_8_dialog_content = "He's been apart from us for too long. Something must have happened to him!",
  ui_story_5053_50530601_9_dialog_content = "I'm just as unsure of his present situation, but don't worry, I'll send a team of guards to search for him.",
  ui_story_5053_50530601_10_dialog_content = "We're running out of time. If we wish to escape from this place safely, the priority goes to defeating that monster.",
  ui_story_5053_50530601_11_dialog_content = "Then let's go hunt down that Dark Angel!",
  ui_story_5053_50530601_12_dialog_content = "No, Jakine. You need to stay here with me.",
  ui_story_5053_50530601_13_dialog_content = "Huh? But how come? My crystal ball is pretty useful in a fight too!",
  ui_story_5053_50530601_14_dialog_content = "Yes, I know, but you operate the Crystal.",
  ui_story_5053_50530601_15_dialog_content = "If the others get hurt, we can always turn back time to restore everything.",
  ui_story_5053_50530601_16_dialog_content = "But if anything were to happen to you, it would be irreversible.",
  ui_story_5053_50530601_17_dialog_content = "T-That's true...",
  ui_story_5053_50530601_18_dialog_content = "Mother? I-If you and Jakine are going to stay here, then Carleen should come back too.",
  ui_story_5053_50530601_19_dialog_content = "I don't want her and Father to feel lonely without us there.",
  ui_story_5053_50530601_20_dialog_content = "Very well. I'll have a guard call her back to her room to get some rest.",
  ui_story_5053_50530601_21_dialog_content = "You don't want her here with us, Mother? She's been looking forward to this day for so long, why send her back to her room all by herself?",
  ui_story_5053_50530601_22_dialog_content = "Won't she feel bad if she misses the parade...?",
  ui_story_5053_50530601_23_dialog_content = "My sweet Vonnie... None of this is real. The world within the Crystal of Eternal Memory is nothing more than an illusion.",
  ui_story_5053_50530601_24_dialog_content = "We must follow the predetermined course of events. Don't let any unnecessary concerns distract you from your objective.",
  ui_story_5053_50530601_25_dialog_content = "Oh...",
  ui_story_5053_50530601_26_dialog_content = "My sister is right, Mia. This is all a fantasy, so don't let your emotions get the better of you.",
  ui_story_5053_50530601_27_dialog_content = "A-All right. Sorry for being so immature...",
  ui_story_5053_50530601_28_dialog_content = "...",
  ui_story_5053_50530601_29_dialog_content = "Joshua makes a valid point. Everyone's safety should be our highest priority, which is why Caleb should also stay here.",
  ui_story_5053_50530601_30_dialog_content = "I'll search for PlayerName myself. For now, everyone else should stay together.",
  ui_story_5053_50530601_31_dialog_content = "That won't be necessary. A team of guards can find PlayerName just as quickly, if not more so.",
  ui_story_5053_50530601_32_dialog_content = "Besides, we need everyone's strength if we hope to stand a chance against that monster.",
  ui_story_5053_50530601_33_dialog_content = "I think you know as well as I do which of these matters is more important. Use your common sense, Daniel.",
  ui_story_5053_50530601_34_dialog_content = "Heh, your judgment is as sharp as ever, Joshua. I must say, this really takes me back to our old days.",
  ui_story_5053_50530601_35_dialog_content = "...",
  ui_story_5053_50530601_36_dialog_content = "Is this really a good time for nostalgia, you two? We're still racing against the clock.",
  ui_story_5053_50530601_37_dialog_content = "In any case, I'm perfectly capable of weighing the options for myself.",
  ui_story_5053_50530601_38_dialog_content = "Let's go, Mia.",
  ui_story_5053_50530601_39_dialog_content = "Y-Yes, Father.",
  ui_story_5053_50530601_40_dialog_content = "What's with that man, acting so strangely all of a sudden?!",
  ui_story_5053_50530601_41_dialog_content = "...",
  ui_story_5053_50530601_42_dialog_content = "Is something about Joshua bothering you, Mia?",
  ui_story_5053_50530601_43_dialog_content = "Ah! Um, well... M-Maybe a little...",
  ui_story_5053_50530601_44_dialog_content = "It's probably just me, but... after being apart from her for so long, Mother feels somewhat unfamiliar.",
  ui_story_5053_50530601_45_dialog_content = "Tell me, what kind of person is Joshua to you?",
  ui_story_5053_50530601_46_dialog_content = "M-Mother is... Mother is the kindest and most patient person I've ever known, and she loves children more than anything.",
  ui_story_5053_50530601_47_dialog_content = "Yes, the Joshua in my heart is also a warm, kind-hearted woman, one of the most steadfast and sincere people I've ever met.",
  ui_story_5053_50530601_48_dialog_content = "Father...!",
  ui_story_5053_50530601_49_dialog_content = "Believe in yourself, Mia. And believe in the beautiful image of your mother that you keep in your heart.",
  ui_story_5053_50530601_50_dialog_content = "Believe in me?",
  ui_story_5053_50530601_51_dialog_content = "Despite your usual clumsiness, you have shown a stronger, braver side of yourself throughout this ordeal.",
  ui_story_5053_50530601_52_dialog_content = "I think it is time for me to accept that you've grown up.",
  ui_story_5053_50530601_53_dialog_content = "From now on, I promise to respect your opinions instead of telling you how to feel.",
  ui_story_5053_50530601_54_dialog_content = "There's no need to hesitate any longer, Mia. Whether it has to do with your mother, or Carleen, or anything else...",
  ui_story_5053_50530601_55_dialog_content = "Do whatever you feel is right, and do it bravely. I will always have faith in you.",
  ui_story_5053_50530601_56_dialog_content = "(Is Father... Encouraging me?)",
  ui_story_5053_50530601_57_dialog_content = "(I've never heard him say anything like this before. It feels... nice.)",
  ui_story_5053_50530601_58_dialog_content = "Thank you, Father. I promise to become more decisive from now on.",
  ui_story_5053_50530601_59_dialog_content = "I'll be on the stand to keep a lookout, just like we planned. If I see any sign of the Dark Angel, I'll let everyone know.",
  ui_story_5053_50530601_60_dialog_content = "Good. Be on your guard, Mia.",
  ui_story_5053_50530601_61_dialog_content = "(Mia should be safe over there for the time being. PlayerName, on the other hand... Where could he be right now?)",
  ui_story_5053_50530601_62_dialog_content = "(His absence feels extremely suspicious now, but why...?)",
  ui_story_5053_50530601_63_dialog_content = "Over... Here...",
  ui_story_5053_50530601_64_dialog_content = "... Here!",
  ui_story_5053_50530601_65_dialog_content = "That voice...",
  ui_story_5053_50530601_66_dialog_content = "Sch... Schwartz...!!!",
  ui_story_5053_50530601_67_dialog_content = "Aaaaaaah!!!",
  ui_story_5053_50530601_68_dialog_content = "So this is where you've been.",
  ui_story_5053_50530601_69_dialog_content = "Good. So long as you're here, no one else is in danger.",
  ui_story_5053_50530601_70_dialog_content = "Hurts! Die... Die!!!",
  ui_story_5053_50530601_71_dialog_content = "You won't fool me by impersonating Joshua.",
  ui_story_5053_50530701_1_dialog_content = "Urgh... Aaaaah!",
  ui_story_5053_50530701_2_dialog_content = "(Without Mia or Caleb here, it seems we're evenly matched. Unfortunately, these Eclipsites are tilting the scales slightly in her favor.)",
  ui_story_5053_50530701_3_dialog_content = "\"White Night, protect us!\"",
  ui_story_5053_50530701_4_dialog_content = "I would say we've reached a stalemate. Are you satisfied now?",
  ui_story_5053_50530701_5_dialog_content = "Sch... Schwartz...!",
  ui_story_5053_50530701_6_dialog_content = "I... Hate... You...!",
  ui_story_5053_50530701_7_dialog_content = "Why...",
  ui_story_5053_50530701_8_dialog_content = "It hurts... so much! Why... Why... betray me?!",
  ui_story_5053_50530701_9_dialog_content = "You said... We build... future together! You promised...!",
  ui_story_5053_50530701_10_dialog_content = "So why... sacrifice... family?!",
  ui_story_5053_50530701_11_dialog_content = "The pain... is unbearable!!!",
  ui_story_5053_50530701_12_dialog_content = "What are you saying?",
  ui_story_5053_50530701_13_dialog_content = "If only... If only I knew...",
  ui_story_5053_50530701_14_dialog_content = "I would never... love...",
  ui_story_5053_50530701_15_dialog_content = "And... chose you!!!",
  ui_story_5053_50530701_16_dialog_content = "?!",
  ui_story_5053_50530701_17_dialog_content = "Joshua...?!",
  ui_story_5053_50530701_18_dialog_content = "But how could this be?",
  ui_story_5053_50530701_19_dialog_content = "...!!!",
  ui_story_5053_50530701_20_dialog_content = "Ahh...! M... Mia... danger...",
  ui_story_5053_50530701_21_dialog_content = "Where do you think you're going?!",
  ui_story_5053_50530701_22_dialog_content = "Graah—!",
  ui_story_5053_50530701_23_dialog_content = "Out of my way, nasty creatures!",
  ui_story_5053_50530701_24_dialog_content = "(Young Schwartz just finished his speech, which means the duel is about to begin.)",
  ui_story_5053_50530701_25_dialog_content = "(If everything goes as expected, the dragon will appear soon and the people will panic, along with the guards...)",
  ui_story_5053_50530701_26_dialog_content = "(Once that happens, I can take advantage of the chaos and run over to the stand! I have to meet up with the others and tell them about Joshua before it's too late!)",
  ui_story_5053_50530701_27_dialog_content = "Roar—!",
  ui_story_5053_50530701_28_dialog_content = "Aaaah!!!",
  ui_story_5053_50530701_29_dialog_content = "Wh-What's that thing?!",
  ui_story_5053_50530701_30_dialog_content = "Run! Help me!!!",
  ui_story_5053_50530701_31_dialog_content = "Alright! Now's my chance to look for Lord Schwartz and the others—",
  ui_story_5053_50530701_32_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5053_50530701_33_dialog_content = "Whoa...! Wh-What was that?!",
  ui_story_5053_50530701_34_dialog_content = "Roar—!",
  ui_story_5053_50530701_35_dialog_content = "<color=#e8d9bb>BOOM!!!</color>",
  ui_story_5053_50530701_36_dialog_content = "Aaaah...! Urgh!!!",
  ui_story_5053_50530701_37_dialog_content = "The Dark Angel?! What's going on?!",
  ui_story_5053_50530701_38_dialog_content = "What's she doing in the sky? Is she blocking the dragon's attack?",
  ui_story_5053_50530701_39_dialog_content = "A flying dragon?!",
  ui_story_5053_50530701_40_dialog_content = "Long live the dragon! Long live the dragon!!!",
  ui_story_5053_50530701_41_dialog_content = "House Kartima? So they're the traitors all along?",
  ui_story_5053_50530701_42_dialog_content = "How bold of them to show their true colors at a time like this.",
  ui_story_5053_50530701_43_dialog_content = "(But what's that other monster in the sky...?)",
  ui_story_5053_50530701_44_dialog_content = "S-Sister! What's happening?",
  ui_story_5053_50530701_45_dialog_content = "Get behind me, Carleen!",
  ui_story_5053_50530701_46_dialog_content = "(It's the Dark Angel! But why is she here?)",
  ui_story_5053_50530701_47_dialog_content = "What on earth is...?!",
  ui_story_5053_50530701_48_dialog_content = "Veronica! Carleen! Stay back!",
  ui_story_5053_50530701_49_dialog_content = "<color=#e8d9bb>Smash—!</color>",
  ui_story_5053_50530701_50_dialog_content = "(She got hit by the dragon's flames! No, wait... It looks like she's blocking its attacks!)",
  ui_story_5053_50530701_51_dialog_content = "But why is she...",
  ui_story_5053_50530701_52_dialog_content = "Veronica, it looks like she's helping us fend off the dragon!",
  ui_story_5053_50530701_53_dialog_content = "D-Did she lose consciousness?",
  ui_story_5053_50530701_54_dialog_content = "The Dark Angel... I don't understand...",
  ui_story_5053_50530701_55_dialog_content = "Mia!!!",
  ui_story_5053_50530701_56_dialog_content = "Mia! Are you okay?!",
  ui_story_5053_50530701_57_dialog_content = "PlayerName? I'm fine, don't worry! Where have you been all this time?",
  ui_story_5053_50530701_58_dialog_content = "O-Over here...!",
  ui_story_5053_50530701_59_dialog_content = "Kill... Kill the intruder!",
  ui_story_5053_50530701_60_dialog_content = "Drat! Not them again!",
  ui_story_5053_50530701_61_dialog_content = "What's the matter with those guards?!",
  ui_story_5053_50530701_62_dialog_content = "Long live the dragon! Long live the dragon!!!",
  ui_story_5053_50530701_63_dialog_content = "Attack!",
  ui_story_5053_50530701_64_dialog_content = "Look out, PlayerName! The rebels are joining the fight too!",
  ui_story_5053_50530701_65_dialog_content = "I'll have to explain things later, Mia. Right now, we need to get ready for the fight!",
  ui_story_5053_50530701_66_dialog_content = "It doesn't matter how many flying monsters or traitorous scum decide to show their faces today! In the name of House Schwartz, all of you will be punished for ruining this day!",
  ui_story_5053_50530701_67_dialog_content = "Roar!!!",
  ui_story_5053_50530701_68_dialog_content = "Be careful! Leave the Dark Angel alone for the time being.",
  ui_story_5053_50530701_69_dialog_content = "Our enemy is different than before. Don't expect to defeat it so easily.",
  ui_story_5053_50530701_70_dialog_content = "And who might you be...?",
  ui_story_5053_50530701_71_dialog_content = "Just focus your attacks on the dragon, and help me bring it down!",
  ui_story_5053_50530701_72_dialog_content = "Hmph. Even a flying dragon is no match for me.",
  ui_story_5053_50530701_73_dialog_content = "Light of White Night!",
  ui_story_5053_50530701_74_dialog_content = "Roar—!!!",
  ui_story_5053_50530701_75_dialog_content = "What?! I pierced its throat, but it healed almost instantly!!",
  ui_story_5053_50530701_76_dialog_content = "Rapid regeneration... or some type of invulnerability.",
  ui_story_5053_50530701_77_dialog_content = "But how? Who could have bestowed this kind of power on it? Could this be Mime's doing?",
  ui_story_5053_50530701_78_dialog_content = "...",
  ui_story_5053_50530701_79_dialog_content = "On your guard! It's preparing to attack again!",
  ui_story_5053_50530801_1_dialog_content = "Huff... puff...",
  ui_story_5053_50530801_2_dialog_content = "Kill... Kill the intruders... Kill them all!",
  ui_story_5053_50530801_3_dialog_content = "Ahhh! Kill them all!!!",
  ui_story_5053_50530801_4_dialog_content = "Crap! Why are more and more of these crazy guards showing up?! Can you still fight, Mia?",
  ui_story_5053_50530801_5_dialog_content = "These guys are horrifying... Their eyes are completely white, and their faces are all contorted!",
  ui_story_5053_50530801_6_dialog_content = "I'm fine, but the enemy's numbers are only growing!",
  ui_story_5053_50530801_7_dialog_content = "The people who were running away just now have joined their ranks... Even the fallen rebels are on their side!",
  ui_story_5053_50530801_8_dialog_content = "It's like some sort of plague...",
  ui_story_5053_50530801_9_dialog_content = "Keep your distance from them, Mia! Whatever's controlling them seems to spread through their attacks!",
  ui_story_5053_50530801_10_dialog_content = "But we won't last much longer at this rate...!",
  ui_story_5053_50530801_11_dialog_content = "Is this part of her plan too? Lord Schwartz, we need help!",
  ui_story_5053_50530801_12_dialog_content = "Father's too busy fighting off the dragon!",
  ui_story_5053_50530801_13_dialog_content = "(Father... What should I do?)",
  ui_story_5053_50530801_14_dialog_content = "There's no need to hesitate any longer, Mia. Whether it has to do with your mother, or Carleen, or anything else...",
  ui_story_5053_50530801_15_dialog_content = "Do whatever you feel is right, and do it bravely. I will always have faith in you.",
  ui_story_5053_50530801_16_dialog_content = "(Believe in yourself, Mia! Trust in your judgment!)",
  ui_story_5053_50530801_17_dialog_content = "Hippoca—!",
  ui_story_5053_50530801_18_dialog_content = "<color=#e8d9bb>BOOM!!!</color>",
  ui_story_5053_50530801_19_dialog_content = "S-So powerful!",
  ui_story_5053_50530801_20_dialog_content = "Hippoca! Thank you... Thank you for answering my call! I promise I'll never abandon you again!",
  ui_story_5053_50530801_21_dialog_content = "That was incredible, Mia! You took out every single one of those infected guards in one swoop!",
  ui_story_5053_50530801_22_dialog_content = "I'm just glad that it worked! Come on, let's go help my father!",
  ui_story_5053_50530801_23_dialog_content = "Mia... Wait...",
  ui_story_5053_50530801_24_dialog_content = "Gasp, gasp, gasp...",
  ui_story_5053_50530801_25_dialog_content = "V-Veronica...",
  ui_story_5053_50530801_26_dialog_content = "C-Carleen, your head is bleeding!!",
  ui_story_5053_50530801_27_dialog_content = "Did one of those guards manage to hurt you, Carleen? Does that mean she'll...",
  ui_story_5053_50530801_28_dialog_content = "Get away from her, Mia! Her eyes are starting to turn white, just like the others!!",
  ui_story_5053_50530801_29_dialog_content = "Come here, Carleen... Just put down the lance, would you?",
  ui_story_5053_50530801_30_dialog_content = "Please?",
  ui_story_5053_50530801_31_dialog_content = "...",
  ui_story_5053_50530801_32_dialog_content = "Veronica... It hurts...",
  ui_story_5053_50530801_33_dialog_content = "Don't be afraid, Carleen. Put down your weapon and let me dress your wounds, okay?",
  ui_story_5053_50530801_34_dialog_content = "No! My head... it hurts...!",
  ui_story_5053_50530801_35_dialog_content = "There's a strange voice... It keeps telling me to kill you! No, I won't do it!",
  ui_story_5053_50530801_36_dialog_content = "I know you won't, Carleen. I'll protect you, so don't be afraid!",
  ui_story_5053_50530801_37_dialog_content = "Stay back!!",
  ui_story_5053_50530801_38_dialog_content = "I... I am Carleen de Schwartz... Proud daughter of House Schwartz, and defender of Lumopolis...",
  ui_story_5053_50530801_39_dialog_content = "And I'll never hurt anyone in my family! Never!",
  ui_story_5053_50530801_40_dialog_content = "Urgh! I don't want to hurt you, Veronica! That's why...",
  ui_story_5053_50530801_41_dialog_content = "I have to put an end to this, right here and now... I'm sorry, sister... Goodbye.",
  ui_story_5053_50530801_42_dialog_content = "Don't do it, Carleen! Put your weapon down!!",
  ui_story_5053_50530801_43_dialog_content = "Carleen!!!",
  ui_story_5053_50530801_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530801_45_dialog_content = "She pierced her neck with her own lance...",
  ui_story_5053_50530801_46_dialog_content = "Carleen... How could you...",
  ui_story_5053_50530801_47_dialog_content = "...",
  ui_story_5053_50530801_48_dialog_content = "No... No...!",
  ui_story_5053_50530801_49_dialog_content = "Aaaaaahhhh!!!!",
  ui_story_5053_50530801_50_dialog_content = "Carleen!! Nooooooo!!!",
  ui_story_5053_50530801_51_dialog_content = "Snap out of it, Mia! This isn't real, remember? The Carleen in this world is just an illusion!",
  ui_story_5053_50530801_52_dialog_content = "I don't want to lose you, Carleen!!! Please... don't leave me all alone... please, Carleen...",
  ui_story_5053_50530801_53_dialog_content = "Calm down, Mia! Are you listening to me?! Hey!!",
  ui_story_5053_50530801_54_dialog_content = "(Mia's too distressed to hear me... Don't tell me she's going to lose control again?!)",
  ui_story_5053_50530801_55_dialog_content = "Waaaaaaah!!!",
  ui_story_5053_50530801_56_dialog_content = "That's hot!!!",
  ui_story_5053_50530801_57_dialog_content = "Mia's power is about to go berserk!!",
  ui_story_5053_50530801_58_dialog_content = "...",
  ui_story_5053_50530801_59_dialog_content = "Wh-What do you think you're doing...?!",
  ui_story_5053_50530801_60_dialog_content = "Don't cry...",
  ui_story_5053_50530801_61_dialog_content = "Don't cry... My sweet, little... Vonnie...",
  ui_story_5053_50530801_62_dialog_content = "Everything will... be all right...",
  ui_story_5053_50530801_63_dialog_content = "Ah...",
  ui_story_5053_50530801_64_dialog_content = "Pick a bouquet of roses... for my baby... ♪",
  ui_story_5053_50530801_65_dialog_content = "The breeze on your face... your smile is all that I need... ♪",
  ui_story_5053_50530801_66_dialog_content = "Pick a bouquet of roses... for dear father and mother... ♪",
  ui_story_5053_50530801_67_dialog_content = "Though the world may change... Our love will always stay the same... ♪",
  ui_story_5053_50530801_68_dialog_content = "Vonnie... Look... It's Mommy...",
  ui_story_5053_50530801_69_dialog_content = "M-Mother...? Mother!",
  ui_story_5053_50530801_70_dialog_content = "Waaaaaaaaah!!!",
  ui_story_5053_50530801_71_dialog_content = "Mother! It's Carleen... She's...",
  ui_story_5053_50530801_72_dialog_content = "Her hands... her hands were so warm... and there's her blood...",
  ui_story_5053_50530801_73_dialog_content = "Mother... Please...",
  ui_story_5053_50530801_74_dialog_content = "This is... just a bad dream...",
  ui_story_5053_50530801_75_dialog_content = "My little Vonnie... This is all... just a bad dream...",
  ui_story_5053_50530801_76_dialog_content = "You can cry... if you want to...",
  ui_story_5053_50530801_77_dialog_content = "Mommy... is here...",
  ui_story_5053_50530801_78_dialog_content = "...",
  ui_story_5053_50530801_79_dialog_content = "Her warm embrace... and that lullaby just now...",
  ui_story_5053_50530801_80_dialog_content = "It really is you, Mother...",
  ui_story_5053_50530801_81_dialog_content = "I've missed you so much...",
  ui_story_5053_50530801_82_dialog_content = "As have I... my love...",
  ui_story_5053_50530801_83_dialog_content = "(The Dark Angel... She's comforting Mia?!)",
  ui_story_5053_50530801_84_dialog_content = "(But I thought she was just a mindless monster! No, wait... Joshua's the one who said that, and nothing she says can be trusted.)",
  ui_story_5053_50530801_85_dialog_content = "... Are you alright, Mia? Can you still stand?",
  ui_story_5053_50530801_86_dialog_content = "PlayerName... I'm sorry, I couldn't control myself just now.",
  ui_story_5053_50530801_87_dialog_content = "I didn't hurt you, did I...?",
  ui_story_5053_50530801_88_dialog_content = "Of course not! See? I'm perfectly fine, and it looks like you're okay too.",
  ui_story_5053_50530801_89_dialog_content = "So what's the deal with this Dark Angel? I'm completely lost now...",
  ui_story_5053_50530801_90_dialog_content = "She's my mother, no doubt about it.",
  ui_story_5053_50530801_91_dialog_content = "You're saying this is the real Lady Joshua...?!",
  ui_story_5053_50530801_92_dialog_content = "I know it's hard to understand, but my heart tells me that she's my real mother...",
  ui_story_5053_50530801_93_dialog_content = "The other one told us that the Dark Angel has no conscience and only exists to destroy... But her embrace just now told me otherwise.",
  ui_story_5053_50530801_94_dialog_content = "As for the Mother that we met in the mansion, I've always felt something unfamiliar about her...",
  ui_story_5053_50530801_95_dialog_content = "... No, I completely understand. In fact, this would answer a lot of questions.",
  ui_story_5053_50530801_96_dialog_content = "Huh? What do you mean, PlayerName?",
  ui_story_5053_50530801_97_dialog_content = "There's not enough time to explain right now. Jakine's in serious danger, and we need to go save her.",
  ui_story_5053_50530801_98_dialog_content = "I'll tell you more on the way!",
  ui_story_5053_50530801_99_dialog_content = "Jakine? I don't think you have anything to worry about. Uncle Caleb is with her, after all.",
  ui_story_5053_50530801_100_dialog_content = "Caleb is with her?",
  ui_story_5053_50530801_101_dialog_content = "That's right. Father told him to stay behind, but I'm not entirely sure why.",
  ui_story_5053_50530801_102_dialog_content = "Whatever his reasons, it won't make a difference with just Caleb there.",
  ui_story_5053_50530801_103_dialog_content = "The Joshua from the mansion is plotting to kill every single one of us. She can't be trusted.",
  ui_story_5053_50530801_104_dialog_content = "Wh-What are you talking about?!",
  ui_story_5053_50530801_105_dialog_content = "This isn't the first time all of this has happened, Mia!",
  ui_story_5053_50530801_106_dialog_content = "!!!",
  ui_story_5053_50530801_107_dialog_content = "Caleb... Danger...",
  ui_story_5053_50530801_108_dialog_content = "M... My brother... Caleb...",
  ui_story_5053_50530801_109_dialog_content = "Brother... danger...",
  ui_story_5053_50530801_110_dialog_content = "So you're saying another reset happened after the first one?",
  ui_story_5053_50530801_111_dialog_content = "Then we need to find my father and head back right away!!",
  ui_story_5053_50530801_112_dialog_content = "Father!",
  ui_story_5053_50530801_113_dialog_content = "Lord Schwartz, Caleb and Jakine are in grave danger! Hurry, I'll explain everything on the way!",
  ui_story_5053_50530801_114_dialog_content = "Sch... Schwartz...",
  ui_story_5053_50530801_115_dialog_content = "... It appears things are more complicated than I had imagined.",
  ui_story_5053_50530801_116_dialog_content = "Unfortunately, I have no way of leaving this place right now.",
  ui_story_5053_50530801_117_dialog_content = "The dragon immediately heals any wounds inflicted on it, even the most grievous.",
  ui_story_5053_50530801_118_dialog_content = "I can only describe this ominous trait as a type of invulnerability.",
  ui_story_5053_50530801_119_dialog_content = "One that only within the world created by the Crystal of Eternal Memory.",
  ui_story_5053_50530801_120_dialog_content = "But how could this be...?",
  ui_story_5053_50530801_121_dialog_content = "I think the other Joshua must have something to do with it. Lord Schwartz, can you continue fending off the dragon for the time being?",
  ui_story_5053_50530801_122_dialog_content = "Joshua... Very well, then. I'll leave the rest in your hands.",
  ui_story_5053_50530801_123_dialog_content = "Veronica? Why aren't you taking shelter from the dragon?! And who are these people...?",
  ui_story_5053_50530801_124_dialog_content = "...",
  ui_story_5053_50530801_125_dialog_content = "Father... I-I have something urgent to do back at the mansion. Please don't try to stop me.",
  ui_story_5053_50530801_126_dialog_content = "Nothing could be more urgent than our current predicament, Veronica.",
  ui_story_5053_50530801_127_dialog_content = "What's more, I forbid you from involving yourself with these strangers.",
  ui_story_5053_50530801_128_dialog_content = "I hardly consider us strangers, City Lord, given that we have been fighting on the same side for some time now.",
  ui_story_5053_50530801_129_dialog_content = "This is neither the time nor place for paternalistic demands.",
  ui_story_5053_50530801_130_dialog_content = "...",
  ui_story_5053_50530801_131_dialog_content = "Rest assured, as Veronica's allies, PlayerName and I swear to protect her at all costs.",
  ui_story_5053_50530801_132_dialog_content = "You have an obligation to protect the people of Lumopolis, and they need you now more than ever.",
  ui_story_5053_50530801_133_dialog_content = "Enough. My associate, Ms. Rot, is more than capable of defending my family, and my wife is no stranger to combat either. We hardly need outside protection, much less from total strangers.",
  ui_story_5053_50530801_134_dialog_content = "Furthermore, I have no reason to trust a group that counts a monster as one of their own.",
  ui_story_5053_50530801_135_dialog_content = "...",
  ui_story_5053_50530801_136_dialog_content = "This is no monster, of that you can be sure. She's my wife.",
  ui_story_5053_50530801_137_dialog_content = "Wha...?!",
  ui_story_5053_50530801_138_dialog_content = "...!",
  ui_story_5053_50530801_139_dialog_content = "(Father thinks she's the real Mother too!)",
  ui_story_5053_50530801_140_dialog_content = "Ahem... I must say, your tastes are quite unique.",
  ui_story_5053_50530801_141_dialog_content = "Then let us leave it at that.",
  ui_story_5053_50530801_142_dialog_content = "There's no time to lose. Mia, PlayerName, the rest is up to you. Now go!",
  ui_story_5053_50530801_143_dialog_content = "Yes!",
  ui_story_5053_50530801_144_dialog_content = "Caleb...",
  ui_story_5053_50530801_145_dialog_content = "You want to come too, Mother?",
  ui_story_5053_50530801_146_dialog_content = "Protect... Caleb...",
  ui_story_5053_50530801_147_dialog_content = "I understand. We'll do it together, now let's go!",
  ui_story_5053_50530901_1_dialog_content = "How's it look outside, Caleb?",
  ui_story_5053_50530901_2_dialog_content = "I have a really bad feeling about that roar we heard earlier.",
  ui_story_5053_50530901_3_dialog_content = "Agreed. For some reason, the dragon appeared far earlier than expected.",
  ui_story_5053_50530901_4_dialog_content = "The central square should be in complete disarray right now.",
  ui_story_5053_50530901_5_dialog_content = "Then wouldn't that mean everyone is in danger right now?",
  ui_story_5053_50530901_6_dialog_content = "Lord Schwartz, Mia, and PlayerName, who still hasn't shown up anywhere...",
  ui_story_5053_50530901_7_dialog_content = "Not to worry. I'm sure Daniel can handle everything.",
  ui_story_5053_50530901_8_dialog_content = "As for ourselves... Good, you've come just in time.",
  ui_story_5053_50530901_9_dialog_content = "...",
  ui_story_5053_50530901_10_dialog_content = "See? My sister has always been the kind to think ahead and prepare.",
  ui_story_5053_50530901_11_dialog_content = "You and the others are safe, Jakine. I promise.",
  ui_story_5053_50530901_12_dialog_content = "Okay...",
  ui_story_5053_50530901_13_dialog_content = "Now then, would you be a dear and lock the door for us, Jakine?",
  ui_story_5053_50530901_14_dialog_content = "Oh, sure! After all, even a simple lock can do wonders for our safety!",
  ui_story_5053_50530901_15_dialog_content = "Let me ask you a question, Caleb. Why do you want to rescue me?",
  ui_story_5053_50530901_16_dialog_content = "Hmm? Because you're my sister, of course! What brother wouldn't want to help his own sister?",
  ui_story_5053_50530901_17_dialog_content = "So it's because of our kinship... is that it?",
  ui_story_5053_50530901_18_dialog_content = "That's right. The world may change all around us, but the bonds between us... Between you, our father, and myself...",
  ui_story_5053_50530901_19_dialog_content = "Those will never change. No matter how many years pass, I will always feel this way.",
  ui_story_5053_50530901_20_dialog_content = "Is that so? Regardless of your motives, I must thank you for rescuing my body.",
  ui_story_5053_50530901_21_dialog_content = "You've done well, Caleb.",
  ui_story_5053_50530901_22_dialog_content = "Joshua...!",
  ui_story_5053_50530901_23_dialog_content = "It's true that the world is an ever-changing place, but there are some things that even time cannot change...",
  ui_story_5053_50530901_24_dialog_content = "Tell me, what is Lumopolis like after twelve years?",
  ui_story_5053_50530901_25_dialog_content = "Nothing has changed. Those parasitic aristocrats are as stubborn and shameless as ever.",
  ui_story_5053_50530901_26_dialog_content = "After fattening themselves on the glory of Lumopolis, all that remains is a rotting system covered by only the thinnest of veneers.",
  ui_story_5053_50530901_27_dialog_content = "I see... And what of House Schwartz?",
  ui_story_5053_50530901_28_dialog_content = "Schwartz? He's the most repugnant of them all.",
  ui_story_5053_50530901_29_dialog_content = "He made so many promises to you in the past that he could never keep.",
  ui_story_5053_50530901_30_dialog_content = "He even swore he would turn Lumopolis into a beacon of freedom and equality...",
  ui_story_5053_50530901_31_dialog_content = "At this point, he could fight against the corrupt aristocracy to his dying breath, and still nothing would change.",
  ui_story_5053_50530901_32_dialog_content = "His weakness is also the reason your family was left in shambles. You and your daughters should never have suffered like you did, and I despise him all the more for it!",
  ui_story_5053_50530901_33_dialog_content = "I may not know much about politics, but you sound a little extreme, Caleb.",
  ui_story_5053_50530901_34_dialog_content = "I think Lord Schwartz deserves more credit than that. Even with all those noble codgers constantly plotting against him, he still maintains such an honorable appearance in the public eye.",
  ui_story_5053_50530901_35_dialog_content = "What would you know about the inner workings of Lumopolis, Jakine? The only thing you and the rest of the world can see is his so-called \"honorable appearance.\"",
  ui_story_5053_50530901_36_dialog_content = "B-But even Queen Bethlehem thinks... Ugh, never mind! I'm just gonna chat with the guards!",
  ui_story_5053_50530901_37_dialog_content = "What about me, Caleb? Do you see me as a failure in choosing Daniel as my husband?",
  ui_story_5053_50530901_38_dialog_content = "N-Not at all! You were just another victim of Schwartz's grandiose lies!",
  ui_story_5053_50530901_39_dialog_content = "And if... mind you, this is purely hypothetical, but if you were to leave him... Our home will always be open for you.",
  ui_story_5053_50530901_40_dialog_content = "And if you ever grew tired of Lumopolis and its filth, we could always live someplace else!",
  ui_story_5053_50530901_41_dialog_content = "That won't be necessary, Caleb. I have no intention of leaving Lumopolis to rot. I will change this city within my lifetime, if it's the last thing I do.",
  ui_story_5053_50530901_42_dialog_content = "...",
  ui_story_5053_50530901_43_dialog_content = "But you are correct in saying that Schwartz is beyond saving. I have lost all hope in him.",
  ui_story_5053_50530901_44_dialog_content = "Joshua... You're finally willing to divorce him?!",
  ui_story_5053_50530901_45_dialog_content = "Caleb, there are such few people left who are willing to oppose Schwartz.",
  ui_story_5053_50530901_46_dialog_content = "It appears our efforts to raise you were not in vain, after all.",
  ui_story_5053_50530901_47_dialog_content = "Our? Joshua, are you perhaps talking about our father? What does he have to do with this? And why would you say such a thing...?",
  ui_story_5053_50530901_48_dialog_content = "It appears the time has come to tell you the truth, Caleb. Guards, seize her.",
  ui_story_5053_50530901_49_dialog_content = "...",
  ui_story_5053_50530901_50_dialog_content = "Ouch!!! Hey, what are you guys doing?!",
  ui_story_5053_50530901_51_dialog_content = "What do you mean by the truth, Joshua? And what are you doing to Jakine??",
  ui_story_5053_50530901_52_dialog_content = "Caleb... <color=#FFB400>I am not your sister by blood</color>.",
  ui_story_5053_50530901_53_dialog_content = "What...?",
  ui_story_5053_50530901_54_dialog_content = "Many years ago, my family refused to submit to House Schwartz and its despotic rule. As a result, my family was eradicated by Daniel's father, the previous city lord.",
  ui_story_5053_50530901_55_dialog_content = "Many other families shared in our fate as well. Only a few of us survived and I was only a child back then.",
  ui_story_5053_50530901_56_dialog_content = "All of us came to despise House Schwartz, and we vowed to exact vengeance on every single one of them.",
  ui_story_5053_50530901_57_dialog_content = "Eventually, I found my way into the Lumopolis Gardens. A bereaved family of nobles who had lost their daughter to Schwartz's tyranny accepted me as one of their own.",
  ui_story_5053_50530901_58_dialog_content = "Wait... A bereaved family... Who <color=#FFB400>lost their daughter to Schwartz</color>...",
  ui_story_5053_50530901_59_dialog_content = "That's right, it was <color=#FFB400>Joshua</color>, your sister. Your blood sister and mother were killed long ago.",
  ui_story_5053_50530901_60_dialog_content = "They never had any quarrel with House Schwartz. They were simply visiting a friend, a political opponent of Schwartz whose family had been marked for elimination.",
  ui_story_5053_50530901_61_dialog_content = "... And Father, did he know about this...?",
  ui_story_5053_50530901_62_dialog_content = "Of course he did. Your father was the one who asked me to take his daughter's place and seek revenge against House Schwartz.",
  ui_story_5053_50530901_63_dialog_content = "I-Impossible! How could a kind and honest man like my father...",
  ui_story_5053_50530901_64_dialog_content = "Hatred can drive even the most compassionate people to do wicked things, Caleb.",
  ui_story_5053_50530901_65_dialog_content = "It was vengeance, not love, that motivated us to raise you into the man you are today.",
  ui_story_5053_50530901_66_dialog_content = "When your father's assassination attempt ended in failure, he took his own life not just to protect us, but to protect the embers of revenge.",
  ui_story_5053_50530901_67_dialog_content = "When I saw Daniel's sincerity all those years ago, I gave him one last chance to change House Schwartz and Lumopolis for the better.",
  ui_story_5053_50530901_68_dialog_content = "I offered him my unflinching support in his campaign to become the next City Lord.",
  ui_story_5053_50530901_69_dialog_content = "I told myself I was better than his father, that I would never stoop so low as to kill innocent people, just to have my way.",
  ui_story_5053_50530901_70_dialog_content = "But I was wrong. Daniel was too incompetent to change anything, so I realized it was time for House Schwartz to suffer our wrath.",
  ui_story_5053_50530901_71_dialog_content = "Caleb, dispose of <color=#FFB400>Jakine</color>.",
  ui_story_5053_50530901_72_dialog_content = "... What? What are you saying, Joshua?!",
  ui_story_5053_50530901_73_dialog_content = "I need Lumina from outsiders to leave here. I still have a purpose to fulfill out there.",
  ui_story_5053_50530901_74_dialog_content = "No, Joshua... Jakine has nothing to do with any of this! You said it yourself, you're not willing to murder innocent people to have your way!",
  ui_story_5053_50530901_75_dialog_content = "Her death is a necessary sacrifice.",
  ui_story_5053_50530901_76_dialog_content = "What... Are you out of your mind?! What happened to the sweet and gentle Lady Joshua from before?!",
  ui_story_5053_50530901_77_dialog_content = "I would like to ask the very same thing! You raised me not out of love, but for vengeance... I've never heard anything more ludicrous in my life! Jakine, are you sure this person isn't just another illusion?!",
  ui_story_5053_50530901_78_dialog_content = "She's not, trust me! And I didn't cast any spell on her either!",
  ui_story_5053_50530901_79_dialog_content = "How long will you continue to ignore the truth, Caleb? Do you want your family's sacrifices to be in vain?",
  ui_story_5053_50530901_80_dialog_content = "...",
  ui_story_5053_50530901_81_dialog_content = "It doesn't matter, I can dispose of Jakine myself. It appears we failed to educate you thoroughly, Caleb.",
  ui_story_5053_50530901_82_dialog_content = "I will give you one last chance to prove your resolve. When the time comes, you must personally eliminate Schwartz, along with the others.",
  ui_story_5053_50530901_83_dialog_content = "Argh, let go of me! You're nuts if you think you can just kill us all!!!",
  ui_story_5053_50530901_84_dialog_content = "You have no one to blame but Schwartz. Goodbye, envoy of Northland.",
  ui_story_5053_50530901_85_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5053_50530901_86_dialog_content = "... You're right, Joshua. Though much of you has become unfamiliar to me, there can be no denying that you are my dearly-beloved sister.",
  ui_story_5053_50530901_87_dialog_content = "Which is why I must stop you! I won't let you live with the regret of doing something so awful!",
  ui_story_5053_50530901_88_dialog_content = "Regret? I've never once regretted anything. I chose to raise you in your cowardly father's place so that you would inherit our desire for vengeance.",
  ui_story_5053_50530901_89_dialog_content = "Urgh...!",
  ui_story_5053_50530901_90_dialog_content = "Yet you've chosen to betray me... Just like all the others!!!",
  ui_story_5053_50530901_91_dialog_content = "No, Joshua... I would never betray you!",
  ui_story_5053_50530901_92_dialog_content = "Hmph, so you've managed to disarm me... But petty tricks won't save you now!",
  ui_story_5053_50530901_93_dialog_content = "If we're being honest, I also have a confession to make. All these years, I've said that Schwartz was not worthy of you, but the truth is...",
  ui_story_5053_50530901_94_dialog_content = "I resented him! With all my heart, I resented that man and the children you bore him because they took you away from me! They took away the only family I had left in this world!",
  ui_story_5053_50530901_95_dialog_content = "I don't care that we aren't related by blood... You raised me from a child into an adult, and you will always be my beloved sister!",
  ui_story_5053_50530901_96_dialog_content = "It seems you'll never be more than a crying child, desperate for his sister's attention. Now get out of my way!",
  ui_story_5053_50530901_97_dialog_content = "That's right! And I'll never change, no matter how much you ridicule me!",
  ui_story_5053_50530901_98_dialog_content = "But I knew... I knew how much you loved your husband and daughters; nothing I did could ever change that!",
  ui_story_5053_50530901_99_dialog_content = "I told you it was all an act!!",
  ui_story_5053_50530901_100_dialog_content = "I... I'm sorry, Joshua, but I refuse to believe that.",
  ui_story_5053_50530901_101_dialog_content = "And I refuse to let you go through with this. I'll protect your precious family, even at the cost of my own life!",
  ui_story_5053_50530901_102_dialog_content = "Very well, then both your life and your Lumina are now forfeit.",
  ui_story_5053_50530901_103_dialog_content = "Urgh...?!",
  ui_story_5053_50530901_104_dialog_content = "No... Noooo!! Caleb!!!",
  ui_story_5053_50530901_105_dialog_content = "... You made your choice.",
  ui_story_5053_50530901_130_dialog_content = "Caleb!!!",
  ui_story_5053_50530901_131_dialog_content = "<color=#e8d9bb>Smash—!</color>",
  ui_story_5053_50530901_132_dialog_content = "<size=45>Aaaaaaah—!</size>",
  ui_story_5053_50530901_133_dialog_content = "Ugh!",
  ui_story_5053_50530901_134_dialog_content = "Urg—!",
  ui_story_5053_50530901_135_dialog_content = "?!",
  ui_story_5053_50530901_136_dialog_content = "Oh, you disgusting creature, showing up at a time like this...!",
  ui_story_5053_50530901_138_dialog_content = "Caleb! Just hang on, please!!!",
  ui_story_5053_50530901_139_dialog_content = "C... Caleb...!!",
  ui_story_5053_50530901_140_dialog_content = "Heh... Killing me with a single strike... So there's still some mercy in her heart, after all...",
  ui_story_5053_50530901_141_dialog_content = "This is no good. The wound is too deep, he's losing too much blood...",
  ui_story_5053_50530901_143_dialog_content = "It's so dark... I can't see a thing.",
  ui_story_5053_50530901_145_dialog_content = "No... Please...",
  ui_story_5053_50530901_146_dialog_content = "Joshua...? Is that... you...?",
  ui_story_5053_50530901_147_dialog_content = "Caleb... Caleb!",
  ui_story_5053_50530901_148_dialog_content = "I'm... right here...",
  ui_story_5053_50530901_149_dialog_content = "I... I see... Cough, cough!!!",
  ui_story_5053_50530901_150_dialog_content = "Did you... Did you lay down your weapon, Joshua?",
  ui_story_5053_50530901_151_dialog_content = "I'm so glad...",
  ui_story_5053_50530901_152_dialog_content = "...",
  ui_story_5053_50530901_153_dialog_content = "Caleb?! Caleb!!!",
  ui_story_5053_50530901_155_dialog_content = "Please... Caleb!!!",
  ui_story_5053_50530901_156_dialog_content = "No... No...!!",
  ui_story_5053_50530901_157_dialog_content = "<size=50>Hraaaaaaaaaaaaah!!!</size>",
  ui_story_5053_50531001_1_dialog_content = "Huff... Huff...",
  ui_story_5053_50531001_2_dialog_content = "Are you doing alright, PlayerName? We can stop and rest if you need.",
  ui_story_5053_50531001_3_dialog_content = "I'm fine, don't worry. I'm just worried because the Dark Angel took off so quickly just now.",
  ui_story_5053_50531001_4_dialog_content = "She was with us this whole time, but then she suddenly flew off as if she sensed something wrong...",
  ui_story_5053_50531001_5_dialog_content = "She did the exact same thing before, when she sensed that you were in danger. I'm really starting to worry about Jakine and Caleb.",
  ui_story_5053_50531001_6_dialog_content = "We're almost there! Hopefully they're still okay...",
  ui_story_5053_50531001_7_dialog_content = "Mia, are you sure that Jakine doesn't remember anything about the second reset?",
  ui_story_5053_50531001_8_dialog_content = "I'm sure of it. None of us recalled it ever happening... Which is why we believed everything the other Joshua told us.",
  ui_story_5053_50531001_9_dialog_content = "To be honest, I'm still having a hard time believing your own story, PlayerName...",
  ui_story_5053_50531001_10_dialog_content = "That's why... I need to see the truth for myself!",
  ui_story_5053_50531001_11_dialog_content = "(So why do I remember everything, even though Jakine doesn't? It makes no sense...)",
  ui_story_5053_50531001_12_dialog_content = "Something doesn't feel right. Where are all the guards?",
  ui_story_5053_50531001_13_dialog_content = "It feels like the ground is trembling... Mia, look out!!",
  ui_story_5053_50531001_14_dialog_content = "?!",
  ui_story_5053_50531001_15_dialog_content = "Intruders! Traitors! Die—!",
  ui_story_5053_50531001_16_dialog_content = "Ahhh—!!!",
  ui_story_5053_50531001_17_dialog_content = "Die! Die! Die!",
  ui_story_5053_50531001_18_dialog_content = "Not those crazy guards again!",
  ui_story_5053_50531001_19_dialog_content = "Ahhhh!!! Somebody save me!!!",
  ui_story_5053_50531001_20_dialog_content = "Was that... Jakine?!",
  ui_story_5053_50531001_21_dialog_content = "The guards are after her! We need to fight our way through this mob, Mia!",
  ui_story_5053_50531001_22_dialog_content = "There are too many of them! Hippo—",
  ui_story_5053_50531001_23_dialog_content = "Step aside, Princess Veronica—!",
  ui_story_5053_50531001_24_dialog_content = "?!?!",
  ui_story_5053_50531001_25_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5053_50531001_26_dialog_content = "Urgh...!!",
  ui_story_5053_50531001_27_dialog_content = "Aaaaaahhh!!!",
  ui_story_5053_50531001_28_dialog_content = "(Ms. Blanc?! That was incredible! She danced through the entire mob of guards and took them all out!)",
  ui_story_5053_50531001_29_dialog_content = "Ms. Rot! Behind you!",
  ui_story_5053_50531001_30_dialog_content = "Do not worry yourself, Princess Veronica.",
  ui_story_5053_50531001_31_dialog_content = "As a member of the Nightwatch, my duty is to prevent anyone from defiling Lumopolis.",
  ui_story_5053_50531001_32_dialog_content = "None shall disrupt the peace and order of Lumopolis under my watch!",
  ui_story_5053_50531001_33_dialog_content = "White Night up high!",
  ui_story_5053_50531001_34_dialog_content = "Ugh—!!",
  ui_story_5053_50531001_35_dialog_content = "Yarrgh!!",
  ui_story_5053_50531001_36_dialog_content = "Princess Veronica, Miss Jakine, are you hurt?",
  ui_story_5053_50531001_37_dialog_content = "I... I'm fine.",
  ui_story_5053_50531001_38_dialog_content = "You came just in time. I don't think we could have won without you, Ms. Rot.",
  ui_story_5053_50531001_39_dialog_content = "What in the world is happening, your highness? These guards weren't acting like ordinary rebels.",
  ui_story_5053_50531001_40_dialog_content = "That's because they're not rebels! This entire mess is all Joshua's—",
  ui_story_5053_50531001_41_dialog_content = "Silence, traitor! Thank goodness you've come, Ms. Rot.",
  ui_story_5053_50531001_42_dialog_content = "These assailants were in league with PlayerName and Jakine, along with the rest of their treacherous group of outsiders. They've even managed to brainwash Veronica into joining their side!",
  ui_story_5053_50531001_43_dialog_content = "She's too far gone to be saved now. As her mother, I couldn't be more disappointed.",
  ui_story_5053_50531001_44_dialog_content = "I'm afraid I have no choice now. Ms. Rot, I order you to dispose of all three of them.",
  ui_story_5053_50531001_45_dialog_content = "...",
  ui_story_5053_50531001_46_dialog_content = "What are you saying, Mother?! So PlayerName was right all along...",
  ui_story_5053_50531001_47_dialog_content = "Listen to me, Ms. Rot! The \"Joshua\" in front of you is nothing but an impostor! I still don't know exactly what's going on...",
  ui_story_5053_50531001_48_dialog_content = "But please believe me when I tell you that she's not the Joshua you've always known!",
  ui_story_5053_50531001_49_dialog_content = "PlayerName is telling the truth! On my honor as a member of the Schwartz family, I can attest to it!",
  ui_story_5053_50531001_50_dialog_content = "You know my mother better than anyone! How could she order you to do something like this?!",
  ui_story_5053_50531001_51_dialog_content = "...",
  ui_story_5053_50531001_52_dialog_content = "Why are you still hesitating? Have you forgotten everything I've taught you?",
  ui_story_5053_50531001_53_dialog_content = "An assassin must obey their master without question. They must be ready to pay any price to carry out their master's righteous will.",
  ui_story_5053_50531001_54_dialog_content = "You are not letting your emotions override your sense of duty, are you? Remember, emotions are nothing more than obstacles on the path to Lumopolis' prosperous future.",
  ui_story_5053_50531001_55_dialog_content = "(What? I didn't know Ms. Blanc was Joshua's pupil?!)",
  ui_story_5053_50531001_56_dialog_content = "... You're right, Master. Everything I do is for the future of Lumopolis.",
  ui_story_5053_50531001_57_dialog_content = "What...?!",
  ui_story_5053_50531001_58_dialog_content = "In order to create a better world, one in which children can laugh and exist in peaceful harmony... I will eliminate any obstacle in my way, even if that obstacle is you.",
  ui_story_5053_50531001_59_dialog_content = "...",
  ui_story_5053_50531001_60_dialog_content = "How remarkably bold of you to point your blade at me. I suppose I shouldn't be surprised.",
  ui_story_5053_50531001_61_dialog_content = "If this is your choice, then you can die here with the rest of them!",
  ui_story_5053_50531001_62_dialog_content = "<color=#e8d9bb>Clang—!</color>",
  ui_story_5053_50531001_63_dialog_content = "Urgh—!",
  ui_story_5053_50531001_64_dialog_content = "(Her attacks are too fast...!)",
  ui_story_5053_50531001_65_dialog_content = "Ms. Rot?!",
  ui_story_5053_50531001_66_dialog_content = "PlayerName! Take Princess Veronica and Miss Jakine, and run!!!",
  ui_story_5053_50531001_67_dialog_content = "I don't know if I'm strong enough to defeat her, so you three must escape while you can!",
  ui_story_5053_50531001_68_dialog_content = "B-But...",
  ui_story_5053_50531001_69_dialog_content = "Save your breath! Your safety comes before anything else, now go!",
  ui_story_5053_50531001_70_dialog_content = "... I'm sorry! Mia, Jakine, let's get out of here!!",
  ui_story_5053_50531001_71_dialog_content = "(Please be careful, Ms. Rot...!)",
  ui_story_5053_50531002_1_dialog_content = "There! Do we have anything else to block the door?",
  ui_story_5053_50531002_2_dialog_content = "I'm afraid not. That chair was the only one left.",
  ui_story_5053_50531002_3_dialog_content = "Argh! This is all way too weird!!",
  ui_story_5053_50531002_4_dialog_content = "If what PlayerName says is true, then we've already been through a second reset.",
  ui_story_5053_50531002_5_dialog_content = "Everyone held hands for the first time, so we remembered everything. That's how I know I did it right.",
  ui_story_5053_50531002_6_dialog_content = "I was there for the second reset, but I didn't retain any of my memories...",
  ui_story_5053_50531002_7_dialog_content = "Why do you think that happened, Jakine?",
  ui_story_5053_50531002_8_dialog_content = "... I think I have an idea.",
  ui_story_5053_50531002_9_dialog_content = "The Crystal of Eternal Memory must be running out of Lumina!",
  ui_story_5053_50531002_10_dialog_content = "What?!",
  ui_story_5053_50531002_11_dialog_content = "Ugh... It looks like we overdid it with our fight against the enemy.",
  ui_story_5053_50531002_12_dialog_content = "With so little Lumina left, the Crystal of Eternal Memory can't maintain all of its functions.",
  ui_story_5053_50531002_13_dialog_content = "But then, why did you get to keep all of your memories, PlayerName?",
  ui_story_5053_50531002_14_dialog_content = "And now there are two Joshuas... Things just keep getting crazier!",
  ui_story_5053_50531002_15_dialog_content = "Maybe the Joshua from the mansion really is an impostor?",
  ui_story_5053_50531002_16_dialog_content = "I'm just as confused as you are, but my father is still too busy fighting the dragon to help us. I'm worried about him too...",
  ui_story_5053_50531002_17_dialog_content = "We don't have a lot of choices right now. Why don't we try performing another reset?",
  ui_story_5053_50531002_18_dialog_content = "Are you out of your mind?! If none of us manage to keep our memories, you'd have to fight Joshua all by yourself!",
  ui_story_5053_50531002_19_dialog_content = "She's right. You wouldn't stand a chance against her on your own.",
  ui_story_5053_50531002_20_dialog_content = "Blocking the door with all this junk should have bought us some time. Let me see what's in the book...",
  ui_story_5053_50531002_21_dialog_content = "\"Northland's divination arts originated in an ancient Aurorian settlement...\" Ancient Aurorians, hmmm...",
  ui_story_5053_50531002_22_dialog_content = "Wait, that's it! The arts of divination were designed and used by Aurorians, but PlayerName is a Caelestite!",
  ui_story_5053_50531002_23_dialog_content = "Could it affect other races differently? After all, the book doesn't mention any non-Aurorians using the spells.",
  ui_story_5053_50531002_24_dialog_content = "I see... Maybe that also explains why my psychic abilities are so much weaker too?",
  ui_story_5053_50531002_25_dialog_content = "Say, PlayerName? Have you ever played any of the games from Illumina?",
  ui_story_5053_50531002_26_dialog_content = "When you start a game over, the characters lose all their progress, but the player still remembers everything that happened.",
  ui_story_5053_50531002_27_dialog_content = "Are you saying that here, I'm the player?",
  ui_story_5053_50531002_28_dialog_content = "Bingo! Which is why you're not bound by all of the same rules as the rest of us!",
  ui_story_5053_50531002_29_dialog_content = "That's why we need to plan everything out perfectly if we want to reset the time again.",
  ui_story_5053_50531002_30_dialog_content = "I agree. It would be too dangerous for you to go back in time again without being prepared.",
  ui_story_5053_50531002_31_dialog_content = "I guess you're right... Let's plan things out, then.",
  ui_story_5053_50531002_32_dialog_content = "Right now, our biggest threat is Joshua.",
  ui_story_5053_50531002_33_dialog_content = "As for why there are suddenly two of them, I'm still not entirely sure.",
  ui_story_5053_50531002_34_dialog_content = "It's too confusing to refer to them both as Joshua, since one of them is Dark Angel...",
  ui_story_5053_50531002_35_dialog_content = "We can call the other one the White Demon!",
  ui_story_5053_50531002_37_dialog_content = "The White Demon... I don't want to call Mother by that name, but it's a fitting way to describe her as she is right now.",
  ui_story_5053_50531002_38_dialog_content = "Judging from the White Demon's behavior and knowledge, it's safe to assume that she isn't an impostor.",
  ui_story_5053_50531002_39_dialog_content = "When a Seed is planted in a living host, it creates a split personality... Given my own experiences, I can relate to her situation.",
  ui_story_5053_50531002_40_dialog_content = "And just like Baba Yaga and myself, there's no way to determine which of us is good or bad.",
  ui_story_5053_50531002_41_dialog_content = "Her actions may be extreme at times, but that doesn't make Baba Yaga evil. PlayerName knows that too.",
  ui_story_5053_50531002_42_dialog_content = "Is it possible that the Dark Angel and the White Demon are the same?",
  ui_story_5053_50531002_43_dialog_content = "Despite her scary behavior, the Dark Angel did save us back in the central square.",
  ui_story_5053_50531002_44_dialog_content = "Maybe she just has trouble controlling herself?",
  ui_story_5053_50531002_45_dialog_content = "Well, even though she shares some traits with Baba Yaga, I don't think you and the White Demon are anything alike, Mia.",
  ui_story_5053_50531002_46_dialog_content = "She's nothing but a cold-hearted, ruthless murderer. Are you saying Lady Joshua has a side like this?",
  ui_story_5053_50531002_47_dialog_content = "I don't get it either. Mother was always a kind and gentle person... I never saw a hint of wickedness in her.",
  ui_story_5053_50531002_48_dialog_content = "Er, I might be able to add to the story here.",
  ui_story_5053_50531002_49_dialog_content = "She used to be an assassin. I heard it straight from her mouth a while ago...",
  ui_story_5053_50531002_50_dialog_content = "Many years ago, my family refused to submit to House Schwartz and its despotic rule. As a result, my family was eradicated by Daniel's father, the previous City Lord.",
  ui_story_5053_50531002_51_dialog_content = "Many other families shared in our fate as well. Only a few of us survived and I was only a child back then.",
  ui_story_5053_50531002_52_dialog_content = "All of us came to despise House Schwartz, and we vowed to exact vengeance on every single one of them.",
  ui_story_5053_50531002_53_dialog_content = "Eventually, I found my way into the Lumopolis Gardens. A bereaved family of nobles who had lost their daughter to Schwartz's tyranny accepted me as one of their own.",
  ui_story_5053_50531002_54_dialog_content = "What...? B-But how could that be?! S-She's Lord Schwartz's wife!!",
  ui_story_5053_50531002_55_dialog_content = "Don't you think she might have been lying?",
  ui_story_5053_50531002_56_dialog_content = "It's hard for me to imagine, too...",
  ui_story_5053_50531002_57_dialog_content = "...",
  ui_story_5053_50531002_58_dialog_content = "You don't believe that, right Mia?!",
  ui_story_5053_50531002_59_dialog_content = "Actually... It would make a lot of sense if she was telling the truth.",
  ui_story_5053_50531002_60_dialog_content = "Aside from being a kind and compassionate mother, she was also an incredibly powerful person.",
  ui_story_5053_50531002_61_dialog_content = "In spite of her lofty status as the city lord's wife, she never lost sight of her morals. She approached everything with a rational mind and a gentle heart...",
  ui_story_5053_50531002_62_dialog_content = "In our private lives, she took care of us all, including my father. In public, she was the perfect partner to the city lord of Lumopolis.",
  ui_story_5053_50531002_63_dialog_content = "She was never motivated by wealth or power. Even in the most dire situations, she would always sacrifice her own interests for the sake of other people.",
  ui_story_5053_50531002_64_dialog_content = "That isn't something any noblewoman is capable of doing.",
  ui_story_5053_50531002_65_dialog_content = "A cruel and tragic past, followed by a lifetime of sacrificing herself and suppressing her own needs, all while having no one to understand her...",
  ui_story_5053_50531002_66_dialog_content = "My mother's suffering was a million times more painful than my own.",
  ui_story_5053_50531002_67_dialog_content = "I wouldn't blame her if this White Demon was a manifestation of her resentment.",
  ui_story_5053_50531002_68_dialog_content = "I see...",
  ui_story_5053_50531002_69_dialog_content = "Lady Joshua... What an incredible yet tragic existence.",
  ui_story_5053_50531002_70_dialog_content = "But if our theory is true, then why haven't Baba Yaga and I split apart too?",
  ui_story_5053_50531002_71_dialog_content = "You're right, and that's a big difference between you and Lady Joshua.",
  ui_story_5053_50531002_72_dialog_content = "Baba Yaga is your friend, Mia. She's always trying to protect you.",
  ui_story_5053_50531002_73_dialog_content = "It's possible that she doesn't want to break away from you. That would explain why we haven't seen her since entering the Crystal's world.",
  ui_story_5053_50531002_74_dialog_content = "Joshua, on the other hand, is the exact opposite. Her two halves are completely at odds with each other.",
  ui_story_5053_50531002_75_dialog_content = "Y-You think so? I'm relieved to hear that... This whole time, I thought she was just angry because I changed my outfit without consulting her.",
  ui_story_5053_50531002_76_dialog_content = "Baba Yaga... When we get back, I'll have to thank her for being so considerate...",
  ui_story_5053_50531002_77_dialog_content = "Let's get back to what the White Demon said earlier.",
  ui_story_5053_50531002_78_dialog_content = "According to her, the only way to get escape without hurting anyone... Is to bring the two of them with us.",
  ui_story_5053_50531002_79_dialog_content = "You don't think she was lying when she said that, do you...?",
  ui_story_5053_50531002_80_dialog_content = "I don't think so. After all, it matches up with what happened during the last reset.",
  ui_story_5053_50531002_81_dialog_content = "The problem is, we don't know if she still has something up her sleeve or not...",
  ui_story_5053_50531002_82_dialog_content = "...",
  ui_story_5053_50531002_83_dialog_content = "Mia?",
  ui_story_5053_50531002_84_dialog_content = "Sorry, I'm just wondering what Mother will be like once we return to the real world...",
  ui_story_5053_50531002_85_dialog_content = "Will she continue suffering like before? Or worse... Will she turn into an Eclipsite?",
  ui_story_5053_50531002_86_dialog_content = "I... I think we should just try to stay optimistic for now.",
  ui_story_5053_50531002_87_dialog_content = "Whatever happens, we'll all be there to help. Lord Schwartz, Caleb, Jakine... and me too.",
  ui_story_5053_50531002_88_dialog_content = "With our combined strength, we should be able to handle anything that comes our way.",
  ui_story_5053_50531002_89_dialog_content = "But nothing will change unless we get out of here first!",
  ui_story_5053_50531002_90_dialog_content = "... You're absolutely right!",
  ui_story_5053_50531002_91_dialog_content = "Getting them both out at the same time won't be easy though. I doubt the White Demon will come along quietly.",
  ui_story_5053_50531002_92_dialog_content = "She also made it very clear that she hates her other self and refuses to become one with her again...",
  ui_story_5053_50531002_93_dialog_content = "Right, which is why she's planning to kill us all.",
  ui_story_5053_50531002_94_dialog_content = "Our only choice is to subdue her by force and take her with us.",
  ui_story_5053_50531002_95_dialog_content = "But with all those mindless guards and a dragon in the way...",
  ui_story_5053_50531002_96_dialog_content = "Does the book say anything about why they're acting so strange, Jakine?",
  ui_story_5053_50531002_97_dialog_content = "Let me see... There! \"Whoever first activates a Crystal of Eternal Memory has the power to alter the course of events to a certain degree.\"",
  ui_story_5053_50531002_98_dialog_content = "... Wait, is that it? Argh, couldn't you explain a little more, Mom?!",
  ui_story_5053_50531002_99_dialog_content = "Looks like we'll have to find the answer for ourselves. Hmmm...",
  ui_story_5053_50531002_100_dialog_content = "The world within a Crystal of Eternal Memory is created and sustained by <color=#FFB400>Lake Mirror's water</color> and <color=#FFB400>the Lumina of whoever activates it</color>.",
  ui_story_5053_50531002_101_dialog_content = "<color=#FFB400>The activator's Lumina</color>... In other words, Joshua's Lumina! This entire illusory world is a product of her own Lumina.",
  ui_story_5053_50531002_102_dialog_content = "She mentioned that her power had been split apart, right?!",
  ui_story_5053_50531002_103_dialog_content = "Right...",
  ui_story_5053_50531002_104_dialog_content = "She also said that she needed to absorb our Lumina in order to become her own person!",
  ui_story_5053_50531002_105_dialog_content = "That's right! Don't you see?!",
  ui_story_5053_50531002_106_dialog_content = "When the Dark Angel broke away from the White Demon, she took half of her power with her!",
  ui_story_5053_50531002_107_dialog_content = "As for the other half, I don't think she lost it at all! I think she used it to manipulate the Crystal of Eternal Memory!",
  ui_story_5053_50531002_108_dialog_content = "After all, the dragon and the guards are products of Joshua's Lumina.",
  ui_story_5053_50531002_109_dialog_content = "That means she's the only one capable of interfering with them... Or, in this case, infecting them!",
  ui_story_5053_50531002_110_dialog_content = "If that's the case, the White Demon's been lying to us since the very beginning!",
  ui_story_5053_50531002_111_dialog_content = "Is that really possible?! Then Ms. Rot...",
  ui_story_5053_50531002_112_dialog_content = "... Is probably in a lot of danger right now.",
  ui_story_5053_50531002_113_dialog_content = "This is terrifying, she can be so cruel and calculating...",
  ui_story_5053_50531002_114_dialog_content = "I've never been afraid of Mother, but without her warm and gentle side...",
  ui_story_5053_50531002_115_dialog_content = "Is this really the kind of person she would become?",
  ui_story_5053_50531002_116_dialog_content = "So the dragon and the mobs of crazy people are most likely the White Demon's pawns. Defeating them should whittle down her strength.",
  ui_story_5053_50531002_117_dialog_content = "Aside from that, do we have any other way to fight her—wait!",
  ui_story_5053_50531002_118_dialog_content = "The Dark Angel! She didn't seem to see anyone in House Schwartz other than the city lord as her enemy, and the White Demon can't kill her either.",
  ui_story_5053_50531002_119_dialog_content = "If we can convince her to fight on our side, we'll have a much higher chance of winning!",
  ui_story_5053_50531002_120_dialog_content = "That's one harebrained scheme you got there! I always knew you had a reckless side!",
  ui_story_5053_50531002_121_dialog_content = "But I have to warn you, PlayerName...",
  ui_story_5053_50531002_122_dialog_content = "The Crystal of Eternal Memory only has enough Lumina left for one final reset.",
  ui_story_5053_50531002_123_dialog_content = "That means failure isn't an option. You have to succeed, or we're all done for!",
  ui_story_5053_50531002_124_dialog_content = "I-I have to succeed... Got it...",
  ui_story_5053_50531002_125_dialog_content = "PlayerName? After the final reset, what if you go straight to the White Demon and expose her right away?",
  ui_story_5053_50531002_126_dialog_content = "Whoa... That's even wilder than PlayerName's idea! My impression of you has changed a lot since we got here, Mia.",
  ui_story_5053_50531002_127_dialog_content = "R-Really?",
  ui_story_5053_50531002_128_dialog_content = "It would be extremely risky, no doubt.",
  ui_story_5053_50531002_129_dialog_content = "I don't have any way to defend myself. The White Demon would have no problem getting rid of me.",
  ui_story_5053_50531002_130_dialog_content = "None of you will have your memories either, so you may not believe my accusations immediately.",
  ui_story_5053_50531002_131_dialog_content = "You're right... Uncle Caleb would have an especially-difficult time believing your testimony.",
  ui_story_5053_50531002_132_dialog_content = "But to be honest, PlayerName, I don't think you need to worry too much about this.",
  ui_story_5053_50531002_133_dialog_content = "My father is extremely perceptive. He's had his suspicions about the White Demon since we first met her this time.",
  ui_story_5053_50531002_134_dialog_content = "I think he asked Uncle Caleb to stay behind so that he could see the truth with his own eyes...",
  ui_story_5053_50531002_135_dialog_content = "That's why you should focus your attention on the Dark Angel instead.",
  ui_story_5053_50531002_136_dialog_content = "That does sound like Lord Schwartz...",
  ui_story_5053_50531002_137_dialog_content = "<color=#e8d9bb>Wham! Wham! Wham!</color>",
  ui_story_5053_50531002_138_dialog_content = "Wh-What was that?!",
  ui_story_5053_50531002_139_dialog_content = "Oh no, the guards caught up!",
  ui_story_5053_50531002_140_dialog_content = "I'll go hold them off! Jakine, get ready to perform the final reset...",
  ui_story_5053_50531002_141_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5053_50531002_142_dialog_content = "Look out, Mia!",
  ui_story_5053_50531002_143_dialog_content = "Is that...?!",
  ui_story_5053_50531002_144_dialog_content = "...",
  ui_story_5053_50531002_145_dialog_content = "Ms. Rot?!",
  ui_story_5053_50531002_146_dialog_content = "Get back, Mia!",
  ui_story_5053_50531002_147_dialog_content = "... No.",
  ui_story_5053_50531002_148_dialog_content = "You must be in so much pain right now, Ms. Rot... Just like Carleen, when she fought to the very end to keep her sanity.",
  ui_story_5053_50531002_149_dialog_content = "... I won't let it happen again. I won't let you suffer the way Carleen suffered.",
  ui_story_5053_50531002_150_dialog_content = "I'll free you from your pain!",
  ui_story_5053_50531002_151_dialog_content = "Come at me!",
  ui_story_5053_50531002_152_dialog_content = "—!",
  ui_story_5053_50531002_153_dialog_content = "Mia...",
  ui_story_5053_50531002_154_dialog_content = "She's fighting as hard as she can to buy us some time, Jakine... Let's begin the reset.",
  ui_story_5053_50531002_155_dialog_content = "Once I wake up, I just have to find the Dark Angel, then hide from those guards, and then...",
  ui_story_5053_50531002_156_dialog_content = "PlayerName? Your hands are shaking...",
  ui_story_5053_50531002_157_dialog_content = "...",
  ui_story_5053_50531002_158_dialog_content = "I know we're putting a lot on your shoulders right now. I'd be nervous if I had to do it all on my own too, but don't be afraid.",
  ui_story_5053_50531002_159_dialog_content = "Everything's going to be okay. We believe you, no matter what happens!",
  ui_story_5053_50531002_160_dialog_content = "Jakine...!",
  ui_story_5053_50531002_161_dialog_content = "Right! Just leave it to me!",
  ui_story_5053_50531002_162_dialog_content = "Reditus, reditus, reditus! Let everything return to the way it once was!",
  ui_story_5053_50531002_163_dialog_content = "Abracadabra!",
  ui_story_5053_50531101_0X_dialog_content = "<color=#e8d9bb>After the third reset—</color>",
  ui_story_5053_50531101_1_dialog_content = "Everything is set, my lord.",
  ui_story_5053_50531101_2_dialog_content = "The carriage awaits outside and is ready to depart anytime.",
  ui_story_5053_50531101_3_dialog_content = "Understood.",
  ui_story_5053_50531101_4_dialog_content = "Get in the carriage, Carleen.",
  ui_story_5053_50531101_5_dialog_content = "I... I want to stay behind with Mother!",
  ui_story_5053_50531101_6_dialog_content = "Jakine... Mia... I must...",
  ui_story_5053_50531101_7_dialog_content = "Hmmm... Where am I...?",
  ui_story_5053_50531101_8_dialog_content = "That's right, Jakine sent me back in time again!",
  ui_story_5053_50531101_9_dialog_content = "And over there... Lord Schwartz's younger self is escorting Carleen out of here.",
  ui_story_5053_50531101_10_dialog_content = "Looks like the reset was successful!",
  ui_story_5053_50531101_11_dialog_content = "Alright, first things first...",
  ui_story_5053_50531101_12_dialog_content = "Suspicious person... must exterminate...",
  ui_story_5053_50531101_13_dialog_content = "Suspicious person... not here...",
  ui_story_5053_50531101_14_dialog_content = "Phew, I managed to dodge the guards! That takes care of that!",
  ui_story_5053_50531101_15_dialog_content = "(Before the reset, the three of us put together a three-step plan to get us out of here.)",
  ui_story_5053_50531101_16_dialog_content = "(First, find the Dark Angel and convince her to fight on our side.)",
  ui_story_5053_50531101_17_dialog_content = "(And then, prevent the dragon and the infected guards from launching their attack.)",
  ui_story_5053_50531101_18_dialog_content = "(Lastly, take down the White Demon before anyone else gets hurt or worse.)",
  ui_story_5053_50531101_19_dialog_content = "(Mia, Jakine...)",
  ui_story_5053_50531101_20_dialog_content = "(This is our very last reset. I have to pull this off, or we're all doomed.)",
  ui_story_5053_50531101_21_dialog_content = "Suspicious person... exterminate...",
  ui_story_5053_50531101_22_dialog_content = "!!!",
  ui_story_5053_50531101_23_dialog_content = "Not... here...",
  ui_story_5053_50531101_24_dialog_content = "(That was close... Based on my last few run-ins with these guards, they're not going to stop chasing me until the very end.)",
  ui_story_5053_50531101_25_dialog_content = "(I'm short on time, combat strength, and mobility... Which means I'll have to complete all three steps in one go.)",
  ui_story_5053_50531101_26_dialog_content = "(I only have one shot at this!)",
  ui_story_5053_50531102_1_dialog_content = "<color=#e8d9bb>Boom!!!</color>",
  ui_story_5053_50531102_2_dialog_content = "Urgh... Cough, cough...",
  ui_story_5053_50531102_3_dialog_content = "Where did the Dark Angel go?",
  ui_story_5053_50531102_4_dialog_content = "Looks like she escaped through an outside path.",
  ui_story_5053_50531102_5_dialog_content = "That was awesome, Lord Schwartz!",
  ui_story_5053_50531102_6_dialog_content = "I'm just thankful no one was injured—",
  ui_story_5053_50531102_7_dialog_content = "Oh, there you all are!",
  ui_story_5053_50531102_8_dialog_content = "Mother... What are you doing here? Shouldn't you be watching the parade?",
  ui_story_5053_50531102_9_dialog_content = "...",
  ui_story_5053_50531102_10_dialog_content = "... It seems we had an unwelcome guest.",
  ui_story_5053_50531102_11_dialog_content = "Is everyone alright?",
  ui_story_5053_50531102_12_dialog_content = "Joshua? B-But the Dark Angel just now...",
  ui_story_5053_50531102_13_dialog_content = "Heheh, so my little genius has his moments of confusion as well.",
  ui_story_5053_50531102_14_dialog_content = "You must all be tired from your battle. Come inside and rest, won't you?",
  ui_story_5053_50531102_15_dialog_content = "Don't worry about that monster. I'll dispatch my guards to hunt it down momentarily.",
  ui_story_5053_50531102_16_dialog_content = "Mother, just one moment, something doesn't seem right...",
  ui_story_5053_50531102_17_dialog_content = "Has anyone seen PlayerName?",
  ui_story_5053_50531102_18_dialog_content = "Oh yeah! Where is PlayerName? I don't see him anywhere.",
  ui_story_5053_50531102_19_dialog_content = "He has been missing the entire time.",
  ui_story_5053_50531102_20_dialog_content = "What...",
  ui_story_5053_50531102_21_dialog_content = "I'm sorry, Mother. We need to go find PlayerName before he runs into any danger...",
  ui_story_5053_50531102_22_dialog_content = "It warms my heart to see how much you care for your friend, Vonnie... But I have something very important to share with everyone.",
  ui_story_5053_50531102_23_dialog_content = "I'll send a team of guards to search for PlayerName. Let's go inside for now, shall we?",
  ui_story_5053_50531102_24_dialog_content = "Huh? Um... O-Okay...",
  ui_story_5053_50531102_25_dialog_content = "... Is that it?",
  ui_story_5053_50531102_26_dialog_content = "It's not like you at all to talk about a person's life-or-death circumstances so nonchalantly.",
  ui_story_5053_50531102_27_dialog_content = "Oh? Is that what you think of me? An ordinary, weak noble lady? DANIEL.",
  ui_story_5053_50531102_28_dialog_content = "...",
  ui_story_5053_50531102_29_dialog_content = "Daniel? But Joshua, how did you—could it be?!",
  ui_story_5053_50531201_1_dialog_content = "Huff, puff...",
  ui_story_5053_50531201_2_dialog_content = "I-I know I saw her go this way, but why can't I find her?",
  ui_story_5053_50531201_3_dialog_content = "Sch... wartz...",
  ui_story_5053_50531201_4_dialog_content = "There! Behind that crate!",
  ui_story_5053_50531201_5_dialog_content = "...!!!",
  ui_story_5053_50531201_6_dialog_content = "Wait, I don't want to fight you! Caleb and Veronica are in danger, and they need your help!",
  ui_story_5053_50531201_7_dialog_content = "Ca... Caleb...? Veronica...?",
  ui_story_5053_50531201_8_dialog_content = "That's right! Your brother Caleb, and your daughter Veronica!",
  ui_story_5053_50531201_9_dialog_content = "They're your family, aren't they?",
  ui_story_5053_50531201_10_dialog_content = "My... family...",
  ui_story_5053_50531201_11_dialog_content = "Yes, your family! And they're in serious danger right now!",
  ui_story_5053_50531201_12_dialog_content = "My family... in danger...",
  ui_story_5053_50531201_13_dialog_content = "Is something wrong...?",
  ui_story_5053_50531201_14_dialog_content = "<size=50>My... family... Schwartz!!!</size>",
  ui_story_5053_50531201_15_dialog_content = "H-Huh?! Hey, keep it down! You're gonna alert the guards!",
  ui_story_5053_50531201_16_dialog_content = "(When we said Caleb was in danger last time, she was willing to help us. Why is she going angry this time?!)",
  ui_story_5053_50531201_17_dialog_content = "(Is it possible that the Dark Angel will only listen to Mia or someone else from her family?)",
  ui_story_5053_50531201_18_dialog_content = "Pain...! So much pain...!",
  ui_story_5053_50531201_19_dialog_content = "Ah, this is no good... I'm running out of time! What should I do?!",
  ui_story_5053_50531201_20_dialog_content = "Don't cry...",
  ui_story_5053_50531201_21_dialog_content = "Don't cry... My sweet, little... Vonnie...",
  ui_story_5053_50531201_22_dialog_content = "Everything will... be okay...",
  ui_story_5053_50531201_23_dialog_content = "Ah...",
  ui_story_5053_50531201_24_dialog_content = "(I need to calm her down somehow. So, the way Aurorians do to comfort each other... the one thing that means peace and safety for the Dark Angel...)",
  ui_story_5053_50531201_25_dialog_content = "(It's my only chance!)",
  ui_story_5053_50531201_26_dialog_content = "Pick a rose... Just for my baby? ♪",
  ui_story_5053_50531201_27_dialog_content = "Something, something... The breeze on your face is all I need? ♪",
  ui_story_5053_50531201_28_dialog_content = "...?",
  ui_story_5053_50531201_29_dialog_content = "...",
  ui_story_5053_50531201_30_dialog_content = "Pick a rose...? For my dear father and mother... ♪",
  ui_story_5053_50531201_31_dialog_content = "Shut up.",
  ui_story_5053_50531201_32_dialog_content = "I apologize if my singing is terrible.",
  ui_story_5053_50531201_33_dialog_content = "I hear this song on the street from time to time. It's catchy, but I can never remember the words.",
  ui_story_5053_50531201_34_dialog_content = "The melody escapes me most of the time as well.",
  ui_story_5053_50531201_35_dialog_content = "A member of House Schwartz has no right to sing a song of Lower Lumopolis.",
  ui_story_5053_50531201_36_dialog_content = "... Why do you resent House Schwartz so much?",
  ui_story_5053_50531201_37_dialog_content = "The hatred even compelled you to mask and sacrifice yourself to get close to me, becoming my lover.",
  ui_story_5053_50531201_38_dialog_content = "All of this, just so you could assassinate my father.",
  ui_story_5053_50531201_39_dialog_content = "...",
  ui_story_5053_50531201_40_dialog_content = "Your act was flawless, and your expertise in combat and academia is second-to-none.",
  ui_story_5053_50531201_41_dialog_content = "Tell me, how long did it take to hone these abilities?",
  ui_story_5053_50531201_42_dialog_content = "Five years? Ten years? Or perhaps... your entire lifetime?",
  ui_story_5053_50531201_43_dialog_content = "All the training and preparations just to carry out a single, high-profile assassination.",
  ui_story_5053_50531201_44_dialog_content = "Was my father's life truly worthy of the hatred in your heart and in the hearts of your conspirators?",
  ui_story_5053_50531201_45_dialog_content = "Before you come to the wrong conclusion, let me make one thing clear.",
  ui_story_5053_50531201_46_dialog_content = "I say these things, not just in defense of my father's honor... But because I do not wish to see you consumed by hatred.",
  ui_story_5053_50531201_47_dialog_content = "House Schwartz is the embodiment of oppression and tyranny.",
  ui_story_5053_50531201_48_dialog_content = "All the meals you have, and all the clothes you wear are stained with the blood of your victims.",
  ui_story_5053_50531201_49_dialog_content = "Victims, you say. Are they including Caleb's real sister as well as your real family?",
  ui_story_5053_50531201_50_dialog_content = "...",
  ui_story_5053_50531201_51_dialog_content = "This is only speculation on my part, at least for the time being.",
  ui_story_5053_50531201_52_dialog_content = "Seven years ago, Caleb's mother was tragically and accidentally killed during an antirebel operation.",
  ui_story_5053_50531201_53_dialog_content = "His sister, Joshua, was also present during the attack.",
  ui_story_5053_50531201_54_dialog_content = "Yet somehow, as if by some miracle, she emerged as the sole survivor of the operation... But it was no miracle, was it?",
  ui_story_5053_50531201_55_dialog_content = "Only then, an entirely-new \"Joshua\" like yourself could appear. Am I mistaken thus far?",
  ui_story_5053_50531201_56_dialog_content = "...",
  ui_story_5053_50531201_57_dialog_content = "I never shared my suspicions with anyone, nor did I tell anyone about your presence here.",
  ui_story_5053_50531201_58_dialog_content = "Everyone assumed you had simply gone home. I even said as much to your adoptive father.",
  ui_story_5053_50531201_59_dialog_content = "But in fact, you never went back. Your adoptive father never mentioned your disappearance either.",
  ui_story_5053_50531201_60_dialog_content = "Clearly, he knew why you were missing.",
  ui_story_5053_50531201_61_dialog_content = "...",
  ui_story_5053_50531201_62_dialog_content = "However, instead of avoiding the subject, he approached me during class and asked how we were doing lately.",
  ui_story_5053_50531201_63_dialog_content = "Plotting the death of his sovereign is a crime punishable by the most gruesome death, yet at that moment, he was more concerned about your safety than his own.",
  ui_story_5053_50531201_64_dialog_content = "Instead of choosing fear or hatred, that kindly old scholar chose you.",
  ui_story_5053_50531201_65_dialog_content = "So, please... For his sake, please abandon your plan of assassinating my father.",
  ui_story_5053_50531201_66_dialog_content = "If you do, I promise to behave as if nothing happened and return you to your family.",
  ui_story_5053_50531201_67_dialog_content = "Spare me the theatrics, Schwartz. I won't listen, and if he were here right now... He wouldn't listen either.",
  ui_story_5053_50531201_68_dialog_content = "We are bound by our mutual hatred for House Schwartz. To sacrifice ourselves in pursuit of our ambitions is the highest honor.",
  ui_story_5053_50531201_69_dialog_content = "Hmm? Did I not say that I was only making conjectures? I never had any evidence to prove my claims.",
  ui_story_5053_50531201_70_dialog_content = "But now that you have admitted to conspiring against House Schwartz with Caleb's father...",
  ui_story_5053_50531201_71_dialog_content = "Hahaha, it appears this round belongs to me, Joshua!",
  ui_story_5053_50531201_72_dialog_content = "...",
  ui_story_5053_50531201_73_dialog_content = "Ahem, forgive me for that bit of gloating. I only wished to lighten the mood somewhat...",
  ui_story_5053_50531201_74_dialog_content = "In any case, I can comprehend your mistrust.",
  ui_story_5053_50531201_75_dialog_content = "My father has always been a ruthless and determined man. When it came to silencing his enemies... He would do so indiscriminately, rather than let a single person escape.",
  ui_story_5053_50531201_76_dialog_content = "He claimed his actions were necessary for establishing a unified front.",
  ui_story_5053_50531201_77_dialog_content = "All must respect House Schwartz, and all must obey a single ruler.",
  ui_story_5053_50531201_78_dialog_content = "When every citizen is loyal to a single, trustworthy leader, the greedy and the wicked will have nowhere to hide.",
  ui_story_5053_50531201_79_dialog_content = "And once their filth has been purged from the city, Lumopolis will shine above the world as a pure and perfect utopia.",
  ui_story_5053_50531201_80_dialog_content = "Father's vision of the future was as grand as it was ideal. I respect him all the more for it.",
  ui_story_5053_50531201_81_dialog_content = "However... the groundwork for my father's utopia is still being laid, and not everyone shares his vision.",
  ui_story_5053_50531201_82_dialog_content = "Tell me, did you notice the expressions on everyone's faces when you first arrived at my home?",
  ui_story_5053_50531201_83_dialog_content = "Whenever I was present, everyone treated me with nervous adulation.",
  ui_story_5053_50531201_84_dialog_content = "It was only from afar that I could see their true smiles... Their true moments of happiness.",
  ui_story_5053_50531201_85_dialog_content = "So I asked my father why they treated me this way.",
  ui_story_5053_50531201_86_dialog_content = "He said it was because they had all grown accustomed to living in shameful sin.",
  ui_story_5053_50531201_87_dialog_content = "Thus, they could not bear to look upon the members of House Schwartz, who symbolized righteousness and order.",
  ui_story_5053_50531201_88_dialog_content = "It was in their nature, an evil that could never be rooted out... Which is why they needed our guidance.",
  ui_story_5053_50531201_89_dialog_content = "It was the noble duty of House Schwartz to bear the weight of governance and correct their behavior.",
  ui_story_5053_50531201_90_dialog_content = "... But to be frank, living here was unbearably suffocating.",
  ui_story_5053_50531201_91_dialog_content = "For this reason, I would often disguise myself and sneak away from home to enjoy a moment's respite.",
  ui_story_5053_50531201_92_dialog_content = "All this time, I thought you were different, Joshua. You were the only person who would laugh with me, Joshua.",
  ui_story_5053_50531201_93_dialog_content = "But I see now that it was only wishful thinking... And that I still have much to learn.",
  ui_story_5053_50531201_94_dialog_content = "... Fool.",
  ui_story_5053_50531201_95_dialog_content = "Haha... I agree. If only I had never been born a Schwartz.",
  ui_story_5053_50531201_96_dialog_content = "Which is all the more reason I should confront your pain and hatred.",
  ui_story_5053_50531201_97_dialog_content = "A perfect assassination such as this could never be done by just a few people.",
  ui_story_5053_50531201_98_dialog_content = "They can hide your true identity, train you year after year, get help from all the relevant personnel...",
  ui_story_5053_50531201_99_dialog_content = "I can't imagine how many people it takes to accomplish such a feat, much less do so with perfect precision.",
  ui_story_5053_50531201_100_dialog_content = "The pressure exerted by House Schwartz has far from eradicated greed and wickedness. Rather, it has made us the enemy of countless people.",
  ui_story_5053_50531201_101_dialog_content = "This was never my father's intention...",
  ui_story_5053_50531201_102_dialog_content = "Don't try to persuade me with your pitiful speeches, Schwartz. If you've acknowledged your mistakes, you and your father should accept responsibility for them... And pay with your lives.",
  ui_story_5053_50531201_103_dialog_content = "To die for one's mistakes is to avoid taking responsibility for them, Joshua.",
  ui_story_5053_50531201_104_dialog_content = "My father's vision was not entirely wrong. In fact, there were many redeeming qualities to it.",
  ui_story_5053_50531201_105_dialog_content = "This assassination plot is indisputable proof of it.",
  ui_story_5053_50531201_106_dialog_content = "...?",
  ui_story_5053_50531201_107_dialog_content = "In the past, rank and bloodline determined everything in Lumopolis.",
  ui_story_5053_50531201_108_dialog_content = "Bribery and embezzlement were common occurrences among the nobility. With their political sway, they occupied every position of power and used the law to further their own interests.",
  ui_story_5053_50531201_109_dialog_content = "But under the pressure exerted by my father, the people of Lower Lumopolis were also given the right to seek justice.",
  ui_story_5053_50531201_110_dialog_content = "With the threat of justice hanging over their heads, the nobles of Lumopolis began confessing their crimes in exchange for leniency.",
  ui_story_5053_50531201_111_dialog_content = "Through a system of assessments, people began to climb the ranks of our city's hierarchy as well.",
  ui_story_5053_50531201_112_dialog_content = "This was in line with my father's vision: a world where a person's worth is decided by their skills and determination, rather than their birth.",
  ui_story_5053_50531201_113_dialog_content = "Was Caleb's father not a scholar born to a common family?",
  ui_story_5053_50531201_114_dialog_content = "If what I've said is a lie, then someone like him, with neither wealth nor status, could never have entered the Lumopolis Gardens on talent alone.",
  ui_story_5053_50531201_115_dialog_content = "Nor could you have used his status as a professor in order to get closer to me.",
  ui_story_5053_50531201_116_dialog_content = "The person who plotted this assassination recognized this truth, and based their entire plan around it.",
  ui_story_5053_50531201_117_dialog_content = "...",
  ui_story_5053_50531201_118_dialog_content = "So tell me, Joshua. Where did my father's policies go wrong?",
  ui_story_5053_50531201_119_dialog_content = "Is it because Lower Lumopolis is still beset by crime? Or is it because his overly-decisive purges resulted in countless miscarriages of justice?",
  ui_story_5053_50531201_120_dialog_content = "Whatever it is, I swear I will not rest until the truth has been revealed.",
  ui_story_5053_50531201_121_dialog_content = "It may be impossible to make up for the pain you feel right now...",
  ui_story_5053_50531201_122_dialog_content = "But at the very least, we should try to set things straight. For everyone else's sake as well as our own.",
  ui_story_5053_50531201_123_dialog_content = "... You still don't understand.",
  ui_story_5053_50531201_124_dialog_content = "What people need isn't proper governance but true and absolute freedom.",
  ui_story_5053_50531201_125_dialog_content = "Absolute... freedom?",
  ui_story_5053_50531201_126_dialog_content = "Yes. The right to live however they please instead of abiding by a social hierarchy.",
  ui_story_5053_50531201_127_dialog_content = "The right to say what's on their mind without fear of losing their wealth or even their lives.",
  ui_story_5053_50531201_128_dialog_content = "That is freedom.",
  ui_story_5053_50531201_129_dialog_content = "Those servants were so afraid of you because they knew you could take everything away from them whenever you pleased.",
  ui_story_5053_50531201_130_dialog_content = "\"A world where a person's worth is decided by their skills and determination...\" Don't make me laugh!",
  ui_story_5053_50531201_131_dialog_content = "To House Schwartz, we're nothing but livestock whose existence hinges solely upon your approval!",
  ui_story_5053_50531201_132_dialog_content = "...",
  ui_story_5053_50531201_133_dialog_content = "...",
  ui_story_5053_50531201_134_dialog_content = "So by killing my father and eradicating House Schwartz...",
  ui_story_5053_50531201_135_dialog_content = "You wish to create a world of absolute freedom, one that exists without House Schwartz?",
  ui_story_5053_50531201_136_dialog_content = "Will that truly make you happy, Joshua?",
  ui_story_5053_50531201_137_dialog_content = "My happiness is not tied to any of this.",
  ui_story_5053_50531201_138_dialog_content = "Once the assassination is finally carried out, my life will also be at its end.",
  ui_story_5053_50531201_139_dialog_content = "In other words, you have chosen death regardless of the outcome?",
  ui_story_5053_50531201_140_dialog_content = "Is this to protect your allies?",
  ui_story_5053_50531201_141_dialog_content = "No. Once my mission is complete, I simply have no reason to exist any longer.",
  ui_story_5053_50531201_142_dialog_content = "No... Reason...?",
  ui_story_5053_50531201_143_dialog_content = "The nobles are driven by self-interest, but we are driven by our ideals.",
  ui_story_5053_50531201_144_dialog_content = "We live for neither wealth nor status, but to raise a new sun into the sky, one which shines equally upon the world.",
  ui_story_5053_50531201_145_dialog_content = "To strike down the old and oppressive sun, we are more than willing to sacrifice ourselves. Don't think you can judge us with your rotten utilitarian thinking.",
  ui_story_5053_50531201_146_dialog_content = "Heh, While I'm honored that you've shared so much with me, why is everything so cryptic and obscure?",
  ui_story_5053_50531201_147_dialog_content = "So this is your preferred way of speaking...?",
  ui_story_5053_50531201_148_dialog_content = "If my father and his rule represent the \"old sun,\" wouldn't this so-called \"new sun\" simply be another ruler?",
  ui_story_5053_50531201_149_dialog_content = "The person behind the assassination plot... Do they seek to take my father's place as the new ruler?",
  ui_story_5053_50531201_150_dialog_content = "...",
  ui_story_5053_50531201_151_dialog_content = "... Unbelievable.",
  ui_story_5053_50531201_152_dialog_content = "I could understand dying with your enemy to protect your family and allies... But what do you mean by you have no reason to exist?",
  ui_story_5053_50531201_153_dialog_content = "What of your younger brother, who has opposed me day and night ever since I stole you from him?",
  ui_story_5053_50531201_154_dialog_content = "What of your adoptive father, who fears for your safety and simply wishes for you to come home?",
  ui_story_5053_50531201_155_dialog_content = "Are they not reason enough to live on...?",
  ui_story_5053_50531201_156_dialog_content = "If you truly believe that House Schwartz has robbed everyone of their freedom, you need only destroy us to reclaim it!",
  ui_story_5053_50531201_157_dialog_content = "So why must you deprive yourself of that same freedom, even if you succeed?",
  ui_story_5053_50531201_158_dialog_content = "Does this mean that you would end your own life if my father passed away unexpectedly? Are your fates so intertwined?!",
  ui_story_5053_50531201_159_dialog_content = "I've proven it enough times, haven't I? All the bonding and relationship with that man and his fool son is just a disguise.",
  ui_story_5053_50531201_160_dialog_content = "I am a weapon whose sole purpose is to put an end to the rule of House Schwartz.",
  ui_story_5053_50531201_161_dialog_content = "Without my enemy, I have no reason to exist. Freedom belongs to the people, not to me.",
  ui_story_5053_50531201_162_dialog_content = "... How hypocritical.",
  ui_story_5053_50531201_163_dialog_content = "It appears this \"new sun\" never taught you the true meaning of love or freedom.",
  ui_story_5053_50531201_164_dialog_content = "How could you possibly deliver either to the people?",
  ui_story_5053_50531201_165_dialog_content = "...",
  ui_story_5053_50531201_166_dialog_content = "... I understand now.",
  ui_story_5053_50531201_167_dialog_content = "I was never a part of your world. I have no way of truly comprehending how the people have suffered under strict governance.",
  ui_story_5053_50531201_168_dialog_content = "You were never a part of my world either. You have no way of understanding the true meaning of love or freedom.",
  ui_story_5053_50531201_169_dialog_content = "This is a gap we can never hope to bridge.",
  ui_story_5053_50531201_170_dialog_content = "Agreed, so just give up already...",
  ui_story_5053_50531201_171_dialog_content = "Which is why we should work together, and compensate for each other's shortcomings!",
  ui_story_5053_50531201_172_dialog_content = "You're mad.",
  ui_story_5053_50531201_173_dialog_content = "Whether it's us, or my father, or even this \"new sun\" person...",
  ui_story_5053_50531201_174_dialog_content = "No one is capable of seeing things from everyone's point of view. Not alone, at least.",
  ui_story_5053_50531201_175_dialog_content = "But if we set aside our differences and try working together...",
  ui_story_5053_50531201_176_dialog_content = "We can create a new, free world! One where everyone's voice can be heard!",
  ui_story_5053_50531201_177_dialog_content = "This is your goal as well, isn't it?",
  ui_story_5053_50531201_178_dialog_content = "...",
  ui_story_5053_50531201_179_dialog_content = "Ever since I stopped you that day, I've thought about it constantly.",
  ui_story_5053_50531201_180_dialog_content = "Is it wrong of us to entrust our dreams to others?",
  ui_story_5053_50531201_181_dialog_content = "Whether it's realizing my father's vision or killing him to give rise to a \"new sun\"...",
  ui_story_5053_50531201_182_dialog_content = "Perhaps taking our destinies into our own hands is the best way to realize our dreams.",
  ui_story_5053_50531201_183_dialog_content = "As confused and ignorant as I am right now...",
  ui_story_5053_50531201_184_dialog_content = "I believe that by working together, we can accomplish anything we desire.",
  ui_story_5053_50531201_185_dialog_content = "All we need to do is take the first step.",
  ui_story_5053_50531201_186_dialog_content = "You can open my eyes to the world outside of Lumopolis Gardens.",
  ui_story_5053_50531201_187_dialog_content = "Only then will I be able to see the shortcomings of my father's politics.",
  ui_story_5053_50531201_188_dialog_content = "In exchange, I will help you experience life to its fullest, so you can laugh from the bottom of your heart again.",
  ui_story_5053_50531201_189_dialog_content = "When that day comes, you can share that joy with the rest of the world!",
  ui_story_5053_50531201_190_dialog_content = "... How pointless.",
  ui_story_5053_50531201_191_dialog_content = "There are plenty of other women who would be more than happy to play house with you. Why waste your time on me?",
  ui_story_5053_50531201_192_dialog_content = "Well... to be honest...",
  ui_story_5053_50531201_193_dialog_content = "There are so few people that are willing to oppose my father, and the residents of Lumopolis Gardens cannot comprehend the outside world...",
  ui_story_5053_50531201_194_dialog_content = "And, er... Just as I said when we first met—",
  ui_story_5053_50531201_195_dialog_content = "I fell in love with you at first sight!",
  ui_story_5053_50531201_196_dialog_content = "...",
  ui_story_5053_50531201_197_dialog_content = "(The Dark Angel hasn't moved in a long time. Has she finally calmed down...?)",
  ui_story_5053_50531201_198_dialog_content = "Hey! Are you finally willing to hear me out then?",
  ui_story_5053_50531201_199_dialog_content = "Listen, the White Demon... I mean, the other you, want to kill Caleb, Veronica, and everyone else.",
  ui_story_5053_50531201_200_dialog_content = "They really need your...",
  ui_story_5053_50531201_201_dialog_content = "Da... Niel...",
  ui_story_5053_50531201_202_dialog_content = "Huh?",
  ui_story_5053_50531201_203_dialog_content = "Daniel... Why did you... betray me?!",
  ui_story_5053_50531201_204_dialog_content = "<size=45>Daniel!!!</size>",
  ui_story_5053_50531201_205_dialog_content = "What the—?! She's going even more berserk than before! P-Please calm down! I'm not Lord Schwartz!",
  ui_story_5053_50531201_206_dialog_content = "<size=45>Daniel! Daniel!</size>",
  ui_story_5053_50531201_207_dialog_content = "(I'm running out of time, but at least I have her attention! I need to draw her over to the central square!)",
  ui_story_5053_50531201_208_dialog_content = "<size=45>Daniel—</size>",
  ui_story_5053_50531301_1_dialog_content = "My gratitude goes out to all people of Lumopolis gathering here today to celebrate this special occasion.",
  ui_story_5053_50531301_2_dialog_content = "House Schwartz is the crown jewel of the city, as well as its foundation.",
  ui_story_5053_50531301_3_dialog_content = "We raised our arms in defense of Lumopolis, wielding blades that were crafted by its very own people.",
  ui_story_5053_50531301_4_dialog_content = "Today, we praise not only House Schwartz and its moral example, but also the proud and righteous people of Lumopolis!",
  ui_story_5053_50531301_5_dialog_content = "I hereby declare the commencement of the Schwartz Family Day Celebration!",
  ui_story_5053_50531301_6_dialog_content = "The celebration is about to begin, but the Dark Angel has yet to appear near the stand.",
  ui_story_5053_50531301_7_dialog_content = "Eliminate... Intruder...",
  ui_story_5053_50531301_8_dialog_content = "Hmm? What's the matter with these guards?",
  ui_story_5053_50531301_9_dialog_content = "If I remember correctly, the people within the Crystal of Eternal Memory are nothing more than illusions created by Lumina.",
  ui_story_5053_50531301_10_dialog_content = "Why would they suddenly behave so erratically? It's as though they've lost their sentience...",
  ui_story_5053_50531301_11_dialog_content = "I'll be on the stand to keep a lookout. If I see any sign of the Dark Angel, I'll let everyone know.",
  ui_story_5053_50531301_12_dialog_content = "Good. Be on your guard, Mia.",
  ui_story_5053_50531301_13_dialog_content = "(Mia should be safe over there for the time being. PlayerName, on the other hand, where could he be right now?)",
  ui_story_5053_50531301_14_dialog_content = "What?",
  ui_story_5053_50531301_15_dialog_content = "PlayerName...",
  ui_story_5053_50531301_16_dialog_content = "Must find... PlayerName...",
  ui_story_5053_50531301_17_dialog_content = "Halt. You people are clearly not knights of House Kartima.",
  ui_story_5053_50531301_18_dialog_content = "House Kartima is overseeing security for this year's celebration, so why are you roaming about like this?",
  ui_story_5053_50531301_19_dialog_content = "(These guards keep staggering around and muttering to themselves... Could they be drunk?)",
  ui_story_5053_50531301_20_dialog_content = "(And why are they so interested in finding PlayerName?)",
  ui_story_5053_50531301_21_dialog_content = "Must find... PlayerName...",
  ui_story_5053_50531301_22_dialog_content = "Must eliminate... PlayerName...",
  ui_story_5053_50531301_23_dialog_content = "I beg your pardon? What you've just said is a serious breach of your knightly duties.",
  ui_story_5053_50531301_24_dialog_content = "Explain yourselves this instant, all of you.",
  ui_story_5053_50531301_25_dialog_content = "Eliminate... Intruder...!",
  ui_story_5053_50531301_26_dialog_content = "They can't even speak coherently, much less tell me who or what is behind this. What in the world is wrong with these knights?",
  ui_story_5053_50531301_27_dialog_content = "(After the reset, no one in the Crystal of Eternal Memory should recognize PlayerName anymore.)",
  ui_story_5053_50531301_28_dialog_content = "(They shouldn't even be aware of his existence, much less harbor murderous intent toward him.)",
  ui_story_5053_50531301_29_dialog_content = "That won't be necessary. A team of guards can find PlayerName just as quickly, if not more so.",
  ui_story_5053_50531301_30_dialog_content = "Besides, we need everyone's strength if we hope to stand a chance against that monster.",
  ui_story_5053_50531301_31_dialog_content = "I think you know as well as I do which of these matters is more important. Use your common sense, Daniel.",
  ui_story_5053_50531301_32_dialog_content = "(... Joshua is the only one outside of our group who knows about PlayerName.)",
  ui_story_5053_50531301_33_dialog_content = "(She is also the only other living person within the Crystal of Eternal Memory aside from us.)",
  ui_story_5053_50531301_34_dialog_content = "(But why would she want to hunt down a mere child, one who has nothing to do with her?)",
  ui_story_5053_50531301_35_dialog_content = "(Telling Caleb to remain at her side was the right choice after all.)",
  ui_story_5053_50531301_36_dialog_content = "(I only pray that he won't let the joy of reuniting with his sister cloud his judgment and uncovers the truth in my stead.)",
  ui_story_5053_50531301_37_dialog_content = "Huff... huff... L-Lord Schwartz! Oh, thank goodness I found you!",
  ui_story_5053_50531301_38_dialog_content = "PlayerName...?",
  ui_story_5053_50531301_39_dialog_content = "Aaaaaaah—!",
  ui_story_5053_50531301_40_dialog_content = "PlayerName, get down!",
  ui_story_5053_50531301_41_dialog_content = "Forget about the Dark Angel! Mia's in danger! We need to get to the stand!",
  ui_story_5053_50531301_42_dialog_content = "What do you mean?",
  ui_story_5053_50531301_43_dialog_content = "Just trust me! Now let's go!!",
  ui_story_5053_50531301_44_dialog_content = "Very well...",
  ui_story_5053_50531301_45_dialog_content = "Bwaaah! Wh-What is this?!",
  ui_story_5053_50531301_46_dialog_content = "Hold still. I'm taking you to the stand.",
  ui_story_5053_50531301_47_dialog_content = "?!",
  ui_story_5053_50531301_48_dialog_content = "D... Daniel...? Daniel!!!",
  ui_story_5053_50531301_49_dialog_content = "Hey! Quit shoving!",
  ui_story_5053_50531301_50_dialog_content = "Wh-What's going on?",
  ui_story_5053_50531301_51_dialog_content = "Monster! It's a monster!!",
  ui_story_5053_50531301_52_dialog_content = "The crowd is in an uproar. What's happening down there?",
  ui_story_5053_50531301_53_dialog_content = "<size=30> That's... Father and PlayerName! Wait, is that... the Dark Angel?!</size>",
  ui_story_5053_50531301_54_dialog_content = "What is it, Veronica?",
  ui_story_5053_50531301_55_dialog_content = "N-Nothing, Father...",
  ui_story_5053_50531301_56_dialog_content = "They're forcing their way through the crowd and towards the stand!",
  ui_story_5053_50531301_57_dialog_content = "Stop them, guards!!",
  ui_story_5053_50531301_58_dialog_content = "(The Dark Angel really is hunting Father down... Just like Mother said.)",
  ui_story_5053_50531301_59_dialog_content = "(I don't know why they're running this way, but I have to protect him.)",
  ui_story_5053_50531301_60_dialog_content = "(Oh, Hippoca, please answer me, I need you more than ever!)",
  ui_story_5053_50531301_61_dialog_content = "Veronica, what's happening? Who are those strangers fighting through the crowd?",
  ui_story_5053_50531301_62_dialog_content = "I-I don't know Carleen, but stay close to us.",
  ui_story_5053_50531301_63_dialog_content = "That man in the front is something else.",
  ui_story_5053_50531301_64_dialog_content = "He's dodging our guards so effortlessly, all while carrying someone in his arms.",
  ui_story_5053_50531301_65_dialog_content = "In fact, he almost looks like...",
  ui_story_5053_50531301_66_dialog_content = "H-He knocked over one of the guards and used him to leap out of the crowd! He's coming right towards us!",
  ui_story_5053_50531301_67_dialog_content = "Men, protect the others! I'll handle them myself.",
  ui_story_5053_50531301_68_dialog_content = "...",
  ui_story_5053_50531301_69_dialog_content = "Who are you, and what is your business here?",
  ui_story_5053_50531301_70_dialog_content = "Where is the danger that you mentioned, PlayerName?",
  ui_story_5053_50531301_71_dialog_content = "I asked you a question, sir!",
  ui_story_5053_50531301_72_dialog_content = "Above us! It'll be here any second!",
  ui_story_5053_50531301_73_dialog_content = "Where did this foul creature come from?! Guards! Protect me! Guards!!!",
  ui_story_5053_50531301_74_dialog_content = "D... Daniel? Daniel... Daniel...",
  ui_story_5053_50531301_75_dialog_content = "Aaaaaah—Daniel—!!!",
  ui_story_5053_50531301_76_dialog_content = "Stay away from my father!",
  ui_story_5053_50531301_77_dialog_content = "... It's here! The dragon's here now!!",
  ui_story_5053_50531301_78_dialog_content = "<size=50>Roar—!!!</size>",
  ui_story_5053_50531301_79_dialog_content = "A flying dragon?",
  ui_story_5053_50531301_80_dialog_content = "A covenant engraved in House Kartima's bloodline... But isn't it far too early still?",
  ui_story_5053_50531301_81_dialog_content = "I would advise you to focus on the danger at hand, young man.",
  ui_story_5053_50531301_82_dialog_content = "Kartima traitors... You will never be in control here!",
  ui_story_5053_50531301_83_dialog_content = "Concentrate on your real enemy! It's coming for us!",
  ui_story_5053_50531301_84_dialog_content = "...",
  ui_story_5053_50531301_85_dialog_content = "Th-The dragon! But it's not supposed to be here yet!",
  ui_story_5053_50531301_86_dialog_content = "Don't worry, Veronica! I'll protect you!",
  ui_story_5053_50531301_87_dialog_content = "No... The rebels put their plan into action sooner than we thought! Take cover, Carleen!",
  ui_story_5053_50531301_88_dialog_content = "Carleen...? Veronica...?",
  ui_story_5053_50531301_89_dialog_content = "Roooooaaaaar!!!!!!",
  ui_story_5053_50531301_90_dialog_content = "The dragon's about to attack!",
  ui_story_5053_50531301_91_dialog_content = "—!!!",
  ui_story_5053_50531301_92_dialog_content = "Where did that dragon come from?!",
  ui_story_5053_50531301_93_dialog_content = "Waaaaah! Daddy, where are you?!",
  ui_story_5053_50531301_94_dialog_content = "It's breathing fire! Run!!!",
  ui_story_5053_50531301_95_dialog_content = "Son! Where are you, my boy?!",
  ui_story_5053_50531301_96_dialog_content = "...",
  ui_story_5053_50531301_97_dialog_content = "Please, sir! Have you seen my little boy? He's about this tall, and...",
  ui_story_5053_50531301_98_dialog_content = "Eliminate... them all...",
  ui_story_5053_50531301_99_dialog_content = "Huh? What did you say?",
  ui_story_5053_50531301_100_dialog_content = "More allies... eliminate them all...",
  ui_story_5053_50531301_101_dialog_content = "Urk?! Wh-What are you...",
  ui_story_5053_50531301_102_dialog_content = "More allies... eliminate them all...",
  ui_story_5053_50531301_103_dialog_content = "*Coughing* Veronica? Father? Where are you?",
  ui_story_5053_50531301_104_dialog_content = "Carleen! Are you alright?",
  ui_story_5053_50531301_105_dialog_content = "I'm fine. It's just that my throat hurts from all the dust.",
  ui_story_5053_50531301_106_dialog_content = "Oh, thank goodness...",
  ui_story_5053_50531301_107_dialog_content = "Veronica... Carleen...",
  ui_story_5053_50531301_108_dialog_content = "It worked! All four of them were able to beat back the dragon!!",
  ui_story_5053_50531301_109_dialog_content = "(It looks like only family members can calm the Dark Angel down. It was a huge gamble, but I'm glad it paid off!)",
  ui_story_5053_50531301_110_dialog_content = "It's still too early to celebrate.",
  ui_story_5053_50531301_111_dialog_content = "The dragon merely retreated to gather its strength for another fiery attack.",
  ui_story_5053_50531301_112_dialog_content = "It will bear down upon us soon enough.",
  ui_story_5053_50531301_113_dialog_content = "That simply means we need to defeat it before it launches its next attack.",
  ui_story_5053_50531301_114_dialog_content = "Then you better do well to target its weak point.",
  ui_story_5053_50531301_115_dialog_content = "More specifically, you need to attack its—",
  ui_story_5053_50531301_116_dialog_content = "I know where to strike the beast.",
  ui_story_5053_50531301_117_dialog_content = "It won't do us any good! The dragon has some kind of invulnerability, which lets it instantly heal any wounds.",
  ui_story_5053_50531301_118_dialog_content = "What?",
  ui_story_5053_50531301_119_dialog_content = "Lord Schwartz! The uprising has begun!",
  ui_story_5053_50531301_120_dialog_content = "Then continue with the plan. Gather more men and suppress the rebels.",
  ui_story_5053_50531301_121_dialog_content = "Leave the dragon to me, and have the remaining soldiers evacuate the people from this area.",
  ui_story_5053_50531301_122_dialog_content = "But my lord... The rebels aren't the only ones rioting! Most people in the area, including some of our own soldiers, have also begun attacking!",
  ui_story_5053_50531301_123_dialog_content = "What...?!",
  ui_story_5053_50531301_124_dialog_content = "They seem to have lost control of their bodies and minds, my lord. They're lashing out at any living creature they can reach, whether they are friends or foes!",
  ui_story_5053_50531301_125_dialog_content = "But the most disturbing thing is that their madness seems to spread to whomever they manage to injure! It's as though...",
  ui_story_5053_50531301_126_dialog_content = "As though they're being infected and turned into walking dead, right?",
  ui_story_5053_50531301_127_dialog_content = "P-Precisely.",
  ui_story_5053_50531301_128_dialog_content = "You seem to be quite aware of our current situation.",
  ui_story_5053_50531301_129_dialog_content = "Time is not on our side, so tell us what you know.",
  ui_story_5053_50531301_130_dialog_content = "I...",
  ui_story_5053_50531301_131_dialog_content = "(Young Schwartz is glaring at me too...)",
  ui_story_5053_50531301_132_dialog_content = "(If I don't give him a good enough explanation, he's not going to let me go so easily.)",
  ui_story_5053_50531301_133_dialog_content = "(But if I tell him the truth right now, it'll only make him doubt me! I need to come up with the perfect excuse...)",
  ui_story_5053_50531301_134_dialog_content = "Are you that reluctant to divulge the truth before me?",
  ui_story_5053_50531301_135_dialog_content = "Or could it be that the culprit stands among you outsiders—",
  ui_story_5053_50531301_136_dialog_content = "Like perhaps that winged monster there?",
  ui_story_5053_50531301_137_dialog_content = "Please don't call her that! She's not a monster, she's...",
  ui_story_5053_50531301_138_dialog_content = "Up there, the dragon is preparing to descend for another attack.",
  ui_story_5053_50531301_139_dialog_content = "While an army of the living dead surrounds us from below.",
  ui_story_5053_50531301_140_dialog_content = "I'm certain you know what takes precedence at a time like this, yes?",
  ui_story_5053_50531301_141_dialog_content = "... Of course I know.",
  ui_story_5053_50531301_142_dialog_content = "Guard, contact Lachon and Otto, and tell them that the soldiers in the square are under their command now.",
  ui_story_5053_50531301_143_dialog_content = "Tell them to fortify the stand's defenses and to bring any uninfected survivors here. I'll hold off the dragon.",
  ui_story_5053_50531301_144_dialog_content = "Yes, my lord!",
  ui_story_5053_50531301_145_dialog_content = "(Lucky that Lord Schwartz was able to get his younger self off my back. He must have realized that I have my reasons for not telling him the truth.)",
  ui_story_5053_50531301_146_dialog_content = "(I can't waste another second of our time, not after we've come so far. It's time for us to head back to Schwartz Mansion!)",
  ui_story_5053_50531301_147_dialog_content = "Veronica... Why is it calling my name?",
  ui_story_5053_50531301_148_dialog_content = "Just keep your distance from her, Carleen.",
  ui_story_5053_50531301_149_dialog_content = "Veronica... Carleen... Are you... hurt...?",
  ui_story_5053_50531301_150_dialog_content = "Are you... hurt...?",
  ui_story_5053_50531301_151_dialog_content = "I will hold you... and sing...",
  ui_story_5053_50531301_152_dialog_content = "Huh? I-I'm fine, and so is Carleen.",
  ui_story_5053_50531301_153_dialog_content = "So you can communicate with us after all... You're a part of Mother, aren't you?",
  ui_story_5053_50531301_154_dialog_content = "Mother... I am.. Mother...",
  ui_story_5053_50531301_155_dialog_content = "Then could you please stop attacking us? Can you please stop trying to hurt Father?",
  ui_story_5053_50531301_156_dialog_content = "Veronica... Father? Daniel... Daniel...!!!",
  ui_story_5053_50531301_157_dialog_content = "Y-You never wanted us to see you two fighting!",
  ui_story_5053_50531301_158_dialog_content = "Isn't that right?",
  ui_story_5053_50531301_159_dialog_content = "...",
  ui_story_5053_50531301_160_dialog_content = "No more... No more fighting... It scares the girls...",
  ui_story_5053_50531301_161_dialog_content = "No more fighting... Veronica... don't be afraid...",
  ui_story_5053_50531301_162_dialog_content = "I know, Mother. Thank you.",
  ui_story_5053_50531301_163_dialog_content = "(Mother said the Dark Angel was born from a Seed, and that she was nothing more than a mindless beast.)",
  ui_story_5053_50531301_164_dialog_content = "(But not only can I communicate with her... I can even sense a certain kindness coming from her.)",
  ui_story_5053_50531301_165_dialog_content = "(A kindness I haven't felt from the mother back at the mansion. What in the world is happening...?)",
  ui_story_5053_50531301_166_dialog_content = "<size=30>Hey! Over here, Veronica!</size>",
  ui_story_5053_50531301_167_dialog_content = "PlayerName! Father! Are you two alright?",
  ui_story_5053_50531301_168_dialog_content = "Shhh! Keep it down!",
  ui_story_5053_50531301_169_dialog_content = "While the young Schwartz is busy fighting the dragon, the three of us and the Dark Angel need to leave.",
  ui_story_5053_50531301_170_dialog_content = "Leave? But where to? And why does the Dark Angel have to come with us?",
  ui_story_5053_50531301_171_dialog_content = "To Schwartz Mansion. Caleb and Jakine are in serious danger.",
  ui_story_5053_50531301_172_dialog_content = "Huh? I-I'm sorry, this is all just so confusing. What exactly is...",
  ui_story_5053_50531301_173_dialog_content = "PlayerName has promised to explain everything on the way. We must go while we still have the chance.",
  ui_story_5053_50531301_174_dialog_content = "Y-Yes, then.",
  ui_story_5053_50531301_175_dialog_content = "Daniel...",
  ui_story_5053_50531301_176_dialog_content = "And you're certain she will not attack me again, PlayerName?",
  ui_story_5053_50531301_177_dialog_content = "Uh, I'm pretty sure you're safe for now...",
  ui_story_5053_50531301_178_dialog_content = "She won't, Father. Mother already promised me that she wouldn't, right?",
  ui_story_5053_50531301_179_dialog_content = "I... Promise...",
  ui_story_5053_50531301_180_dialog_content = "... Fine.",
  ui_story_5053_50531301_181_dialog_content = "The back of the stand should be free of any onlookers. We should leave before they finish strengthening their defenses.",
  ui_story_5053_50531301_182_dialog_content = "Where are you going, Veronica?",
  ui_story_5053_50531301_183_dialog_content = "Father told us to stay here and wait for Ms. Rot to escort us to safety.",
  ui_story_5053_50531301_184_dialog_content = "I'm sorry, Carleen, but I can't stay. There's something very important that I need to do.",
  ui_story_5053_50531301_185_dialog_content = "But a brave girl like you should have no problem waiting for Ms. Rot all by yourself, right?",
  ui_story_5053_50531301_186_dialog_content = "I'll be fine, but I'm more worried about you, Veronica.",
  ui_story_5053_50531301_187_dialog_content = "When you go off on your own, it's usually to cry by yourself...",
  ui_story_5053_50531301_188_dialog_content = "But you don't need to cry anymore, Veronica! I promise I'll get stronger one day and protect you, no matter what!",
  ui_story_5053_50531301_189_dialog_content = "Heehee... What a brave and mature person you've become, Carleen.",
  ui_story_5053_50531301_190_dialog_content = "You don't need to worry either. I'm not as weak and helpless as I used to be.",
  ui_story_5053_50531301_191_dialog_content = "Your big sister will be perfectly fine, I promise.",
  ui_story_5053_50531301_192_dialog_content = "I know I was always a half-step behind you in the past and made things difficult for everyone.",
  ui_story_5053_50531301_193_dialog_content = "But from now on, I will work hard and become a dependable big sister who can help you bear your burden.",
  ui_story_5053_50531301_194_dialog_content = "Veronica...?",
  ui_story_5053_50531301_195_dialog_content = "So please, just trust me.",
  ui_story_5053_50531301_196_dialog_content = "Yes. I trust you.",
  ui_story_5053_50531301_197_dialog_content = "Heehee, thank you.",
  ui_story_5053_50531301_198_dialog_content = "Until next time... My sweet, little Carleen.",
  ui_story_5053_50531302_1_dialog_content = "... This is the current situation in the central square.",
  ui_story_5053_50531302_2_dialog_content = "Every passage leading to the square has been completely sealed off.",
  ui_story_5053_50531302_3_dialog_content = "Under Lord Schwartz's command, the riot is starting to fall under control. You can put your mind at ease, your highness.",
  ui_story_5053_50531302_4_dialog_content = "... Understood. You may leave now.",
  ui_story_5053_50531302_5_dialog_content = "As you wish.",
  ui_story_5053_50531302_6_dialog_content = "Now then, would you be a dear and lock the door for us, Jakine?",
  ui_story_5053_50531302_7_dialog_content = "Oh, sure! After all, even a simple lock can do wonders for our safety!",
  ui_story_5053_50531302_8_dialog_content = "Let me ask you a question, Caleb. Why do you want to rescue me?",
  ui_story_5053_50531302_9_dialog_content = "Huh?",
  ui_story_5053_50531302_10_dialog_content = "Hmm? Because you're my sister, of course! What brother wouldn't want to help his own sister?",
  ui_story_5053_50531302_11_dialog_content = "<color=#e8d9bb>Thud, thud, thud!</color>",
  ui_story_5053_50531302_12_dialog_content = "Lady Joshua, I've come to escort you to safety. May I come in?",
  ui_story_5053_50531302_13_dialog_content = "Sure, just get in here!",
  ui_story_5053_50531302_14_dialog_content = "Jakine, have you forgotten that you are a guest here? My sister wasn't finished speaking!",
  ui_story_5053_50531302_15_dialog_content = "...",
  ui_story_5053_50531302_16_dialog_content = "Forgive the interruption...",
  ui_story_5053_50531302_17_dialog_content = "What is it, Ms. Rot?",
  ui_story_5053_50531302_18_dialog_content = "I was told you were not feeling well today. As such, Lord Schwartz ordered me to stay by your side and ensure your safety.",
  ui_story_5053_50531302_19_dialog_content = "Given the severity of the situation, I must ask you to follow me to another secure location.",
  ui_story_5053_50531302_20_dialog_content = "Once you have taken shelter, I will escort Princess Carleen to safety as well. Rest assured, I will not let her come to any harm.",
  ui_story_5053_50531302_21_dialog_content = "I see. How very kind of you.",
  ui_story_5053_50531302_22_dialog_content = "However, my guests and I are perfectly safe here. If anything, you should be more concerned with Carleen's safety right now.",
  ui_story_5053_50531302_23_dialog_content = "I'm afraid I can't do that.",
  ui_story_5053_50531302_24_dialog_content = "If I were to leave right now... You would have no problem murdering your two guests in my absence.",
  ui_story_5053_50531302_25_dialog_content = "M-Murder?!",
  ui_story_5053_50531302_26_dialog_content = "What is the meaning of this, Ms. Rot?! My sister would never...",
  ui_story_5053_50531302_27_dialog_content = "... Joshua?",
  ui_story_5053_50531302_28_dialog_content = "Yes, Caleb. I would never do anything so violently atrocious.",
  ui_story_5053_50531302_29_dialog_content = "Why on earth would you accuse me of that, Ms. Rot?",
  ui_story_5053_50531302_30_dialog_content = "You can dispense with the act.",
  ui_story_5053_50531302_31_dialog_content = "The dagger is hidden on your leg, is it not? Quite the classic method of assassination.",
  ui_story_5053_50531302_32_dialog_content = "Your ability to conceal weapons is peerless, but your hand hovering over the hilt makes your intentions all too obvious.",
  ui_story_5053_50531302_33_dialog_content = "...",
  ui_story_5053_50531302_34_dialog_content = "You are a highly-trained assassin, and there can be no doubt.",
  ui_story_5053_50531302_35_dialog_content = "You are so much like my master, but you're nothing more than an extremely compelling impostor.",
  ui_story_5053_50531302_36_dialog_content = "An impostor? B-But her voice and appearance... I could never mistake them!",
  ui_story_5053_50531302_37_dialog_content = "He's right, and the Crystal of Eternal Memory clearly shows that she's a living, breathing person too!",
  ui_story_5053_50531302_38_dialog_content = "What are the odds that someone else is in here impersonating Lady Joshua?!",
  ui_story_5053_50531302_39_dialog_content = "I don't know how you two are connected to this assassin, but for your safety, I suggest you keep your distance from her.",
  ui_story_5053_50531302_40_dialog_content = "If I had to guess, you must be another remnant of that organization, one who they also trained in the killing arts.",
  ui_story_5053_50531302_41_dialog_content = "After all, the resemblance between you and my former master is uncanny.",
  ui_story_5053_50531302_42_dialog_content = "It is precisely for this reason that you could never replace her. The Lady Joshua of today is a loving wife, a nurturing mother, and a caring sister.",
  ui_story_5053_50531302_43_dialog_content = "Am I correct in saying so?",
  ui_story_5053_50531302_44_dialog_content = "...",
  ui_story_5053_50531302_45_dialog_content = "L-Lady Joshua has a dagger in her hands! How the heck did she pull that out of nowhere...?",
  ui_story_5053_50531302_46_dialog_content = "Argh, that does it! Where's my crystal ball?!",
  ui_story_5053_50531302_47_dialog_content = "There's no mistaking it, Jakine... She truly is my sister. But how... How could this be?!",
  ui_story_5053_50531302_48_dialog_content = "Quit standing around, Caleb! If you're not going to fight, then take cover!",
  ui_story_5053_50531302_49_dialog_content = "<size=45>Aaaaaaah—!</size>",
  ui_story_5053_50531302_50_dialog_content = "I-It's you—!!",
  ui_story_5053_50531302_51_dialog_content = "It's the Dark Angel!",
  ui_story_5053_50531302_52_dialog_content = "The Dark Angel...?",
  ui_story_5053_50531302_53_dialog_content = "Away... from Caleb...",
  ui_story_5053_50531302_54_dialog_content = "<size=45>Leave... Caleb... Alone!!!</size>",
  ui_story_5053_50531302_55_dialog_content = "What are you doing here?!",
  ui_story_5053_50531302_56_dialog_content = "Get away from me, you disgusting thing!",
  ui_story_5053_50531302_57_dialog_content = "There's no escape!",
  ui_story_5053_50531302_58_dialog_content = "First Lady Joshua wants to kill us, and now the Dark Angel chased her away...",
  ui_story_5053_50531302_59_dialog_content = "Wh-What the heck is even happening anymore?! Someone needs to explain this mess right now!",
  ui_story_5053_50531302_60_dialog_content = "W-Whoa, Hippoca! Stop...!!",
  ui_story_5053_50531302_61_dialog_content = "Bwaaa! And now a giant spider-horse just flew through the window!!!",
  ui_story_5053_50531302_62_dialog_content = "Wait... PlayerName?! With Mia and Lord Schwartz!",
  ui_story_5053_50531302_63_dialog_content = "Well done, Mia. You appear to have quite the gift when it comes to using your Lumina summon as a mount.",
  ui_story_5053_50531302_64_dialog_content = "*Gasping* To be honest... That was my first time using Hippoca like that...",
  ui_story_5053_50531302_65_dialog_content = "Ugh... We jumped over so many buildings on Hippoca's back... I think I'm gonna be sick...",
  ui_story_5053_50531302_66_dialog_content = "What are you three...",
  ui_story_5053_50531302_67_dialog_content = "Oh good, it looks like Caleb and Jakine are still okay...",
  ui_story_5053_50531302_68_dialog_content = "Thank goodness we made it in time... Urk...!",
  ui_story_5053_50531401_1_dialog_content = "So you're saying this White Demon has been playing us for fools all along.",
  ui_story_5053_50531401_2_dialog_content = "And that she and the Dark Angel are both part of Lady Joshua, but they can't come to terms with each other.",
  ui_story_5053_50531401_3_dialog_content = "So her plan is to kill us all, absorb our Lumina, and free herself with it...",
  ui_story_5053_50531401_4_dialog_content = "Even though it sounds so unbelievable, I think I understand her circumstances.",
  ui_story_5053_50531401_5_dialog_content = "The head-splitting pain, the fear of her other self...",
  ui_story_5053_50531401_6_dialog_content = "But even though we're so different, Baba Yaga and I are one and the same person.",
  ui_story_5053_50531401_7_dialog_content = "And if I could learn to coexist with her, then surely mother could...",
  ui_story_5053_50531401_8_dialog_content = "Do you think we still have a chance of convincing the White Demon to give up her crazy scheme, PlayerName?",
  ui_story_5053_50531401_9_dialog_content = "Well... I think only the real Lady Joshua would know that.",
  ui_story_5053_50531401_10_dialog_content = "All I know is that the Crystal of Eternal Memory is nearly out of Lumina.",
  ui_story_5053_50531401_11_dialog_content = "This is our final chance to get out of here. We can't waste any time overthinking things.",
  ui_story_5053_50531401_12_dialog_content = "Please forgive me, but I was unable to subdue the other Lady Joshua.",
  ui_story_5053_50531401_13_dialog_content = "A guard just alerted me that the situation in the central square is now under control.",
  ui_story_5053_50531401_14_dialog_content = "However, the dragon continues to be a relentless threat. Our forces won't last much longer against an unbeatable enemy like this.",
  ui_story_5053_50531401_15_dialog_content = "Thank you for your help, Ms. Rot. You may leave the rest to us.",
  ui_story_5053_50531401_16_dialog_content = "I'm afraid I must refuse.",
  ui_story_5053_50531401_17_dialog_content = "My duty is to protect House Schwartz and all of Lumopolis.",
  ui_story_5053_50531401_18_dialog_content = "Whether or not I'm just an illusion has no bearing on my duty. I am, and always will be, Ms. Rot.",
  ui_story_5053_50531401_19_dialog_content = "Even in the face of such a jarring existential crisis, your composure remains unshakeable.",
  ui_story_5053_50531401_20_dialog_content = "Heheh... Honestly, this realization has given me a sense of relief.",
  ui_story_5053_50531401_21_dialog_content = "Now that I know there is no future for myself, I have no reason to constantly worry about it.",
  ui_story_5053_50531401_22_dialog_content = "If anyone is suffering from the truth right now, it would be Mr. Caleb.",
  ui_story_5053_50531401_23_dialog_content = "Joshua... Never wanted anyone to know the truth about her past.",
  ui_story_5053_50531401_24_dialog_content = "On the one hand, revealing her past would only invite more criticism.",
  ui_story_5053_50531401_25_dialog_content = "However, I believe the real reason was that she didn't have the heart to confess it to her little brother.",
  ui_story_5053_50531401_26_dialog_content = "In a way, the strength and kindness she discovered over the years also gave rise to her greatest weakness.",
  ui_story_5053_50531401_27_dialog_content = "I know what you mean to say. For Lady Joshua to have grown and experienced so many emotions is a positive thing.",
  ui_story_5053_50531401_28_dialog_content = "But sometimes, a problem can only be resolved by communicating openly and sincerely, even when doing so is terrifying.",
  ui_story_5053_50531401_29_dialog_content = "When Lady Joshua finally reawakens in the real world, I must ask that you share these sincere thoughts with her as well.",
  ui_story_5053_50531401_30_dialog_content = "Otherwise, she may become so enraged that she loses consciousness once again.",
  ui_story_5053_50531401_31_dialog_content = "... I will remember to do so.",
  ui_story_5053_50531401_32_dialog_content = "Uh, Lord Schwartz? Are you and Ms. Rot done talking yet? We still need to talk about the next step of our plan.",
  ui_story_5053_50531401_33_dialog_content = "Certainly.",
  ui_story_5053_50531401_34_dialog_content = "... Wait, where's Caleb? Is he feeling better yet?",
  ui_story_5053_50531401_35_dialog_content = "Leave him be for now.",
  ui_story_5053_50531401_36_dialog_content = "...",
  ui_story_5053_50531401_37_dialog_content = "Are you... really my sister...?",
  ui_story_5053_50531401_38_dialog_content = "—!",
  ui_story_5053_50531401_39_dialog_content = "Why do you hide from me?",
  ui_story_5053_50531401_40_dialog_content = "Was the other Joshua telling the truth? Is it possible that... you never truly saw me as a family?",
  ui_story_5053_50531401_41_dialog_content = "... No...",
  ui_story_5053_50531401_42_dialog_content = "Caleb... I'm... Scared...",
  ui_story_5053_50531401_43_dialog_content = "Scared?",
  ui_story_5053_50531401_44_dialog_content = "Caleb... loved me... trusted me...",
  ui_story_5053_50531401_45_dialog_content = "My chest... hurts... the pressure... can't breathe...",
  ui_story_5053_50531401_46_dialog_content = "Father.. let go... died... to protect me... All... my fault...",
  ui_story_5053_50531401_47_dialog_content = "What do you mean...?",
  ui_story_5053_50531401_48_dialog_content = "The other part of you said that Father committed suicide in order to preserve the embers of vengeance.",
  ui_story_5053_50531401_49_dialog_content = "Yet, you're saying he let it all go... I can't tell what is the truth anymore.",
  ui_story_5053_50531401_50_dialog_content = "You posed as my sister for all those years, just so you could assassinate Schwartz's father.",
  ui_story_5053_50531401_51_dialog_content = "You raised me and took care of me like a real sister... No, like a mother.",
  ui_story_5053_50531401_52_dialog_content = "All those years of putting up with me... The stress must have been unbearable.",
  ui_story_5053_50531401_53_dialog_content = "... But it doesn't matter now, Joshua. Your happiness will always be my priority, now and forever.",
  ui_story_5053_50531401_54_dialog_content = "Once we return to reality, if you truly don't see me as your brother... Then I won't bother you ever again. I want you to live freely and without regret, just as you've always wanted.",
  ui_story_5053_50531401_55_dialog_content = "No... Please... don't leave me... Caleb...",
  ui_story_5053_50531401_56_dialog_content = "I was wrong... to lie... but... I was scared...",
  ui_story_5053_50531401_57_dialog_content = "Scared... you... would hate me...",
  ui_story_5053_50531401_58_dialog_content = "...",
  ui_story_5053_50531401_59_dialog_content = "I could never hate you, Joshua.",
  ui_story_5053_50531401_60_dialog_content = "You're the most beautiful and gentle sister anyone could ever ask for.",
  ui_story_5053_50531401_61_dialog_content = "How could I possibly resent you in any way?",
  ui_story_5053_50531401_62_dialog_content = "Alright, so let me go over everything one last time.",
  ui_story_5053_50531401_63_dialog_content = "As it stands, we've put a stop to the White Demon's previous plan to kill us.",
  ui_story_5053_50531401_64_dialog_content = "With nowhere else to go, there's a good chance she's going to use the dragon and those mind-controlled people to launch a desperate, final attack.",
  ui_story_5053_50531401_65_dialog_content = "Even though we have the numbers advantage now, and young Schwartz is still fending off the dragon...",
  ui_story_5053_50531401_66_dialog_content = "He and his forces won't be able to fight at their full strength, not with how little Lumina is left in the Crystal of Eternal Memory.",
  ui_story_5053_50531401_67_dialog_content = "Not only that, there are only a few hours left in the day.",
  ui_story_5053_50531401_68_dialog_content = "We need a simple, effective method that will let us deal with all of the White Demon's pawns in the shortest amount of time possible.",
  ui_story_5053_50531401_69_dialog_content = "It's the only way we'll be able to capture her.",
  ui_story_5053_50531401_70_dialog_content = "Does that Crystal of Eternal Memory have any other functions we can use, Jakine? Can we use it to manipulate the other illusions, just like the White Demon?",
  ui_story_5053_50531401_71_dialog_content = "Hmm... Nope! With how little Lumina it has left, the Crystal of Eternal Memory can't be used for anything other than sustaining the world around us.",
  ui_story_5053_50531401_72_dialog_content = "Also, this Crystal of Eternal Memory is just a failsafe device.",
  ui_story_5053_50531401_73_dialog_content = "It should never have been used so much in the first place... We've already broken enough rules ever since we got our hands on it.",
  ui_story_5053_50531401_74_dialog_content = "But if I managed to put together an even better incantation than last time...!",
  ui_story_5053_50531401_75_dialog_content = "No, Jakine. Our situation is too dire for us to resort to another one of your improvised spells.",
  ui_story_5053_50531401_76_dialog_content = "Ehehehe... Got it.",
  ui_story_5053_50531401_77_dialog_content = "That won't be necessary.",
  ui_story_5053_50531401_78_dialog_content = "All we need to do is let them destroy themselves.",
  ui_story_5053_50531401_79_dialog_content = "Welcome back, Caleb! Are you all done crying now?",
  ui_story_5053_50531401_80_dialog_content = "I wasn't crying! How dare you treat me like a child!",
  ui_story_5053_50531401_81_dialog_content = "What do you mean by that, Caleb? Why would they destroy themselves if they were all under the White Demon's control?",
  ui_story_5053_50531401_82_dialog_content = "It's simple, really.",
  ui_story_5053_50531401_83_dialog_content = "By disrupting the balance of Lumina in their bodies, they will lose their ability to control themselves. Painfully, I might add.",
  ui_story_5053_50531401_84_dialog_content = "The \"balance of Lumina\"? I've never heard of anything like that before.",
  ui_story_5053_50531401_85_dialog_content = "Hmph, ordinary Aurorians could never understand, but I believe our Caelestite friend knows exactly what I'm talking about. Isn't that right?",
  ui_story_5053_50531401_86_dialog_content = "M-Me? Uh... Well, I have noticed something different about their light trails...",
  ui_story_5053_50531401_87_dialog_content = "Your dubious response is... Quite disappointing.",
  ui_story_5053_50531401_88_dialog_content = "<size=30>PlayerName, I felt Caleb had been getting more hostile toward us before. Maybe he's actually a rotten person?</size>",
  ui_story_5053_50531401_89_dialog_content = "<size=30>Well, no comment...</size>",
  ui_story_5053_50531401_90_dialog_content = "You two! No chatting while class is in session!",
  ui_story_5053_50531401_91_dialog_content = "Enough fooling around, Caleb. Tell us your plan.",
  ui_story_5053_50531401_92_dialog_content = "I can prepare a certain type of drug, a potion that can destabilize the user's Lumina. Think of it as a poison that directly targets Lumina.",
  ui_story_5053_50531401_93_dialog_content = "Everything within the Crystal of Eternal Memory was created through a combination of Joshua's Lumina and Lake Mirror's water.",
  ui_story_5053_50531401_94_dialog_content = "As a result, this drug should prove highly effective against our enemies.",
  ui_story_5053_50531401_95_dialog_content = "But with so few ingredients on hand, I propose that we use it to combat the dragon.",
  ui_story_5053_50531401_96_dialog_content = "The White Demon's mind-controlled puppets are nothing more than pernicious ants. If we bring the dragon down upon them...",
  ui_story_5053_50531401_97_dialog_content = "The pain induced by the drug will cause it the trample and writhe on the ground, crushing our adversaries in the process.",
  ui_story_5053_50531401_98_dialog_content = "Aha! So, in other words, if we manage to feed the poison to the dragon, it'll come tumbling down on their mindless heads!",
  ui_story_5053_50531401_99_dialog_content = "... In a manner of speaking, yes.",
  ui_story_5053_50531401_100_dialog_content = "I must say, your plan is quite indicative of your usual style. You've always been fond of simple yet sinister tricks such as this.",
  ui_story_5053_50531401_101_dialog_content = "I'm surprised you still remember that, my lord. Was my cup of tea really so memorable?",
  ui_story_5053_50531401_102_dialog_content = "(Wait... Did Caleb poison Lord Schwartz in the past?!)",
  ui_story_5053_50531401_103_dialog_content = "<size=30>You really aren't a good person after all, Caleb!</size>",
  ui_story_5053_50531401_104_dialog_content = "Pffft... Hehehe...",
  ui_story_5053_50531401_105_dialog_content = "Stop laughing, Mia.",
  ui_story_5053_50531401_106_dialog_content = "I-I'm sorry, I couldn't help it... Wait, I didn't mean it like that...",
  ui_story_5053_50531401_107_dialog_content = "I only have enough ingredients to make a single potion. I'll need someone powerful to subdue the dragon long enough for me to administer the potion. Someone like you.",
  ui_story_5053_50531401_108_dialog_content = "H-Huh? Me...?!",
  ui_story_5053_50531401_109_dialog_content = "Yes, you. Now follow me.",
  ui_story_5053_50531401_110_dialog_content = "W-Wait, uncle...!",
  ui_story_5053_50531401_111_dialog_content = "There he goes, running off to do his own thing again! Think we should follow them?",
  ui_story_5053_50531401_112_dialog_content = "Leave the dragon to Caleb. I believe in him, as well as Mia.",
  ui_story_5053_50531401_113_dialog_content = "Lord Schwartz...",
  ui_story_5053_50531401_114_dialog_content = "According to you, I always manage to survive the White Demon's schemes until the very end, but I can never change the outcome.",
  ui_story_5053_50531401_115_dialog_content = "You young heroes, on the other hand, are far more capable of shaping the future than I could ever be.",
  ui_story_5053_50531401_116_dialog_content = "I always thought I could protect everything with my own two hands... But it appears the time has come to let go of my stubborn pride.",
  ui_story_5053_50531401_117_dialog_content = "So should we just stay here for now?",
  ui_story_5053_50531401_118_dialog_content = "Yes, Jakine. We will remain here to gather our wits and our strength.",
  ui_story_5053_50531401_119_dialog_content = "Knowing the White Demon, she will appear before us for one last battle after her trump card has been defeated.",
  ui_story_5053_50531401_120_dialog_content = "That's the kind of tenacious opponent we face.",
  ui_story_5053_50531401_121_dialog_content = "Also...",
  ui_story_5053_50531401_122_dialog_content = "...",
  ui_story_5053_50531401_123_dialog_content = "I still need to convince her to leave with us.",
  ui_story_5053_50531401_125_dialog_content = "So we find ourselves here once again. You and me, standing at this table in the evening.",
  ui_story_5053_50531401_126_dialog_content = "...",
  ui_story_5053_50531401_127_dialog_content = "The last time this happened, I tried to change the outcome of our falling out by pretending to be my younger self.",
  ui_story_5053_50531401_128_dialog_content = "I said that I didn't wish to hurt you anymore, but in this illusory world, my actions were in pursuit of self-satisfaction and nothing more.",
  ui_story_5053_50531401_129_dialog_content = "Ironically enough, you were standing before me the entire time, witnessing me at my worst. It's little wonder that you're so angry with me.",
  ui_story_5053_50531401_130_dialog_content = "D... Daniel...",
  ui_story_5053_50531401_131_dialog_content = "You were right. This is all my fault, and your vendetta against me is perfectly justified. However, you cannot kill me just yet.",
  ui_story_5053_50531401_132_dialog_content = "These children are innocent, and don't deserve to die in this place.",
  ui_story_5053_50531401_133_dialog_content = "So please, help us capture your other half so we may escape. What do you say?",
  ui_story_5053_50531401_134_dialog_content = "Children are... the future... We must... protect the future...",
  ui_story_5053_50531401_135_dialog_content = "Then we're in agreement. Thank you, Joshua... Thank you for believing in me once more.",
  ui_story_5053_50531401_136_dialog_content = "...",
  ui_story_5053_50531401_137_dialog_content = "Caleb and Mia only just left. We should try to regain our strength for now.",
  ui_story_5053_50531401_138_dialog_content = "Do you still remember that song, Joshua?",
  ui_story_5053_50531401_139_dialog_content = "Yes... A song from... Lower Lumopolis... about... happy life...",
  ui_story_5053_50531401_140_dialog_content = "Yes, that very song. To tell the truth, I prepared a gift for you twelve years ago.",
  ui_story_5053_50531401_141_dialog_content = "But in the heat of the moment, I forgot to give it to you. If I remember correctly... It should be right here.",
  ui_story_5053_50531401_142_dialog_content = "A... Record?",
  ui_story_5053_50531401_143_dialog_content = "That's right. I had someone record a dance version of that very same song. Would you like to listen to it? There's a record player right here, after all.",
  ui_story_5053_50531401_144_dialog_content = "<color=#e8d9bb>...♪</color>",
  ui_story_5053_50531401_145_dialog_content = "...!",
  ui_story_5053_50531401_146_dialog_content = "I'm glad to see you enjoy it, Joshua.",
  ui_story_5053_50531401_147_dialog_content = "But it would be a waste to simply listen to such a wonderful song.",
  ui_story_5053_50531401_148_dialog_content = "Well, my fair lady? May I have this dance?",
  ui_story_5053_50531401_149_dialog_content = "...",
  ui_story_5053_50531401_150_dialog_content = "...",
  ui_story_5053_50531401_151_dialog_content = "Da... Daniel...",
  ui_story_5053_50531401_152_dialog_content = "Yes?",
  ui_story_5053_50531401_153_dialog_content = "Is everyone... Doing well...?",
  ui_story_5053_50531401_154_dialog_content = "...Yes, quite well.",
  ui_story_5053_50531401_155_dialog_content = "Carleen is now a Guard Captain of Lumopolis, and commands a team of exemplary subordinates. Not only that, she has also made many, trustworthy friends.",
  ui_story_5053_50531401_156_dialog_content = "Mia continues to live under Istvan's care and guidance. Her condition has improved greatly; I hear she can even go outside and play during the day now.",
  ui_story_5053_50531401_157_dialog_content = "As for Caleb... He seems to be doing quite well for himself in the Dawn Academy. I would wager that he misses you more dearly than anyone else in the world.",
  ui_story_5053_50531401_158_dialog_content = "What about... You...?",
  ui_story_5053_50531401_159_dialog_content = "Me?",
  ui_story_5053_50531401_160_dialog_content = "My time is over now, Joshua.",
  ui_story_5053_50531401_161_dialog_content = "I was so helpless in the past, and I made more mistakes than I could count, but now. Now, our children stand upon my shoulders, reaching greater heights than I will ever know.",
  ui_story_5053_50531401_162_dialog_content = "All that remains for me to do is stand in this place, supporting them as they strive for a brighter future.",
  ui_story_5053_50531401_163_dialog_content = "The ideal future that you and I have always dreamed of.",
  ui_story_5053_50531401_164_dialog_content = "When we return, I can arrange for you to recover in the safety and privacy of Caleb's home.",
  ui_story_5053_50531401_165_dialog_content = "Afterward, I will have Veronica return to accompany you, and share the good news with Carleen. Soon, our family will be whole again.",
  ui_story_5053_50531401_166_dialog_content = "Only now... Well, as you can see, I've grown rather old. I may be even less worthy of your companionship now, but I would be grateful if you allowed me to visit from time to time. Would that be alright?",
  ui_story_5053_50531401_167_dialog_content = "Want... Home...",
  ui_story_5053_50531401_168_dialog_content = "Joshua?",
  ui_story_5053_50531401_169_dialog_content = "I want... go home...",
  ui_story_5053_50531401_170_dialog_content = "I know. I promise we'll go home together.",
  ui_story_5053_50531401_171_dialog_content = "Joshua... Do you regret our matrimony?",
  ui_story_5053_50531401_172_dialog_content = "To have kept so much anger and pain hidden in your heart... Do you regret choosing me to be your husband?",
  ui_story_5053_50531401_173_dialog_content = "You taught me... happiness and love.",
  ui_story_5053_50531401_174_dialog_content = "Hatred... is the other side... of love.",
  ui_story_5053_50531401_175_dialog_content = "Hatred is... painful... but it was... born from love... So I have... no regrets.",
  ui_story_5053_50531401_176_dialog_content = "...",
  ui_story_5053_50531401_177_dialog_content = "Is that so?",
  ui_story_5053_50531401_178_dialog_content = "I see...",
  ui_story_5053_50531401_179_dialog_content = "Points five and six are now armed...",
  ui_story_5053_50531401_180_dialog_content = "Good. Now the only thing missing is a detonator, and our bombs will be ready to lure the dragon.",
  ui_story_5053_50531401_181_dialog_content = "How are things proceeding with the explosives, Mr. Caleb? Do you require my assistance?",
  ui_story_5053_50531401_182_dialog_content = "Not at all. I've already finished assembling them.",
  ui_story_5053_50531401_183_dialog_content = "In such a short amount of time, no less. Very impressive, sir.",
  ui_story_5053_50531401_184_dialog_content = "No need for flattery amongst relatives, Ms. Rot. Besides, if anyone is deserving of praise, it's you.",
  ui_story_5053_50531401_185_dialog_content = "Without you, these guards would never have allowed us to make such elaborate preparations.",
  ui_story_5053_50531401_186_dialog_content = "I'm simply performing my duties. Are you sure neither of you requires my help?",
  ui_story_5053_50531401_187_dialog_content = "As an illusion created by the Crystal of Eternal Memory, I am far better suited to keeping the enemy at bay.",
  ui_story_5053_50531401_188_dialog_content = "Please don't say that, Ms. Rot...",
  ui_story_5053_50531401_189_dialog_content = "However, I do have something important I would like to ask of you.",
  ui_story_5053_50531401_190_dialog_content = "I am at your command, your highness.",
  ui_story_5053_50531401_191_dialog_content = "Could you please stay by Carleen's side in my place? She's all alone right now, and I'm sure it would put her mind at ease.",
  ui_story_5053_50531401_192_dialog_content = "As you wish. But first, I must ask...",
  ui_story_5053_50531401_193_dialog_content = "Why are you so concerned with our safety, despite the fact that none of us are real?",
  ui_story_5053_50531401_194_dialog_content = "No, Ms. Rot... You're all still very real to me. Each of you is a reflection of someone that I deeply care about. You share their faces, their personalities... Even their memories.",
  ui_story_5053_50531401_195_dialog_content = "Even though you only exist within this crystal, I still care for you in exactly the same way.",
  ui_story_5053_50531401_196_dialog_content = "In my eyes, our concern for one another is what makes our interactions real.",
  ui_story_5053_50531401_197_dialog_content = "Besides, I refuse to see others as unimportant, or even expendable...",
  ui_story_5053_50531401_198_dialog_content = "I worry that if I do, I'll lose sight of myself as a person.",
  ui_story_5053_50531401_199_dialog_content = "You have always resembled your mother, Princess Veronica, but right now... I can hardly tell you apart.",
  ui_story_5053_50531401_200_dialog_content = "I-Is that so...?",
  ui_story_5053_50531401_201_dialog_content = "Preparations are finally complete! It's time, Mia!",
  ui_story_5053_50531401_202_dialog_content = "Understood! Please take good care of Carleen, Ms. Rot!",
  ui_story_5053_50531401_203_dialog_content = "It seems my prayers have been answered. The future of the Schwartz family is as bright as the sun itself.",
  ui_story_5053_50531401_204_dialog_content = "*Inhales* Whew...",
  ui_story_5053_50531401_205_dialog_content = "As soon as I push this button, the bombs will detonate in a sequence, which should draw the dragon to our location in under twenty seconds.",
  ui_story_5053_50531401_206_dialog_content = "Are you ready, Mia?",
  ui_story_5053_50531401_207_dialog_content = "I-I think so...",
  ui_story_5053_50531401_208_dialog_content = "Sigh... After everything we've been through, how are you still so unconfident?",
  ui_story_5053_50531401_209_dialog_content = "Get it together!",
  ui_story_5053_50531401_210_dialog_content = "S-Sorry! Um... May I ask you something, uncle?",
  ui_story_5053_50531401_211_dialog_content = "Make it brief.",
  ui_story_5053_50531401_212_dialog_content = "Why did you choose me to help you with this part of the plan?",
  ui_story_5053_50531401_213_dialog_content = "If you needed someone powerful, Father or Ms. Rot would have been a better choice than me.",
  ui_story_5053_50531401_214_dialog_content = "Oh? And what makes you say that?",
  ui_story_5053_50531401_215_dialog_content = "Our adventure thus far has given me a clear grasp of your power, Mia. In addition, I've been told that you are capable of summoning a Lumina familiar. Is that true?",
  ui_story_5053_50531401_216_dialog_content = "If so, you have the highest mobility out of any of us, which makes you a perfect candidate for this plan.",
  ui_story_5053_50531401_217_dialog_content = "M-M-My familiar?!",
  ui_story_5053_50531401_218_dialog_content = "But I've only summoned Hippoca a few times until now! I'm still not very good at riding him...",
  ui_story_5053_50531401_219_dialog_content = "\"A few times,\" you say? Why on earth would you squander such a rare and valuable gift?!",
  ui_story_5053_50531401_220_dialog_content = "W-Well... Hippoca's looks can be a little unsettling. When I first summoned him, everyone was scared of Hippoca and said that his existence was a terrible omen.",
  ui_story_5053_50531401_221_dialog_content = "B-But I don't feel that way about him anymore! I won't doubt myself because of what other people say ever again!",
  ui_story_5053_50531401_222_dialog_content = "Still, the truth is that Hippoca and I have only fought together a few times... Which is why I don't feel very confident...",
  ui_story_5053_50531401_223_dialog_content = "If we fail, then everyone's lives will...",
  ui_story_5053_50531401_224_dialog_content = "Ah... I see. It was Schwartz's doing, wasn't it?",
  ui_story_5053_50531401_225_dialog_content = "...",
  ui_story_5053_50531401_226_dialog_content = "He forbid you from summoning your familiar, all because of those gossiping nobles.",
  ui_story_5053_50531401_227_dialog_content = "Did he honestly think that you would be saved from criticism by preventing you from summoning Hippoca?",
  ui_story_5053_50531401_228_dialog_content = "Huh? N-No uncle, father was just trying to protect me... Wasn't he?",
  ui_story_5053_50531401_229_dialog_content = "<size=45>That fool! That complete and utter fool!</size>",
  ui_story_5053_50531401_230_dialog_content = "What...?!",
  ui_story_5053_50531401_231_dialog_content = "Listen to me, Mia! Those idiotic nobles only said that because they were jealous of you! The more extraordinary you are, the more they try to drag you through the muck!",
  ui_story_5053_50531401_232_dialog_content = "Which is why you shouldn't listen to them or your father! If they tell you not to do something, that's the reason why you should do it! The life of a genius is fraught with obstacles!!",
  ui_story_5053_50531401_233_dialog_content = "\"The life of a genius\"?! B-But I still think we should hear others out, especially our family...",
  ui_story_5053_50531401_234_dialog_content = "Not true, Mia. That's just what they want you to think, so they can continue holding you back. Let me show you the way.",
  ui_story_5053_50531401_235_dialog_content = "You must unleash every ounce of your power, right here and now! Let it flow through every cell in your body, and release it all at once!",
  ui_story_5053_50531401_236_dialog_content = "Huh...?!",
  ui_story_5053_50531401_237_dialog_content = "Only the most powerful medicine will cure you of that infuriating submissiveness, Mia.",
  ui_story_5053_50531401_238_dialog_content = "And only by understanding the full extent of your power will you learn to control it.",
  ui_story_5053_50531401_239_dialog_content = "The full extent of my power...",
  ui_story_5053_50531401_240_dialog_content = "(People tend to fear what they don't understand. In that respect, I'm no different than anyone else.)",
  ui_story_5053_50531401_241_dialog_content = "(Uncle's methods might seem a little extreme... But he's right. I need to know the true depths of my own strength.)",
  ui_story_5053_50531401_242_dialog_content = "Relax, I promise to keep you safe while you do so. You didn't think I was just another puny scholar, did you?",
  ui_story_5053_50531401_243_dialog_content = "Th-The thought never crossed my mind. Very well, uncle... I'll do my best!",
  ui_story_5053_50531401_244_dialog_content = "That's the spirit!",
  ui_story_5053_50531401_245_dialog_content = "Now prepare for battle!",
  ui_story_5053_50531501_1_dialog_content = "<color=#e8d9bb>Roar—</color>",
  ui_story_5053_50531501_2_dialog_content = "What a monstrous roar! We could hear it all the way over here!",
  ui_story_5053_50531501_3_dialog_content = "It's been three minutes since the first explosion. Two different-colored flames are battling it out in the sky over there.",
  ui_story_5053_50531501_4_dialog_content = "The blue one is Mia, and the red one is the dragon...",
  ui_story_5053_50531501_5_dialog_content = "Look! The red flame is going down! Mia and Caleb did it!",
  ui_story_5053_50531501_6_dialog_content = "It looks like we came at just the right time.",
  ui_story_5053_50531501_7_dialog_content = "Lord Schwartz! I was just about to come and tell you!",
  ui_story_5053_50531501_8_dialog_content = "So are you two ready to negotiate?",
  ui_story_5053_50531501_9_dialog_content = "Yes, and now that the tables have turned...",
  ui_story_5053_50531501_10_dialog_content = "All that remains is to see where the enemy queen makes her final move.",
  ui_story_5053_50531501_11_dialog_content = "... Here...",
  ui_story_5053_50531501_12_dialog_content = "Huh? What do you mean, \"here\"?",
  ui_story_5053_50531501_13_dialog_content = "Here... She's here...!",
  ui_story_5053_50531501_14_dialog_content = "Th-The ground is shaking and splitting apart!! Is this the White Demon's doing?!",
  ui_story_5053_50531501_15_dialog_content = "PlayerName!",
  ui_story_5053_50531501_16_dialog_content = "Blast! What in the world is happening?!",
  ui_story_5053_50531501_17_dialog_content = "Mia? Caleb? What are you two doing back so soon? Didn't you just finish slaying the dragon?",
  ui_story_5053_50531501_18_dialog_content = "No, and we're not entirely sure what happened either.",
  ui_story_5053_50531501_19_dialog_content = "When the dragon fell out of the sky, the central square started warping and breaking apart. Aside from my uncle and myself...",
  ui_story_5053_50531501_20_dialog_content = "Everyone in the area turned into flashes of white light and flew up into the sky.",
  ui_story_5053_50531501_21_dialog_content = "When we tried to escape through someone's front door, we suddenly found ourselves back at the mansion.",
  ui_story_5053_50531501_22_dialog_content = "Zzzzz...",
  ui_story_5053_50531501_23_dialog_content = "Wake up, Jakine! Something terrible is happening!",
  ui_story_5053_50531501_24_dialog_content = "Zzzzz... Huh? Who's there?! Keep your hands off my crystal!!!",
  ui_story_5053_50531501_25_dialog_content = "H-Hey... What happened to the Crystal of Eternal Memory?!",
  ui_story_5053_50531501_26_dialog_content = "Wh... Why...",
  ui_story_5053_50531501_27_dialog_content = "Why have you chosen to side with that disgusting creature...?",
  ui_story_5053_50531501_28_dialog_content = "Mother... Your face...",
  ui_story_5053_50531501_29_dialog_content = "Look at the cracks appearing on her face! They're the same color as the Dark Angel!",
  ui_story_5053_50531501_30_dialog_content = "Why didn't you choose me...?",
  ui_story_5053_50531501_31_dialog_content = "Why does no one understand the importance of my ideals...?",
  ui_story_5053_50531501_32_dialog_content = "<size=45>WHY?!?</size>",
  ui_story_5053_50531501_33_dialog_content = "Sh-She's turning into the Dark Angel!!",
  ui_story_5053_50531501_34_dialog_content = "So Mia was right! The two of them are the same...",
  ui_story_5053_50531501_35_dialog_content = "Guess we don't have time to discuss her surrender over tea and cookies! Let's get her!",
  ui_story_5053_50531501_36_dialog_content = "M-Mother... I'm sorry!",
  ui_story_5053_50531501_37_dialog_content = "Joshua...",
  ui_story_5053_50531501_38_dialog_content = "Are you hesitating now of all times, Caleb?",
  ui_story_5053_50531501_39_dialog_content = "Even my elder daughter is showing more courage than you right now.",
  ui_story_5053_50531501_40_dialog_content = "Save it, Schwartz! When it comes to my sister's matters, you alone have no right to blame anyone!",
  ui_story_5053_50531501_41_dialog_content = "Just wait until we're back in the real world!",
  ui_story_5053_50531501_42_dialog_content = "(Foolish boy. Even after all these years, you still can't control your temper.)",
  ui_story_5053_50531501_43_dialog_content = "...",
  ui_story_5053_50531502_1_dialog_content = "Urgh...!!",
  ui_story_5053_50531502_2_dialog_content = "Jakine!",
  ui_story_5053_50531502_3_dialog_content = "Way ahead of you!!",
  ui_story_5053_50531502_4_dialog_content = "S-Stay back...",
  ui_story_5053_50531502_5_dialog_content = "It's over, Joshua.",
  ui_story_5053_50531502_6_dialog_content = "Don't come any closer...!",
  ui_story_5053_50531502_7_dialog_content = "Struggling will only make it more painful.",
  ui_story_5053_50531502_8_dialog_content = "Stay away from me!!!",
  ui_story_5053_50531502_9_dialog_content = "Lord Schwartz!",
  ui_story_5053_50531502_10_dialog_content = "<size=45>The Sovereign's Blade—</size>",
  ui_story_5053_50531502_11_dialog_content = "Uwaaaaa!!",
  ui_story_5053_50531502_12_dialog_content = "It's all... your fault...",
  ui_story_5053_50531502_13_dialog_content = "...",
  ui_story_5053_50531502_14_dialog_content = "You... Made me weak...",
  ui_story_5053_50531502_15_dialog_content = "Veronica and Carleen... Caleb and Blanc... And Schwartz.",
  ui_story_5053_50531502_16_dialog_content = "They're traitorous scum, every single one of them!!",
  ui_story_5053_50531502_17_dialog_content = "How could you surrender your ideals to them?! You worthless, broken fool—",
  ui_story_5053_50531502_18_dialog_content = "Mia, help me finish this. We can't let my sister continue hurting herself.",
  ui_story_5053_50531502_19_dialog_content = "Okay...",
  ui_story_5053_50531502_20_dialog_content = "Wait! Don't go near her!",
  ui_story_5053_50531502_21_dialog_content = "If this is how it must end... Then in the name of vengeance...",
  ui_story_5053_50531502_22_dialog_content = "I swear to annihilate every last one of you...",
  ui_story_5053_50531502_23_dialog_content = "...Huh? What's with this wind?",
  ui_story_5053_50531502_24_dialog_content = "Look! She's starting to absorb the Lumina within the Crystal of Eternal Memory!",
  ui_story_5053_50531502_25_dialog_content = "Is she... Trying to take us down with her?!",
  ui_story_5053_50531502_26_dialog_content = "Jakine, prepare to get us out of here! The rest of you, help me subdue her!",
  ui_story_5053_50531502_27_dialog_content = "What? You mean right now?!",
  ui_story_5053_50531502_28_dialog_content = "You plan on taking my sister back in this state?!",
  ui_story_5053_50531502_29_dialog_content = "If Joshua were to hurt any of you, it would only break her heart.",
  ui_story_5053_50531502_30_dialog_content = "All who oppose my ideals must perish! Die, you filthy traitors!!!",
  ui_story_5053_50531502_31_dialog_content = "Why must it come to this, Mother? Could you truly have this much hatred in your heart towards us...?",
  ui_story_5053_50531502_32_dialog_content = "Vonnie... Don't be sad...",
  ui_story_5053_50531502_33_dialog_content = "Leave this... To me...",
  ui_story_5053_50531502_34_dialog_content = "Mother...?",
  ui_story_5053_50531502_35_dialog_content = "Argh, our attacks are useless! Mia, stop standing around and focus on the battle!",
  ui_story_5053_50531502_36_dialog_content = "... Joshua? Wait, what are you doing?! Don't go near your other half!!",
  ui_story_5053_50531502_37_dialog_content = "... Trust her, Caleb.",
  ui_story_5053_50531502_38_dialog_content = "Let me go, Schwartz! Don't try to stop me! Joshua!!!",
  ui_story_5053_50531502_39_dialog_content = "The wind is too strong for me to open my eyes! I can't use the Crystal of Eternal Memory like this!",
  ui_story_5053_50531502_40_dialog_content = "H-Huh?! I-I-I-I'm getting blown away! Help me—",
  ui_story_5053_50531502_41_dialog_content = "Jakine!",
  ui_story_5053_50531502_42_dialog_content = "Whew, thanks PlayerName... Huh?",
  ui_story_5053_50531502_43_dialog_content = "Don't be afraid... It's all over now.",
  ui_story_5053_50531502_44_dialog_content = "Remember to hold on tightly to each other this time, everyone.",
  ui_story_5053_50531502_45_dialog_content = "J-Joshua...?",
  ui_story_5053_50531502_46_dialog_content = "Mother... It's you...",
  ui_story_5053_50531502_47_dialog_content = "No! Stay back...",
  ui_story_5053_50531502_48_dialog_content = "That's enough. It's time to let everyone go home now.",
  ui_story_5053_50531502_49_dialog_content = "No! Don't come near me... Noooo!!!",
  ui_story_5053_50531502_50_dialog_content = "<size=50>Joshua!!!</size>",
  ui_story_5053_50531601_1_dialog_content = "I've finally found you.",
  ui_story_5053_50531601_2_dialog_content = "It's you...! No! Get away from me!",
  ui_story_5053_50531601_3_dialog_content = "Are you really so disgusted by me?",
  ui_story_5053_50531601_4_dialog_content = "Of course I am! Have you seen yourself in the mirror lately? Who could bear to look at someone so hideous, much less love them?!",
  ui_story_5053_50531601_5_dialog_content = "I see... I used to feel that way as well.",
  ui_story_5053_50531601_6_dialog_content = "But when I saw how much my family and friends cared for me, I began to see past my self-loathing and love myself again.",
  ui_story_5053_50531601_7_dialog_content = "How disgusting...",
  ui_story_5053_50531601_8_dialog_content = "Have you seen yourself in the mirror as well?",
  ui_story_5053_50531601_9_dialog_content = "I have. I used to practice controlling my expressions in front of the mirror for three hours every day. I have no reason to stare at myself any longer.",
  ui_story_5053_50531601_10_dialog_content = "That's right, you have always been such a brave and fearless warrior, one who would do anything to realize her ideals.",
  ui_story_5053_50531601_11_dialog_content = "But everyone has something that they fear, and you are no exception. For you...",
  ui_story_5053_50531601_12_dialog_content = "It was your father dying.",
  ui_story_5053_50531601_13_dialog_content = "?!",
  ui_story_5053_50531601_14_dialog_content = "It was your children and brother learning the truth.",
  ui_story_5053_50531601_15_dialog_content = "Stop it...",
  ui_story_5053_50531601_16_dialog_content = "It was your husband parting ways with you.",
  ui_story_5053_50531601_17_dialog_content = "I said stop it!!!",
  ui_story_5053_50531601_18_dialog_content = "You're the one who fears those things... Not me! You're the one who insists on having those pointless emotions!",
  ui_story_5053_50531601_19_dialog_content = "I don't need them... I don't need family or feelings to realize my ambitions! I only need to sacrifice myself!",
  ui_story_5053_50531601_20_dialog_content = "I know. You only want to live a simple, uncomplicated life. That way, you would never have to experience happiness or the pain of loss.",
  ui_story_5053_50531601_21_dialog_content = "It was the fear of knowing those emotions that made you force me out of your body.",
  ui_story_5053_50531601_22_dialog_content = "Shut up... Enough already...",
  ui_story_5053_50531601_23_dialog_content = "I can never trust them! They don't listen to me... They only wish to betray me...",
  ui_story_5053_50531601_24_dialog_content = "People are not machines. Everyone has their own thoughts and feelings.",
  ui_story_5053_50531601_25_dialog_content = "\"Ever since I stopped you that day, I've thought about it constantly.\"",
  ui_story_5053_50531601_26_dialog_content = "\"Is it wrong of us to entrust our dreams to others?\"",
  ui_story_5053_50531601_27_dialog_content = "Daniel said that once before, remember?",
  ui_story_5053_50531601_28_dialog_content = "He's nothing but a liar...",
  ui_story_5053_50531601_29_dialog_content = "We simply depended too much on him. We forced the weight of our ideals on the shoulders of a single person.",
  ui_story_5053_50531601_30_dialog_content = "You know better than I that a city lord's family could never experience the joys of ordinary life... And yet I never stopped hoping for it.",
  ui_story_5053_50531601_31_dialog_content = "A ruthless assassin, a perfect wife to a city lord...",
  ui_story_5053_50531601_32_dialog_content = "We constantly shifted between identities given to us by other people, but none of them reflected our true selves.",
  ui_story_5053_50531601_33_dialog_content = "I still don't know who we truly are...",
  ui_story_5053_50531601_34_dialog_content = "...",
  ui_story_5053_50531601_35_dialog_content = "But one thing I do know, is that I don't want to lose the people I love. That will always be more important than the truth.",
  ui_story_5053_50531601_36_dialog_content = "So come with me. It's time to stop fighting.",
  ui_story_5053_50531601_37_dialog_content = "Argh! Your hand... It feels like it's covered in thorns! Even the slightest touch hurts so much!",
  ui_story_5053_50531601_38_dialog_content = "And yet, it feels so warm... What is this feeling?",
  ui_story_5053_50531601_39_dialog_content = "So, this is how <color=#FFB400>love</color> feels.",
  ui_story_5053_50531601_40_dialog_content = "Mother! Cough, cough... Mother, where are you?!",
  ui_story_5053_50531601_41_dialog_content = "Over here, Mia! Take my hand!",
  ui_story_5053_50531601_42_dialog_content = "PlayerName... Everyone... Where did Mother go?",
  ui_story_5053_50531601_43_dialog_content = "She... After the explosion...",
  ui_story_5053_50531601_44_dialog_content = "Cast the spell, Jakine.",
  ui_story_5053_50531601_45_dialog_content = "Let go of me! I refuse to leave without my sister!!",
  ui_story_5053_50531601_46_dialog_content = "The ground is crumbling beneath our feet! Hurry!",
  ui_story_5053_50531601_47_dialog_content = "G-Got it!",
  ui_story_5053_50531601_48_dialog_content = "Ad praessence!",
  ui_story_5053_50531601_49_dialog_content = "Let us return to reality!",
  ui_story_5053_50531601_50_dialog_content = "Abracadabra!",
  ui_story_5053_50531601_51_dialog_content = "Joshua! I won't leave you!! Joshua!!!",
  ui_story_5053_50531601_52_dialog_content = "Stubborn brat... Jakine, grab hold of Mia!",
  ui_story_5053_50531601_53_dialog_content = "Wh-What did you say? I can't hear you over the wind!!",
  ui_story_5053_50531601_54_dialog_content = "I can't hold on any longer! PlayerName!!",
  ui_story_5053_50531601_55_dialog_content = "Ahh!!!",
  ui_story_5053_50531601_56_dialog_content = "Then hold onto me.",
  ui_story_5053_50531601_57_dialog_content = "It's you...?",
  ui_story_5053_50531601_58_dialog_content = ".\".. I hope this letter finds you well.\"",
  ui_story_5053_50531601_59_dialog_content = "\"How have you been lately? The others and I are doing well.\"",
  ui_story_5053_50531601_60_dialog_content = "Writing a letter, huh? Who's it for?",
  ui_story_5053_50531601_61_dialog_content = "Bwaaa! J-Jakine! You scared me...",
  ui_story_5053_50531601_62_dialog_content = "Heehee, sorry about that!",
  ui_story_5053_50531601_63_dialog_content = "Good afternoon, PlayerName.",
  ui_story_5053_50531601_64_dialog_content = "Good afternoon! You guys sure got here early, I thought Jakine was gonna be late again!",
  ui_story_5053_50531601_65_dialog_content = "Hey, it's not my fault everyone's dying to know about my work! It's hard to keep a schedule when a mob of people is constantly barraging you with questions...",
  ui_story_5053_50531601_66_dialog_content = "Oh yes, I'm sure being a celebrity at the Dawn Academy must be so awful for Jakine, the \"Visiting Scholar.\"",
  ui_story_5053_50531601_67_dialog_content = "Heehee, don't call me that! You're gonna make me blush...",
  ui_story_5053_50531601_68_dialog_content = "Anyways, have you taken care of things on your end, Mia?",
  ui_story_5053_50531601_69_dialog_content = "Yup! Everything's taken of!",
  ui_story_5053_50531601_70_dialog_content = "Unfortunately, we were so busy that Carleen and I didn't have a chance to say goodbye to each other...",
  ui_story_5053_50531601_71_dialog_content = "Don't worry, you can always come to see her on the Colossus! I'll let you know the next time she's on board.",
  ui_story_5053_50531601_72_dialog_content = "That's okay, we'll see each other again when the time is right.",
  ui_story_5053_50531601_73_dialog_content = "Oh, okay...",
  ui_story_5053_50531601_74_dialog_content = "\"Ever since, much has happened here, with many people making unexpected decisions.\"",
  ui_story_5053_50531601_75_dialog_content = "\"I promised that I would sort out the entire story for you, so let's start from the very beginning.\"",
  ui_story_5053_50531601_76_dialog_content = "\"At the time, we successfully left the <color=#FFB400>Crystal of Eternal Memory</color>\"",
  ui_story_5053_50531601_77_dialog_content = "\"Before we had the time to make sure everyone was alright, Caleb was already out the door and sprinting back to his house.\"",
  ui_story_5053_50531601_78_dialog_content = "\"It wasn't long before we chased after him... Only to find him with Lady Joshua, whom he had kept hidden in his house all these years.\"",
  ui_story_5053_50531601_79_dialog_content = "Mother's eyes just moved...!",
  ui_story_5053_50531601_80_dialog_content = "Hand me that medicine! The one on the left-hand shelf!",
  ui_story_5053_50531601_81_dialog_content = "W-Wait, I'm still looking for the gauze!",
  ui_story_5053_50531601_82_dialog_content = "I have it here.",
  ui_story_5053_50531601_83_dialog_content = "\"After a stressful emergency procedure, Lady Joshua was finally out of critical condition. A few days later, she woke up.\"",
  ui_story_5053_50531601_84_dialog_content = "\"Unfortunately... She had lost all of her memories.\"",
  ui_story_5053_50531601_85_dialog_content = "How... How could this have happened? Was she lying comatose for too long? Or was it that explosion from before?",
  ui_story_5053_50531601_86_dialog_content = "Whatever the case, it appears my sister is no longer suffering from a split personality. But how...?",
  ui_story_5053_50531601_87_dialog_content = "Could it have something to do with the Crystal of Eternal Memory, Jakine?",
  ui_story_5053_50531601_88_dialog_content = "Hm... I wouldn't be so sure.",
  ui_story_5053_50531601_89_dialog_content = "And just what is that supposed to mean? This is serious, you know!",
  ui_story_5053_50531601_90_dialog_content = "\"In order to repair the Crystal of Eternal Memory, as well as help with Lady Joshua's recovery...\"",
  ui_story_5053_50531601_91_dialog_content = "\"Jakine decided to stay in Lumopolis for a while longer, and began conducting research alongside Caleb.\"",
  ui_story_5053_50531601_92_dialog_content = "\"He even gave her the title of \"Visiting Scholar to the Dawn Academy,\" just to make her happy.\"",
  ui_story_5053_50531601_93_dialog_content = "\"I don't think the title carries any real authority, but as long as Jakine doesn't find out...\"",
  ui_story_5053_50531601_94_dialog_content = "Right now, all we know is that, for some reason, the White Demon and the Dark Angel made contact with each other at the very end.",
  ui_story_5053_50531601_94X1_dialog_content = "When both of those conflicting personalities disappeared, Lady Joshua’s mental state returned to normal.",
  ui_story_5053_50531601_95_dialog_content = "As for the Seed, we still have to study it in depth, but we can only count on Caleb for that.",
  ui_story_5053_50531601_96_dialog_content = "Well done, Emissary Jakine of Northland. Thank you for staying in Lumopolis these several days and assisting Caleb in the endeavor.",
  ui_story_5053_50531601_97_dialog_content = "It's my honor! I don't feel like an outsider after everything we've been through together!",
  ui_story_5053_50531601_98_dialog_content = "On top of that, I was supposed to replenish the Crystal of Eternal Memory with water from Lake Mirror, not to break it...",
  ui_story_5053_50531601_99_dialog_content = "Oh, speaking of that, the Crystal is fixed! And now that Lady Joshua is back, you can use it anytime!",
  ui_story_5053_50531601_100_dialog_content = "Thank you. I shall keep it safe to prevent others from entering accidentally.",
  ui_story_5053_50531601_101_dialog_content = "Yeah... But I'm actually a little concerned about Caleb. Since Lady Joshua woke up, he's been around her the whole time!",
  ui_story_5053_50531601_102_dialog_content = "I also heard he wanted to resign from the Dawn Academy to stay home and take care of Lady Joshua full-time... Wonder if he understood the implications at all.",
  ui_story_5053_50531601_103_dialog_content = "How perpetually immature of him... I heard you are looking for a knight named Sharona. Is that true?",
  ui_story_5053_50531601_104_dialog_content = "I am. I see your network's got their noses to the ground, my lord! Would you mind introducing me to her?",
  ui_story_5053_50531601_105_dialog_content = "I am sorry, Jakine, but Sharona left Lumopolis a while back. I am not able to fulfill your request.",
  ui_story_5053_50531601_106_dialog_content = "What? But isn't it her dream to become the mightiest knight...?",
  ui_story_5053_50531601_107_dialog_content = "You can seek her out in Illumina, but never bring up Lumopolis to her.",
  ui_story_5053_50531601_108_dialog_content = "And do not forget that what happened in the Crystal was not real, no matter how strong a bond was formed between you two...",
  ui_story_5053_50531601_109_dialog_content = "It was but an aspiration. A lot has changed over the twelve years.",
  ui_story_5053_50531601_110_dialog_content = "I see... It's okay, as long as we've stayed true to who we are, we can still become pals!",
  ui_story_5053_50531601_111_dialog_content = "Staying true to who you are, you said... You are right.",
  ui_story_5053_50531601_112_dialog_content = "\"I thought Lady Joshua losing her memory would plunge her family into sorrows again.\"",
  ui_story_5053_50531601_113_dialog_content = "\"Except they didn't feel defeated, but quickly rejoiced in the reunion after a brief disappointment.\"",
  ui_story_5053_50531601_114_dialog_content = "\"Good to see the family happy and whole... What a simple yet flawless bond they all shared.\"",
  ui_story_5053_50531601_115_dialog_content = "\"But the <color=#FFB400>City Lord and his family</color> are too much in the limelight for them to ever enjoy the bliss of a normal family.\"",
  ui_story_5053_50531601_116_dialog_content = "<color=#e8d9bb>The Magnus Manor, Home of Caleb</color>",
  ui_story_5053_50531601_117_dialog_content = "I'm back, sis! Check this out. It's the latest fruit tea from Umbraton. Bet you'll love it!",
  ui_story_5053_50531601_118_dialog_content = "Welcome home, uncle.",
  ui_story_5053_50531601_119_dialog_content = "Welcome back. Uh, isn't it a workday today? Aren't you working, Caleb?",
  ui_story_5053_50531601_120_dialog_content = "No work is ever as important as you. I turned in my resignation to the Dawn Academy already. I'll be with you from now on.",
  ui_story_5053_50531601_121_dialog_content = "What, you resigned? Are you going to abandon your career and aspirations over me?",
  ui_story_5053_50531601_122_dialog_content = "Don't put it that way, sis. Nothing's as big as living a happy life with your family.",
  ui_story_5053_50531601_123_dialog_content = "And Mia's been wanting to come back to her family in Lumopolis too. Isn't that right, Mia?",
  ui_story_5053_50531601_124_dialog_content = "Well... Actually, that's what I'm here to talk to Mother about. I'd like to stay in Umbraton.",
  ui_story_5053_50531601_125_dialog_content = "What? Why would you think that now? Did Schwartz browbeat you again?",
  ui_story_5053_50531601_126_dialog_content = "No, it was my own decision. Father is behind it, too.",
  ui_story_5053_50531601_127_dialog_content = "I was weak and hapless in the past, forced to leave and endure hardships...",
  ui_story_5053_50531601_128_dialog_content = "But I also got to see the truth of the world outside Lumopolis and that made me who I am today. However, I feel that's nowhere enough.",
  ui_story_5053_50531601_129_dialog_content = "You ought to know by now that with you taking a lot of time off and me coming and going in a veil, rumors are starting to fly in Lumopolis Gardens.",
  ui_story_5053_50531601_130_dialog_content = "Father couldn't even come here to see Mother because of that... even though we hid her.",
  ui_story_5053_50531601_131_dialog_content = "I do know! And I've been looking for a solution. Worse comes to worst, we'll just move out of Lumopolis!",
  ui_story_5053_50531601_132_dialog_content = "So what if the City Lord's wife revived after all these years...",
  ui_story_5053_50531601_133_dialog_content = "You need real power to challenge Schwartz! Just relying on political muckraking won't do!",
  ui_story_5053_50531601_134_dialog_content = "Yeah, I know none of it is the family's fault, but it's still something we have to endure.",
  ui_story_5053_50531601_135_dialog_content = "I finally understand how Father feels now... Which is why I don't covet my mother's embrace anymore.",
  ui_story_5053_50531601_136_dialog_content = "Since I can't survive under the spotlight in Lumopolis, let me stay in the dark as a shadow.",
  ui_story_5053_50531601_137_dialog_content = "I'll learn as much from Mr. Istvan in Umbraton as possible, growing from a weakling needing protection to a valiant knight.",
  ui_story_5053_50531601_138_dialog_content = "Then it shall be my turn to protect everybody!",
  ui_story_5053_50531601_139_dialog_content = "Why do you feel that way? Don't you think you could trust and depend on me? Talk her out of it, sis!",
  ui_story_5053_50531601_140_dialog_content = "Caleb, I'm <color=#FFB400>someone without memory</color>. I don't have a past, nor do I linger over it.",
  ui_story_5053_50531601_141_dialog_content = "I'm very happy that you found your dream, Mia. Just work hard, baby, and I'm sure you'll have an exciting future ahead of you.",
  ui_story_5053_50531601_142_dialog_content = "Mother... Thank you.",
  ui_story_5053_50531601_143_dialog_content = "You just reminded me, Mia, there's an exciting world out there too. I should see it for myself.",
  ui_story_5053_50531601_144_dialog_content = "Wait a minute, what do you mean by that, sis?",
  ui_story_5053_50531601_145_dialog_content = "\"Yes, after everything she went through, Mia still chose to leave.\"",
  ui_story_5053_50531601_146_dialog_content = "\"She made the decision all on her own, and I sincerely feel happy for her.\"",
  ui_story_5053_50531601_147_dialog_content = "\"Meanwhile, Caleb's resignation was declined.\"",
  ui_story_5053_50531601_148_dialog_content = "\"It seemed he would often come up with all sorts of rash excuses to resign, so the Academy just rejected it out of habit.\"",
  ui_story_5053_50531601_149_dialog_content = "\"For Lady Joshua, she appeared to be inspired and started having her own ideas.\"",
  ui_story_5053_50531601_150_dialog_content = "\"She sneaked out of Lumopolis on a solo journey.\"",
  ui_story_5053_50531601_151_dialog_content = "Thank you, PlayerName, for smuggling me out on the Colossus.",
  ui_story_5053_50531601_152_dialog_content = "Happy to do that. But how come you didn't say goodbye to them?",
  ui_story_5053_50531601_153_dialog_content = "You're smarter than that. They would never let me go if they knew I was leaving.",
  ui_story_5053_50531601_154_dialog_content = "But I must leave, not just to protect them, but as a final lesson to them as a mother and a sister.",
  ui_story_5053_50531601_155_dialog_content = "Have you really lost your memory, Lady Joshua?",
  ui_story_5053_50531601_156_dialog_content = "Of course. Don't you use your Caelestite powers to peek at a lady's secrets now!",
  ui_story_5053_50531601_157_dialog_content = "Okay, then I'll tell them you left when I get back... That's not lying to your superiors, is it?",
  ui_story_5053_50531601_158_dialog_content = "Well, it is to me.",
  ui_story_5053_50531601_159_dialog_content = "What?!",
  ui_story_5053_50531601_160_dialog_content = "Just kidding! Daniel probably figured it out already. We don't need many words to communicate.",
  ui_story_5053_50531601_161_dialog_content = "As for Carleen, she's very much like Daniel... I heard you're very tight with her, so you should know that as well.",
  ui_story_5053_50531601_162_dialog_content = "She seems so strong and competent when she is actually just holding on. It's an open secret everyone knows not to bring up to her.",
  ui_story_5053_50531601_163_dialog_content = "She's certainly capable enough to find any truth she wishes to uncover. If she doesn't...",
  ui_story_5053_50531601_164_dialog_content = "That means she's still not ready to accept the truth.",
  ui_story_5053_50531601_165_dialog_content = "Despite all that speech, though, I have a hidden side to me, as well.",
  ui_story_5053_50531601_166_dialog_content = "If I wasn't implanted, I probably would never realize I've been repressing a dark side in me.",
  ui_story_5053_50531601_167_dialog_content = "Lady Joshua...",
  ui_story_5053_50531601_168_dialog_content = "In addition to accepting others with kindness, it's also necessary to sternly drive them forward. That's another form of showing you care, right?",
  ui_story_5053_50531601_169_dialog_content = "Correct, even a safe haven could be a hindrance to growth.",
  ui_story_5053_50531601_170_dialog_content = "Carleen now needs dependable and like-minded friends more than ever.",
  ui_story_5053_50531601_171_dialog_content = "So, will you continue to progress alongside Carleen, PlayerName?",
  ui_story_5053_50531601_X171_option_content = "Sure, no problem!",
  ui_story_5053_50531601_X172_option_content = "Who, me...?",
  ui_story_5053_50531601_X173_dialog_content = "As a member of a race completely different from us Aurorians, Last Caelestite, I see a brilliant future ahead of you.",
  ui_story_5053_50531601_X174_dialog_content = "Which is also priceless and always overlooked in a close environment like Lumopolis.",
  ui_story_5053_50531601_X175_dialog_content = "I fully believe you can guide Carleen... No, guide more people to a brighter tomorrow.",
  ui_story_5053_50531601_X176_dialog_content = "Your presence and Mia's courage showed me the potential that's out in the world.",
  ui_story_5053_50531601_X177_dialog_content = "Maybe I'll find what I'm really looking for after seeing it.",
  ui_story_5053_50531601_X178_dialog_content = "Then take that enlightenment back to my loved ones someday...",
  ui_story_5053_50531601_X179_dialog_content = "\"Thus, I bid farewell to you and brought the news of your departure back to Lumopolis.\"",
  ui_story_5053_50531601_X180_dialog_content = "\"Some smiled and gave their regards. Some happily accepted it after recovering from the surprise.\"",
  ui_story_5053_50531601_X181_dialog_content = "\"Some couldn't understand it and left in anger. Still, some appeared to have seen it coming.\"",
  ui_story_5053_50531601_X182_dialog_content = "\"After some commotion, everyone accepted it and opted not to interfere with the amnesic's new life.\"",
  ui_story_5053_50531601_X183_dialog_content = "\"As for you keeping up a correspondence with me in secret, it shall be between us two.\"",
  ui_story_5053_50531601_X184_dialog_content = "\"I'll also keep you updated regarding your family as promised.\"",
  ui_story_5053_50531601_172_dialog_content = "\"The next time we meet, I hope we can share our adventures with one another as fellow travelers.\"",
  ui_story_5053_50531601_173_dialog_content = "PlayerName! Put the pen down already!!",
  ui_story_5053_50531601_174_dialog_content = "Bwaaa! Y-You scared me again, Jakine!!",
  ui_story_5053_50531601_175_dialog_content = "Oh no, you can't blame me this time, pal! I'm going back to Northland today, and you and Mia promised to see me off! Now quit pouring your heart out, and come on!",
  ui_story_5053_50531601_176_dialog_content = "W-Wait a second, Jakine! A Courier is supposed to be here any minute to deliver my letter!",
  ui_story_5053_50531601_177_dialog_content = "Besides, you've never cared about being late before...",
  ui_story_5053_50531601_178_dialog_content = "Hey! I heard that!",
  ui_story_5053_50531601_179_dialog_content = "Heehee, guess we'll just have to wait a bit longer.",
